    { "id": "p1-11-1", "core": "core1", "domain": "p1", "objective": "1.1", "term": "Azure SQL Database", "definition": "A fully managed, single-database PaaS offering where Microsoft handles patching, backups, and OS-level maintenance, with the database as the top-level manageable unit.", "scenario": "deploy a new application database with the least possible ongoing patching and maintenance burden", "distractors": ["SQL Managed Instance", "SQL Server on Azure VM", "Elastic pool alone"], "tip": "The MOST managed option, database as the top-level unit — Managed Instance instead gives you an instance-level surface closer to on-premises SQL Server." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-11-1'><title id='dt-p1-11-1'>The database itself is the top-level manageable unit \u2014 least patching/maintenance burden of the three.</title><rect x='16.0' y='30' width='116.0' height='64' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='74.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Database</text><text x='74.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>Azure SQL DB (this one)</text><rect x='142.0' y='30' width='116.0' height='64' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='200.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Instance</text><text x='200.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>Managed Instance</text><rect x='268.0' y='30' width='116.0' height='64' rx='5' fill='var(--surface-3)' stroke='var(--muted)' stroke-width='1.5'/><text x='326.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Full VM</text><text x='326.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>SQL on Azure VM</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The database itself is the top-level manageable unit \u2014 least patching/maintenance</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>burden of the three.</text></svg>"},
    { "id": "p1-11-2", "core": "core1", "domain": "p1", "objective": "1.1", "term": "Azure SQL Managed Instance", "definition": "A fully managed PaaS offering that provides near-complete SQL Server instance-level compatibility, including cross-database queries and SQL Agent, for easier lift-and-shift migrations.", "scenario": "migrate an on-premises SQL Server application that relies on cross-database queries and SQL Agent jobs, with minimal code changes", "distractors": ["Azure SQL Database", "SQL Server on Azure VM", "Elastic pool"], "tip": "Near-complete INSTANCE-LEVEL compatibility, including cross-database queries — Azure SQL Database's single-database model doesn't support that the same way." , "diagram": "<svg viewBox='0 0 380 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-11-2'><title id='dt-p1-11-2'>Instance-level surface: multiple databases share one instance with cross-DB queries and SQL Agent.</title><rect x='20' y='22' width='340' height='90' rx='6' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.8'/><text x='190' y='40' font-size='7.6' fill='var(--blue)' text-anchor='middle' font-weight='700'>Managed Instance</text><rect x='40' y='50' width='90' height='46' rx='4' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='85' y='68' font-size='6.6' fill='var(--text)' text-anchor='middle'>DB A</text><rect x='145' y='50' width='90' height='46' rx='4' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='68' font-size='6.6' fill='var(--text)' text-anchor='middle'>DB B</text><rect x='250' y='50' width='90' height='46' rx='4' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='295' y='68' font-size='6.4' fill='var(--text)' text-anchor='middle'>SQL Agent</text><text x='85' y='84' font-size='6' fill='var(--blue)' text-anchor='middle'>cross-DB queries</text><text x='190' y='84' font-size='6' fill='var(--blue)' text-anchor='middle'>shared instance</text><text x='295' y='84' font-size='6' fill='var(--blue)' text-anchor='middle'>now available</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Instance-level surface: multiple databases share one instance with cross-DB</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>queries and SQL Agent.</text></svg>"},
    { "id": "p1-11-3", "core": "core1", "domain": "p1", "objective": "1.1", "term": "SQL Server on Azure VM", "definition": "An IaaS deployment where SQL Server runs on a full Azure virtual machine, giving complete OS and SQL Server control at the cost of managing patching and maintenance yourself.", "scenario": "run a SQL Server workload that needs a specific OS-level configuration or third-party agent installed alongside the database engine", "distractors": ["Azure SQL Database", "SQL Managed Instance", "Elastic pool"], "tip": "FULL OS and instance control, but YOU manage patching — the choice when something below the database engine itself needs direct control." , "diagram": "<svg viewBox='0 0 380 163' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-11-3'><title id='dt-p1-11-3'>Full IaaS control over OS and SQL Server config \u2014 and full responsibility for patching both layers.</title><rect x='90' y='20' width='200' height='30' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='39' font-size='7' fill='var(--text)' text-anchor='middle' font-weight='700'>SQL Server (yours)</text><rect x='90' y='54' width='200' height='30' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='73' font-size='7' fill='var(--text)' text-anchor='middle' font-weight='700'>Guest OS (yours)</text><rect x='90' y='88' width='200' height='26' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.6'/><text x='190' y='105' font-size='6.6' fill='var(--primary)' text-anchor='middle'>Azure-managed hardware</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Full IaaS control over OS and SQL Server config \u2014 and full responsibility for</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>patching both layers.</text></svg>"},
    { "id": "p1-12-1", "core": "core1", "domain": "p1", "objective": "1.2", "term": "Elastic pools", "definition": "A shared pool of compute and storage resources that multiple Azure SQL databases draw from, letting databases with unpredictable, non-simultaneous usage patterns share capacity cost-effectively.", "scenario": "host fifty small customer databases that each spike unpredictably at different times, without paying for peak capacity on every single one individually", "distractors": ["Read scale-out", "Auto-failover group", "Serverless tier"], "tip": "SHARES capacity across MANY databases with staggered usage — paying for peak capacity per-database individually would be far more expensive for this exact pattern." , "diagram": "<svg viewBox='0 0 380 132' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-12-1'><title id='dt-p1-12-1'>Multiple databases share one pool of compute/storage resources instead of buying capacity per-DB.</title><circle cx='190' cy='60' r='34' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='190' y='56' font-size='6.8' fill='var(--primary)' text-anchor='middle' font-weight='700'>Elastic</text><text x='190' y='67' font-size='6.8' fill='var(--primary)' text-anchor='middle' font-weight='700'>pool</text><rect x='52' y='16' width='56' height='28' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='80' y='34' font-size='6.6' fill='var(--text)' text-anchor='middle'>DB</text><rect x='272' y='16' width='56' height='28' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='300' y='34' font-size='6.6' fill='var(--text)' text-anchor='middle'>DB</text><rect x='52' y='81' width='56' height='28' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='80' y='99' font-size='6.6' fill='var(--text)' text-anchor='middle'>DB</text><rect x='272' y='81' width='56' height='28' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='300' y='99' font-size='6.6' fill='var(--text)' text-anchor='middle'>DB</text><text x='16' y='110' font-size='8.5' fill='var(--muted)' text-anchor='start'>Multiple databases share one pool of compute/storage resources instead of</text><text x='16' y='122' font-size='8.5' fill='var(--muted)' text-anchor='start'>buying capacity per-DB.</text></svg>"},
    { "id": "p1-12-2", "core": "core1", "domain": "p1", "objective": "1.2", "term": "Read scale-out", "definition": "A feature that routes read-only queries to a secondary replica of an Azure SQL database, offloading reporting or analytics workloads from the primary read-write replica.", "scenario": "run heavy reporting queries against a database without impacting performance of the primary application's live read-write transactions", "distractors": ["Elastic pools", "Auto-failover groups", "Dynamic Data Masking"], "tip": "Offloads READ-ONLY traffic to a SEPARATE REPLICA — protects the primary replica's write performance from being degraded by reporting queries." , "diagram": "<svg viewBox='0 0 400 135' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-12-2'><title id='dt-p1-12-2'>Routes read-only connections to a replica, keeping reporting load off the primary for writes.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='95' y='50' font-size='7.3' fill='var(--primary)' text-anchor='middle' font-weight='700'>Primary</text><text x='95' y='64' font-size='6.4' fill='var(--primary)' text-anchor='middle'>reads + writes</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.8'/><text x='285' y='46' font-size='7.3' fill='var(--blue)' text-anchor='middle' font-weight='700'>Read replica</text><text x='285' y='60' font-size='6.4' fill='var(--blue)' text-anchor='middle'>read-only queries</text><text x='285' y='72' font-size='6.4' fill='var(--blue)' text-anchor='middle'>routed here</text><text x='16' y='113' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Routes read-only connections to a replica, keeping reporting load off the primary</text><text x='16' y='125' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>for writes.</text></svg>"},
    { "id": "p1-12-3", "core": "core1", "domain": "p1", "objective": "1.2", "term": "Serverless compute tier", "definition": "An Azure SQL Database compute tier that automatically scales compute based on workload demand and can pause entirely during inactivity, billing only for actual usage.", "scenario": "run a database used only intermittently during business hours, avoiding paying for compute during long stretches of complete inactivity", "distractors": ["Elastic pool", "Provisioned compute tier", "Read scale-out"], "tip": "Can PAUSE ENTIRELY during inactivity and bills for actual usage — the provisioned tier instead keeps paying for allocated compute whether it's being used or not." , "diagram": "<svg viewBox='0 0 380 197' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-12-3'><title id='dt-p1-12-3'>Pauses during idle time to save cost, then auto-resumes the moment a new connection arrives.</title><rect x='16' y='14' width='348' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='26' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Active</text><text x='190.0' y='39' font-size='7.5' fill='var(--muted)' text-anchor='middle'>serving connections</text><line x1='190.0' y1='48' x2='190.0' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 53 L190.0 60 L194.0 53' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='61' width='348' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='73' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Idle timeout reached</text><text x='190.0' y='86' font-size='7.5' fill='var(--text)' text-anchor='middle'>auto-pauses, compute billing stops</text><line x1='190.0' y1='95' x2='190.0' y2='102' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 100 L190.0 107 L194.0 100' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='108' width='348' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='120' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>New connection arrives</text><text x='190.0' y='133' font-size='7.5' fill='var(--muted)' text-anchor='middle'>resumes automatically</text><text x='16' y='175' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Pauses during idle time to save cost, then auto-resumes the moment a new</text><text x='16' y='187' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>connection arrives.</text></svg>"},
    { "id": "p1-13-1", "core": "core1", "domain": "p1", "objective": "1.3", "term": "Auto-failover groups", "definition": "A feature that manages automatic failover of one or more Azure SQL databases to a secondary server in a different region, using a single listener endpoint that doesn't change during failover.", "scenario": "make sure an application automatically reconnects to a secondary region's database after a regional outage, without changing the connection string", "distractors": ["Read scale-out", "Active geo-replication alone", "Elastic pool"], "tip": "Uses a STABLE LISTENER ENDPOINT that doesn't change on failover — plain active geo-replication requires the application to manually redirect to the new primary." , "diagram": "<svg viewBox='0 0 400 138' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-13-1'><title id='dt-p1-13-1'>A stable listener endpoint fails over to the secondary region automatically \u2014 apps don&#39;t reconnect.</title><rect x='20' y='26' width='150' height='66' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='95' y='46' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>Primary region</text><text x='95' y='60' font-size='6.4' fill='var(--primary)' text-anchor='middle'>read-write</text><text x='95' y='72' font-size='6' fill='var(--primary)' text-anchor='middle'>listener endpoint</text><line x1='172' y1='58' x2='204' y2='58' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 54 L209 58 L202 62' fill='none' stroke='var(--muted)' stroke-width='1.5'/><text x='191' y='50' font-size='6' fill='var(--muted)' text-anchor='middle'>auto</text><rect x='210' y='26' width='150' height='66' rx='6' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.8'/><text x='285' y='46' font-size='6.6' fill='var(--blue)' text-anchor='middle' font-weight='700'>Secondary region</text><text x='285' y='60' font-size='6.2' fill='var(--blue)' text-anchor='middle'>promoted on outage</text><text x='285' y='72' font-size='6.2' fill='var(--blue)' text-anchor='middle'>same endpoint name</text><text x='16' y='116' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A stable listener endpoint fails over to the secondary region automatically \u2014 apps</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>don&#39;t reconnect.</text></svg>"},
    { "id": "p1-13-2", "core": "core1", "domain": "p1", "objective": "1.3", "term": "Zone-redundant configuration", "definition": "A high-availability option that spreads database replicas across multiple availability zones within the same region, protecting against a single datacenter failure without cross-region latency.", "scenario": "protect a database against a single datacenter failure within a region, without incurring the latency of cross-region replication", "distractors": ["Auto-failover groups", "Active geo-replication", "Read scale-out"], "tip": "Protects against a ZONE (datacenter) failure WITHIN one region — geo-replication instead protects against losing an entire region, at higher latency cost." , "diagram": "<svg viewBox='0 0 380 128' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-13-2'><title id='dt-p1-13-2'>Spreads replicas across availability zones within one region, surviving a single zone outage.</title><rect x='30' y='26' width='100' height='60' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='80' y='50' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>Zone A</text><text x='80' y='64' font-size='6.2' fill='var(--primary)' text-anchor='middle'>replica</text><rect x='150' y='26' width='100' height='60' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='200' y='50' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>Zone B</text><text x='200' y='64' font-size='6.2' fill='var(--primary)' text-anchor='middle'>replica</text><rect x='270' y='26' width='100' height='60' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='320' y='50' font-size='7' fill='var(--muted)' text-anchor='middle' font-weight='700'>Zone C</text><text x='320' y='64' font-size='6.2' fill='var(--muted)' text-anchor='middle'>unused</text><text x='16' y='106' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Spreads replicas across availability zones within one region, surviving a</text><text x='16' y='118' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>single zone outage.</text></svg>"},
    { "id": "p1-13-3", "core": "core1", "domain": "p1", "objective": "1.3", "term": "Active geo-replication", "definition": "A feature that creates up to four readable secondary replicas of an Azure SQL database in different regions, each independently promotable to primary during a regional outage.", "scenario": "keep readable copies of a critical database in three different Azure regions, each capable of being manually promoted to primary if needed", "distractors": ["Auto-failover groups", "Zone redundancy", "Elastic pool"], "tip": "Supports up to FOUR independent readable secondaries with MANUAL promotion — auto-failover groups instead automate failover but manage just one designated secondary." , "diagram": "<svg viewBox='0 0 400 132' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-13-3'><title id='dt-p1-13-3'>Up to 4 readable secondary replicas in other regions, each promotable to primary on failure.</title><circle cx='90' cy='55' r='30' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='90' y='52' font-size='6.6' fill='var(--primary)' text-anchor='middle' font-weight='700'>Primary</text><text x='90' y='63' font-size='5.8' fill='var(--primary)' text-anchor='middle'>(writable)</text><line x1='122' y1='55' x2='162' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M160 51 L167 55 L160 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><line x1='212' y1='55' x2='242' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M240 51 L247 55 L240 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><line x1='292' y1='55' x2='322' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M320 51 L327 55 L320 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><circle cx='190' cy='55' r='24' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.6'/><text x='190' y='52' font-size='6.2' fill='var(--blue)' text-anchor='middle' font-weight='700'>Sec 1</text><text x='190' y='62' font-size='5.6' fill='var(--blue)' text-anchor='middle'>readable</text><circle cx='270' cy='55' r='24' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.6'/><text x='270' y='52' font-size='6.2' fill='var(--blue)' text-anchor='middle' font-weight='700'>Sec 2</text><text x='270' y='62' font-size='5.6' fill='var(--blue)' text-anchor='middle'>readable</text><circle cx='350' cy='55' r='24' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.6'/><text x='350' y='52' font-size='6.2' fill='var(--blue)' text-anchor='middle' font-weight='700'>Sec 3</text><text x='350' y='62' font-size='5.6' fill='var(--blue)' text-anchor='middle'>readable</text><text x='16' y='110' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Up to 4 readable secondary replicas in other regions, each promotable to primary on</text><text x='16' y='122' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>failure.</text></svg>"},
    { "id": "p2-21-1", "core": "core1", "domain": "p2", "objective": "2.1", "term": "Microsoft Entra ID authentication vs. SQL authentication", "definition": "Microsoft Entra ID (formerly Azure AD) authentication uses centrally managed identities and supports MFA/conditional access; SQL authentication uses a username/password stored and managed within SQL Server itself.", "scenario": "enforce multifactor authentication for everyone connecting to a database, rather than relying on a locally stored SQL login password", "distractors": ["Contained database users", "Server-level roles", "Row-level security"], "tip": "Microsoft Entra ID auth brings CENTRALIZED IDENTITY and MFA support — SQL authentication's password lives and is managed entirely inside SQL Server, with no such integration." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-21-1'><title id='dt-p2-21-1'>Entra ID auth centralizes identity/MFA/conditional access; SQL auth is a separate local credential.</title><rect x='16.0' y='30' width='179.0' height='64' rx='5' fill='var(--surface-3)' stroke='var(--muted)' stroke-width='1.5'/><text x='105.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>SQL auth</text><text x='105.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>local login + password</text><rect x='205.0' y='30' width='179.0' height='64' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='294.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Entra ID auth</text><text x='294.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>centralized identity</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Entra ID auth centralizes identity/MFA/conditional access; SQL auth is a separate</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>local credential.</text></svg>"},
    { "id": "p2-21-2", "core": "core1", "domain": "p2", "objective": "2.1", "term": "Contained database users", "definition": "Database users that authenticate directly against the database itself rather than through a server-level login, making the database more portable across servers or in a failover.", "scenario": "make sure a database's users can still authenticate immediately after failing over to a different server that doesn't have matching server-level logins", "distractors": ["Server-level roles", "Microsoft Entra ID authentication", "Dynamic Data Masking"], "tip": "Authenticates AT THE DATABASE level, no matching server login required — this is exactly what makes a database portable across a failover to a different server." , "diagram": "<svg viewBox='0 0 380 163' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-21-2'><title id='dt-p2-21-2'>Authenticates directly against the database \u2014 no matching server-level login needed at all.</title><rect x='20' y='20' width='340' height='92' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5' stroke-dasharray='2 2'/><text x='190' y='34' font-size='6.6' fill='var(--muted)' text-anchor='middle'>Server (no login required)</text><rect x='120' y='46' width='140' height='52' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190' y='66' font-size='7.3' fill='var(--primary)' text-anchor='middle' font-weight='700'>Database</text><text x='190' y='80' font-size='6.2' fill='var(--primary)' text-anchor='middle'>contained user lives here</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Authenticates directly against the database \u2014 no matching server-level login</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>needed at all.</text></svg>"},
    { "id": "p2-21-3", "core": "core1", "domain": "p2", "objective": "2.1", "term": "Server-level vs. database-level roles", "definition": "Server-level roles grant permissions across an entire logical server, such as creating new databases; database-level roles scope permissions to just one specific database.", "scenario": "grant a user permission to read and write data in one specific database, without also giving them the ability to create new databases on the server", "distractors": ["Contained database users", "Microsoft Entra ID authentication", "TLS enforcement"], "tip": "SERVER-level roles span the WHOLE server; DATABASE-level roles are scoped to ONE database — picking the narrower scope avoids over-granting permission." , "diagram": "<svg viewBox='0 0 380 167' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-21-3'><title id='dt-p2-21-3'>Server-level roles govern instance-wide capability; database-level roles scope to one database.</title><rect x='60' y='18' width='260' height='40' rx='6' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.8'/><text x='190' y='36' font-size='7.3' fill='var(--blue)' text-anchor='middle' font-weight='700'>Server-level roles</text><text x='190' y='49' font-size='6' fill='var(--blue)' text-anchor='middle'>e.g. dbmanager, sysadmin scope</text><line x1='190' y1='58' x2='190' y2='70' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 68 L190 75 L194 68' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='60' y='78' width='260' height='40' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190' y='96' font-size='7.3' fill='var(--primary)' text-anchor='middle' font-weight='700'>Database-level roles</text><text x='190' y='109' font-size='6' fill='var(--primary)' text-anchor='middle'>e.g. db_datareader, db_owner</text><text x='16' y='145' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Server-level roles govern instance-wide capability; database-level roles scope</text><text x='16' y='157' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>to one database.</text></svg>"},
    { "id": "p2-22-1", "core": "core1", "domain": "p2", "objective": "2.2", "term": "Transparent Data Encryption (TDE)", "definition": "Encryption applied automatically at the storage layer to a database's data and log files at rest, requiring no changes to the application or queries.", "scenario": "encrypt a database's underlying data files at rest to satisfy a compliance requirement, without modifying any application code", "distractors": ["Always Encrypted", "TLS enforcement", "Dynamic Data Masking"], "tip": "Encrypts data AT REST TRANSPARENTLY, no app changes needed — Always Encrypted instead protects specific COLUMNS even from database administrators, a stronger but more involved guarantee." , "diagram": "<svg viewBox='0 0 380 134' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-22-1'><title id='dt-p2-22-1'>Encrypts data at rest transparently \u2014 no application changes, encryption/decryption is automatic.</title><rect x='30' y='24' width='320' height='58' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='190' y='46' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>Data files, logs, backups</text><text x='190' y='62' font-size='6.4' fill='var(--primary)' text-anchor='middle'>encrypted at rest, automatically</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Encrypts data at rest transparently \u2014 no application changes,</text><text x='16' y='124' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>encryption/decryption is automatic.</text></svg>"},
    { "id": "p2-22-2", "core": "core1", "domain": "p2", "objective": "2.2", "term": "Always Encrypted", "definition": "A feature that encrypts specific sensitive columns client-side, so that even database administrators with full access to the database can never see the plaintext values.", "scenario": "protect a column of customer social security numbers so that even a database administrator with full access to the server cannot view the plaintext values", "distractors": ["Transparent Data Encryption", "Dynamic Data Masking", "Row-level security"], "tip": "Keeps plaintext hidden even from DATABASE ADMINISTRATORS themselves — TDE protects against someone stealing the physical files, but a DBA with normal query access could still read TDE-protected data in plaintext." , "diagram": "<svg viewBox='0 0 380 132' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-22-2'><title id='dt-p2-22-2'>Encryption/decryption happens client-side \u2014 the database engine only ever handles ciphertext.</title><rect x='20' y='24' width='130' height='56' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='85' y='44' font-size='7.3' fill='var(--primary)' text-anchor='middle' font-weight='700'>App</text><text x='85' y='58' font-size='6' fill='var(--primary)' text-anchor='middle'>holds the key</text><line x1='152' y1='52' x2='194' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M192 48 L199 52 L192 56' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='200' y='24' width='160' height='56' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5' stroke-dasharray='2 2'/><text x='280' y='44' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>DB engine</text><text x='280' y='58' font-size='6' fill='var(--muted)' text-anchor='middle'>never sees plaintext</text><text x='16' y='110' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Encryption/decryption happens client-side \u2014 the database engine only ever</text><text x='16' y='122' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>handles ciphertext.</text></svg>"},
    { "id": "p2-22-3", "core": "core1", "domain": "p2", "objective": "2.2", "term": "TLS enforcement", "definition": "A setting requiring all connections to a database to use TLS encryption, protecting data in motion between the client and the server from network eavesdropping.", "scenario": "make sure no application can connect to a database over an unencrypted network connection", "distractors": ["Transparent Data Encryption", "Always Encrypted", "SQL Audit"], "tip": "Protects data IN MOTION over the network — TDE and Always Encrypted instead protect data AT REST or at the column level, a different threat surface entirely." , "diagram": "<svg viewBox='0 0 380 126' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-22-3'><title id='dt-p2-22-3'>Requires a minimum TLS version for every connection \u2014 plaintext connections are refused.</title><rect x='20' y='30' width='120' height='44' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='80' y='56' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Client</text><line x1='146' y1='52' x2='228' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M226 48 L233 52 L226 56' fill='none' stroke='var(--muted)' stroke-width='1.5'/><text x='190' y='42' font-size='6.4' fill='var(--primary)' text-anchor='middle' font-weight='700'>TLS 1.2+</text><rect x='240' y='30' width='120' height='44' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='300' y='56' font-size='7' fill='var(--text)' text-anchor='middle' font-weight='700'>SQL server</text><text x='16' y='104' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Requires a minimum TLS version for every connection \u2014 plaintext connections are</text><text x='16' y='116' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>refused.</text></svg>"},
    { "id": "p2-23-1", "core": "core1", "domain": "p2", "objective": "2.3", "term": "Dynamic Data Masking", "definition": "A feature that obscures sensitive data in query results for non-privileged users, such as showing only the last four digits of a credit card number, without altering the actual stored data.", "scenario": "let customer service reps view a masked version of customers' credit card numbers in query results, without altering the actual stored data or requiring separate views", "distractors": ["Always Encrypted", "Transparent Data Encryption", "Row-level security"], "tip": "Masks data in the RESULT SET for non-privileged users — the underlying stored data is completely unchanged, unlike Always Encrypted which actually encrypts the stored value." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-23-1'><title id='dt-p2-23-1'>Non-privileged users see a masked value in query results \u2014 the stored data itself is unchanged.</title><rect x='16.0' y='30' width='179.0' height='64' rx='5' fill='var(--surface-3)' stroke='var(--muted)' stroke-width='1.5'/><text x='105.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Raw value</text><text x='105.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>4111-2233-4455-6677</text><rect x='205.0' y='30' width='179.0' height='64' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='294.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Masked value</text><text x='294.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>XXXX-XXXX-XXXX-6677</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Non-privileged users see a masked value in query results \u2014 the stored data itself is</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>unchanged.</text></svg>"},
    { "id": "p2-23-2", "core": "core1", "domain": "p2", "objective": "2.3", "term": "Row-level security", "definition": "A feature that restricts which rows a given user can see or modify in a query, based on the user's identity or role, enforced automatically without changing application queries.", "scenario": "make sure sales representatives can only see rows for their own assigned customer accounts, without adding a WHERE clause to every application query", "distractors": ["Dynamic Data Masking", "Contained database users", "SQL Audit"], "tip": "Filters WHICH ROWS a user can see, enforced AUTOMATICALLY — Dynamic Data Masking instead lets a user see every row, just with certain COLUMN values obscured." , "diagram": "<svg viewBox='0 0 380 163' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-23-2'><title id='dt-p2-23-2'>A security predicate filters which rows a query returns, per user, transparently.</title><rect x='20' y='18' width='340' height='96' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='32' font-size='6.6' fill='var(--muted)' text-anchor='middle' font-weight='700'>Table (all rows)</text><rect x='36' y='42' width='308' height='14' rx='3' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='190' y='52.5' font-size='5.8' fill='var(--primary)' text-anchor='middle'>visible to this user</text><rect x='36' y='60' width='308' height='14' rx='3' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.2'/><text x='190' y='70.5' font-size='5.8' fill='var(--muted)' text-anchor='middle'>filtered out by predicate</text><rect x='36' y='78' width='308' height='14' rx='3' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='190' y='88.5' font-size='5.8' fill='var(--primary)' text-anchor='middle'>visible to this user</text><rect x='36' y='96' width='308' height='14' rx='3' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.2'/><text x='190' y='106.5' font-size='5.8' fill='var(--muted)' text-anchor='middle'>filtered out by predicate</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A security predicate filters which rows a query returns, per user,</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>transparently.</text></svg>"},
    { "id": "p2-23-3", "core": "core1", "domain": "p2", "objective": "2.3", "term": "SQL Audit", "definition": "A feature that logs database events, such as logins and data access, to a durable audit trail for compliance reporting and forensic investigation.", "scenario": "produce a compliance report showing every user who accessed a specific sensitive table over the past quarter", "distractors": ["Dynamic Data Masking", "Row-level security", "Query Store"], "tip": "Produces a DURABLE LOG of who accessed what and when — Query Store instead tracks query PERFORMANCE history, a completely different purpose despite both being historical records." , "diagram": "<svg viewBox='0 0 380 188' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-23-3'><title id='dt-p2-23-3'>Captures database events to a durable target so access can be proven after the fact.</title><rect x='16' y='14' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='25' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Action occurs</text><text x='190.0' y='38' font-size='7.5' fill='var(--muted)' text-anchor='middle'>a login, query, or permission change</text><line x1='190.0' y1='46' x2='190.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 50 L190.0 57 L194.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='69' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Logged to audit target</text><text x='190.0' y='82' font-size='7.5' fill='var(--muted)' text-anchor='middle'>storage, Log Analytics, or Event Hub</text><line x1='190.0' y1='90' x2='190.0' y2='96' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 94 L190.0 101 L194.0 94' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='102' width='348' height='32' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='113' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Reviewed for compliance</text><text x='190.0' y='126' font-size='7.5' fill='var(--text)' text-anchor='middle'>access history proven on demand</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Captures database events to a durable target so access can be proven after the</text><text x='16' y='178' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>fact.</text></svg>"},
    { "id": "p3-31-1", "core": "core1", "domain": "p3", "objective": "3.1", "term": "Query Store", "definition": "A built-in feature that automatically captures a history of query execution plans and runtime statistics, making it easy to spot performance regressions over time.", "scenario": "identify exactly when a specific query's performance regressed after a recent deployment, using historical execution data captured automatically", "distractors": ["Extended Events", "Dynamic management views", "SQL Audit"], "tip": "Automatically captures HISTORICAL execution plans/stats over TIME — DMVs instead show mostly CURRENT, point-in-time system state rather than trended history." , "diagram": "<svg viewBox='0 0 380 188' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-31-1'><title id='dt-p3-31-1'>Captures query plans and runtime stats over time, right inside the database itself.</title><rect x='16' y='14' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='25' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Query runs</text><text x='190.0' y='38' font-size='7.5' fill='var(--muted)' text-anchor='middle'>plan + runtime stats captured automatically</text><line x1='190.0' y1='46' x2='190.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 50 L190.0 57 L194.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='69' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Stored in the database</text><text x='190.0' y='82' font-size='7.5' fill='var(--muted)' text-anchor='middle'>survives restarts and failovers</text><line x1='190.0' y1='90' x2='190.0' y2='96' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 94 L190.0 101 L194.0 94' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='102' width='348' height='32' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='113' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Historical view available</text><text x='190.0' y='126' font-size='7.5' fill='var(--text)' text-anchor='middle'>compare plan performance over time</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Captures query plans and runtime stats over time, right inside the database</text><text x='16' y='178' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>itself.</text></svg>"},
    { "id": "p3-31-2", "core": "core1", "domain": "p3", "objective": "3.1", "term": "Extended Events", "definition": "A lightweight, highly configurable event-tracing system for capturing detailed diagnostic data about specific database engine events with minimal performance overhead.", "scenario": "capture detailed diagnostic data about a specific rare error condition, with minimal performance impact on the production database", "distractors": ["Query Store", "Azure SQL Analytics", "SQL Audit"], "tip": "LIGHTWEIGHT, highly targeted event capture with LOW OVERHEAD — the tool reached for when you need fine-grained diagnostic detail without a heavy performance cost." , "diagram": "<svg viewBox='0 0 400 118' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-31-2'><title id='dt-p3-31-2'>A low-overhead event-capture session targeting only the specific events you need.</title><rect x='20' y='24' width='150' height='58' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5' stroke-dasharray='2 2'/><text x='95' y='44' font-size='7' fill='var(--muted)' text-anchor='middle' font-weight='700'>SQL Trace</text><text x='95' y='58' font-size='6' fill='var(--muted)' text-anchor='middle'>(deprecated,</text><text x='95' y='70' font-size='6' fill='var(--muted)' text-anchor='middle'>heavier)</text><rect x='210' y='24' width='150' height='58' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='285' y='44' font-size='6.8' fill='var(--primary)' text-anchor='middle' font-weight='700'>Extended Events</text><text x='285' y='58' font-size='6' fill='var(--primary)' text-anchor='middle'>lightweight session,</text><text x='285' y='70' font-size='6' fill='var(--primary)' text-anchor='middle'>targeted events only</text><text x='16' y='108' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A low-overhead event-capture session targeting only the specific events you need.</text></svg>"},
    { "id": "p3-31-3", "core": "core1", "domain": "p3", "objective": "3.1", "term": "Azure SQL Analytics", "definition": "A monitoring solution that aggregates performance metrics and logs across many Azure SQL databases into Azure Monitor for a fleet-wide operational view.", "scenario": "get one consolidated dashboard showing the health of two hundred Azure SQL databases across the organization", "distractors": ["Query Store", "Extended Events", "DMVs"], "tip": "AGGREGATES across MANY databases into ONE fleet-wide view — Query Store and Extended Events instead each operate scoped to a single database." , "diagram": "<svg viewBox='0 0 380 167' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-31-3'><title id='dt-p3-31-3'>Centralizes telemetry from many databases into one workspace for dashboards and alerts.</title><rect x='20' y='18' width='60' height='28' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='50' y='36' font-size='6.4' fill='var(--text)' text-anchor='middle'>DB 1</text><line x1='50' y1='46' x2='50' y2='60' stroke='var(--muted)' stroke-width='1.5'/><path d='M46 58 L50 65 L54 58' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='120' y='18' width='60' height='28' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='150' y='36' font-size='6.4' fill='var(--text)' text-anchor='middle'>DB 2</text><line x1='150' y1='46' x2='150' y2='60' stroke='var(--muted)' stroke-width='1.5'/><path d='M146 58 L150 65 L154 58' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='220' y='18' width='60' height='28' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='250' y='36' font-size='6.4' fill='var(--text)' text-anchor='middle'>DB 3</text><line x1='250' y1='46' x2='250' y2='60' stroke='var(--muted)' stroke-width='1.5'/><path d='M246 58 L250 65 L254 58' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='90' y='68' width='200' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190' y='89' font-size='6.6' fill='var(--primary)' text-anchor='middle' font-weight='700'>Log Analytics workspace</text><text x='190' y='116' font-size='6.6' fill='var(--text)' text-anchor='middle'>Dashboards, alerts, cross-database queries.</text><text x='16' y='145' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Centralizes telemetry from many databases into one workspace for dashboards and</text><text x='16' y='157' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>alerts.</text></svg>"},
    { "id": "p3-32-1", "core": "core1", "domain": "p3", "objective": "3.2", "term": "Dynamic management views (DMVs)", "definition": "System views that expose real-time internal server state, such as active sessions, locks, and resource consumption, queryable like any other table.", "scenario": "query current active sessions and what each one is waiting on, right now, to diagnose an ongoing slowdown", "distractors": ["Query Store", "SQL Audit", "Extended Events"], "tip": "Exposes CURRENT, LIVE internal state as queryable views — Query Store instead is about HISTORICAL trends, a different (though complementary) angle on performance data." , "diagram": "<svg viewBox='0 0 380 138' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-32-1'><title id='dt-p3-32-1'>Dynamic management views expose real-time server and query engine internals via T-SQL.</title><rect x='30' y='22' width='320' height='66' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190' y='44' font-size='7.6' fill='var(--primary)' text-anchor='middle' font-weight='700'>sys.dm_* views</text><text x='190' y='60' font-size='6.4' fill='var(--primary)' text-anchor='middle'>live window into current server state</text><text x='190' y='72' font-size='6' fill='var(--primary)' text-anchor='middle'>(sessions, waits, requests, indexes)</text><text x='16' y='116' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Dynamic management views expose real-time server and query engine internals via</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>T-SQL.</text></svg>"},
    { "id": "p3-32-2", "core": "core1", "domain": "p3", "objective": "3.2", "term": "Wait statistics", "definition": "Data showing what resources or conditions queries are spending time waiting on, such as locks or I/O, pointing directly at the actual bottleneck rather than just its symptoms.", "scenario": "determine whether a slow query is actually being held up by disk I/O, blocking locks, or something else entirely, rather than guessing from symptoms alone", "distractors": ["Resource utilization metrics", "Query Store history", "SQL Audit"], "tip": "Points at WHAT the query is actually WAITING ON — a much more direct diagnostic signal than general resource utilization metrics, which only show overall load." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-32-2'><title id='dt-p3-32-2'>Wait statistics show what queries were waiting ON \u2014 the single biggest clue to a bottleneck&#39;s cause.</title><rect x='16.0' y='30' width='116.0' height='64' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='74.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>CPU</text><text x='74.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>SOS_SCHEDULER_YIELD</text><rect x='142.0' y='30' width='116.0' height='64' rx='5' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='200.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>I/O</text><text x='200.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>PAGEIOLATCH_*</text><rect x='268.0' y='30' width='116.0' height='64' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='326.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Lock</text><text x='326.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>LCK_M_*</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Wait statistics show what queries were waiting ON \u2014 the single biggest clue to a</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>bottleneck&#39;s cause.</text></svg>"},
    { "id": "p3-32-3", "core": "core1", "domain": "p3", "objective": "3.2", "term": "Resource utilization metrics", "definition": "High-level metrics like CPU percentage, DTU/vCore consumption, and storage usage that indicate overall database load and whether the current service tier is appropriately sized.", "scenario": "decide whether a database needs to be scaled up to a higher service tier based on sustained high resource consumption", "distractors": ["Wait statistics", "Query Store history", "Extended Events"], "tip": "HIGH-LEVEL sizing signal for the whole database — wait statistics instead diagnose WHY a specific query is slow, a more granular, different question." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-32-3'><title id='dt-p3-32-3'>A quick top-level read on whether compute, DTU, or storage capacity is the constraint right now.</title><rect x='16.0' y='30' width='116.0' height='64' rx='5' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='74.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>CPU %</text><text x='74.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>78%</text><rect x='142.0' y='30' width='116.0' height='64' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='200.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>DTU %</text><text x='200.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>61%</text><rect x='268.0' y='30' width='116.0' height='64' rx='5' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.5'/><text x='326.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Storage %</text><text x='326.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>34%</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A quick top-level read on whether compute, DTU, or storage capacity is the</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>constraint right now.</text></svg>"},
    { "id": "p4-41-1", "core": "core1", "domain": "p4", "objective": "4.1", "term": "Clustered vs. nonclustered indexes", "definition": "A clustered index physically orders a table's data rows by the index key (one per table); nonclustered indexes are separate structures pointing back to the data, and a table can have many.", "scenario": "decide which type of index to add to speed up lookups on a column that isn't the table's primary sort order, without disturbing the existing physical row order", "distractors": ["Missing index recommendations", "Statistics staleness", "Fragmentation"], "tip": "A table has only ONE clustered index (it defines physical order) but can have MANY nonclustered indexes pointing back to that data." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-41-1'><title id='dt-p4-41-1'>Only one clustered index per table \u2014 it defines row order; nonclustered indexes point back to it.</title><rect x='16.0' y='30' width='179.0' height='64' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='105.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Clustered</text><text x='105.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>IS the physical row order</text><rect x='205.0' y='30' width='179.0' height='64' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='294.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Nonclustered</text><text x='294.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>separate structure + pointer</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Only one clustered index per table \u2014 it defines row order; nonclustered indexes</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>point back to it.</text></svg>"},
    { "id": "p4-41-2", "core": "core1", "domain": "p4", "objective": "4.1", "term": "Missing index recommendations", "definition": "Suggestions the database engine generates based on observed query patterns, identifying indexes that would likely improve performance for queries it has actually seen run.", "scenario": "get a data-driven suggestion for which index to add next, based on the actual query patterns the database has been running", "distractors": ["Clustered index", "Query plan analysis", "Statistics staleness"], "tip": "DATA-DRIVEN suggestions based on ACTUAL observed query patterns — not a substitute for judgment, since not every suggested index is worth the write-performance tradeoff of adding it." , "diagram": "<svg viewBox='0 0 380 188' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-41-2'><title id='dt-p4-41-2'>The optimizer logs what index it wished it had \u2014 a starting point, not an auto-apply command.</title><rect x='16' y='14' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='25' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Query executes</text><text x='190.0' y='38' font-size='7.5' fill='var(--muted)' text-anchor='middle'>optimizer builds the best plan it can</text><line x1='190.0' y1='46' x2='190.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 50 L190.0 57 L194.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='69' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Missing index noted</text><text x='190.0' y='82' font-size='7.5' fill='var(--muted)' text-anchor='middle'>a helpful index wasn\u2019t available</text><line x1='190.0' y1='90' x2='190.0' y2='96' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 94 L190.0 101 L194.0 94' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='102' width='348' height='32' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='113' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>DMV surfaces suggestion</text><text x='190.0' y='126' font-size='7.5' fill='var(--text)' text-anchor='middle'>estimated impact included</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The optimizer logs what index it wished it had \u2014 a starting point, not an</text><text x='16' y='178' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>auto-apply command.</text></svg>"},
    { "id": "p4-41-3", "core": "core1", "domain": "p4", "objective": "4.1", "term": "Index fragmentation", "definition": "The degree to which an index's logical order no longer matches its physical storage order due to ongoing inserts/updates/deletes, degrading read performance until it's rebuilt or reorganized.", "scenario": "explain why a heavily-updated table's query performance has gradually degraded over months without any schema changes", "distractors": ["Missing index recommendations", "Parameter sniffing", "Statistics staleness"], "tip": "Builds up GRADUALLY from ongoing writes over TIME — a rebuild/reorganize restores the index's physical order to match its logical order again." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-41-3'><title id='dt-p4-41-3'>High fragmentation means extra I/O per scan \u2014 reorganize or rebuild restores contiguous pages.</title><rect x='16.0' y='30' width='179.0' height='64' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='105.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Fragmented</text><text x='105.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>pages scattered, out of order</text><rect x='205.0' y='30' width='179.0' height='64' rx='5' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.5'/><text x='294.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Rebuilt</text><text x='294.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>contiguous, in logical order</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>High fragmentation means extra I/O per scan \u2014 reorganize or rebuild restores</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>contiguous pages.</text></svg>"},
    { "id": "p4-42-1", "core": "core1", "domain": "p4", "objective": "4.2", "term": "Execution plan reading", "definition": "Interpreting the graphical or text representation of how the query optimizer chose to retrieve data, revealing whether it used efficient index seeks or costly full table scans.", "scenario": "determine whether a slow query is doing an efficient index seek or an expensive full table scan", "distractors": ["Wait statistics", "Missing index recommendations alone", "SQL Audit"], "tip": "Reveals HOW the optimizer actually retrieved the data — seeks vs. scans is the single most common thing to check first when reading a plan." , "diagram": "<svg viewBox='0 0 380 182' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-42-1'><title id='dt-p4-42-1'>Read plans bottom-up: cheap operators (seeks) feed into joins feeding the final output.</title><rect x='140' y='20' width='100' height='30' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='39' font-size='6.8' fill='var(--text)' text-anchor='middle' font-weight='700'>SELECT</text><line x1='190' y1='50' x2='190' y2='60' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 58 L190 65 L194 58' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='140' y='68' width='100' height='30' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.6'/><text x='190' y='87' font-size='6.8' fill='var(--blue)' text-anchor='middle' font-weight='700'>Hash Join</text><line x1='120' y1='98' x2='120' y2='108' stroke='var(--muted)' stroke-width='1.5'/><path d='M116 106 L120 113 L124 106' fill='none' stroke='var(--muted)' stroke-width='1.5'/><line x1='260' y1='98' x2='260' y2='108' stroke='var(--muted)' stroke-width='1.5'/><path d='M256 106 L260 113 L264 106' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='60' y='116' width='120' height='28' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.6'/><text x='120' y='134' font-size='6.6' fill='var(--primary)' text-anchor='middle' font-weight='700'>Index Seek</text><rect x='200' y='116' width='120' height='28' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.6'/><text x='260' y='134' font-size='6.6' fill='var(--red)' text-anchor='middle' font-weight='700'>Table Scan</text><text x='16' y='160' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Read plans bottom-up: cheap operators (seeks) feed into joins feeding the final</text><text x='16' y='172' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>output.</text></svg>"},
    { "id": "p4-42-2", "core": "core1", "domain": "p4", "objective": "4.2", "term": "Parameter sniffing", "definition": "A behavior where the query optimizer caches an execution plan based on the first parameter value used, which can perform poorly for later calls with very different parameter values.", "scenario": "explain why the same stored procedure runs fast for one customer's data but extremely slowly for a much larger customer, despite identical code", "distractors": ["Index fragmentation", "Statistics staleness", "Missing index"], "tip": "The CACHED PLAN was optimized for the FIRST parameter value seen — a plan great for a small dataset can be terrible when reused for a much larger one." , "diagram": "<svg viewBox='0 0 380 194' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-42-2'><title id='dt-p4-42-2'>A plan optimized for one parameter value can perform badly for a very different one later.</title><rect x='16' y='14' width='348' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='26' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>First execution: value X</text><text x='190.0' y='39' font-size='7.5' fill='var(--muted)' text-anchor='middle'>plan compiled and optimized for X</text><line x1='190.0' y1='48' x2='190.0' y2='54' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 52 L190.0 59 L194.0 52' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='60' width='348' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='72' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Plan cached</text><text x='190.0' y='85' font-size='7.5' fill='var(--muted)' text-anchor='middle'>reused for later calls</text><line x1='190.0' y1='94' x2='190.0' y2='100' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 98 L190.0 105 L194.0 98' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='106' width='348' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='118' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Called again with value Y</text><text x='190.0' y='131' font-size='7.5' fill='var(--text)' text-anchor='middle'>very different data \u2192 same plan, poor fit</text><text x='16' y='172' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A plan optimized for one parameter value can perform badly for a very different</text><text x='16' y='184' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>one later.</text></svg>"},
    { "id": "p4-42-3", "core": "core1", "domain": "p4", "objective": "4.2", "term": "Statistics staleness", "definition": "Outdated column statistics cause the query optimizer to make poor cardinality estimates and therefore poor execution plan choices, until statistics are refreshed to reflect current data.", "scenario": "explain why the optimizer suddenly started choosing a much worse execution plan for a query after a large bulk data load, with no code changes", "distractors": ["Parameter sniffing", "Index fragmentation", "Missing index recommendations"], "tip": "The optimizer's CARDINALITY ESTIMATES go stale after big data changes — updating statistics gives the optimizer an accurate picture of the data again." , "diagram": "<svg viewBox='0 0 380 126' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-42-3'><title id='dt-p4-42-3'>The optimizer trusts stale statistics \u2014 a growing gap from real data leads to bad plan choices.</title><line x1='30' y1='60' x2='350' y2='60' stroke='var(--border)' stroke-width='2'/><circle cx='90' cy='60' r='6' fill='var(--blue)'/><text x='90' y='42' font-size='6.6' fill='var(--blue)' text-anchor='middle' font-weight='700'>Statistics</text><text x='90' y='82' font-size='6' fill='var(--blue)' text-anchor='middle'>captured here</text><circle cx='300' cy='60' r='6' fill='var(--red)'/><text x='300' y='42' font-size='6.6' fill='var(--red)' text-anchor='middle' font-weight='700'>Actual data now</text><text x='300' y='82' font-size='6' fill='var(--red)' text-anchor='middle'>drifted far from stats</text><text x='16' y='104' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The optimizer trusts stale statistics \u2014 a growing gap from real data leads to</text><text x='16' y='116' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>bad plan choices.</text></svg>"},
    { "id": "p5-51-1", "core": "core1", "domain": "p5", "objective": "5.1", "term": "ARM/Bicep templates for SQL deployment", "definition": "Infrastructure-as-code templates that declaratively define Azure SQL resources, allowing consistent, repeatable, version-controlled database provisioning.", "scenario": "provision an identical Azure SQL Database configuration consistently across dev, test, and production environments", "distractors": ["SQL Agent jobs", "PowerShell ad hoc scripts", "Elastic Jobs"], "tip": "DECLARATIVE, VERSION-CONTROLLED infrastructure definitions — ad hoc PowerShell scripts can do similar provisioning but without the same repeatability/consistency guarantees." , "diagram": "<svg viewBox='0 0 380 188' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-51-1'><title id='dt-p5-51-1'>Declares the desired state \u2014 Azure figures out what to create, update, or leave alone.</title><rect x='16' y='14' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='25' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Write declarative template</text><text x='190.0' y='38' font-size='7.5' fill='var(--muted)' text-anchor='middle'>desired end-state, not steps</text><line x1='190.0' y1='46' x2='190.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 50 L190.0 57 L194.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='69' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Deploy the template</text><text x='190.0' y='82' font-size='7.5' fill='var(--muted)' text-anchor='middle'>ARM/Bicep to a resource group</text><line x1='190.0' y1='90' x2='190.0' y2='96' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 94 L190.0 101 L194.0 94' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='102' width='348' height='32' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='113' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Azure reconciles resources</text><text x='190.0' y='126' font-size='7.5' fill='var(--text)' text-anchor='middle'>creates or updates to match</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Declares the desired state \u2014 Azure figures out what to create, update, or leave</text><text x='16' y='178' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>alone.</text></svg>"},
    { "id": "p5-51-2", "core": "core1", "domain": "p5", "objective": "5.1", "term": "CI/CD pipelines for schema changes", "definition": "Automated pipelines that test and deploy database schema changes through controlled stages, reducing the risk of manual, ad hoc production schema modifications.", "scenario": "make sure every database schema change goes through automated testing before it's ever applied to production", "distractors": ["ARM templates alone", "SQL Agent jobs", "Automated index maintenance"], "tip": "Enforces TESTING/CONTROLLED STAGES before production — the schema-change-specific automation, distinct from general infrastructure provisioning via ARM templates." , "diagram": "<svg viewBox='0 0 380 188' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-51-2'><title id='dt-p5-51-2'>Schema changes flow through the same build/test/deploy pipeline as application code.</title><rect x='16' y='14' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='25' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Commit schema change</text><text x='190.0' y='38' font-size='7.5' fill='var(--muted)' text-anchor='middle'>to source control</text><line x1='190.0' y1='46' x2='190.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 50 L190.0 57 L194.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='69' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Pipeline builds and tests</text><text x='190.0' y='82' font-size='7.5' fill='var(--muted)' text-anchor='middle'>validates against a test DB</text><line x1='190.0' y1='90' x2='190.0' y2='96' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 94 L190.0 101 L194.0 94' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='102' width='348' height='32' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='113' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Auto-deploys to target</text><text x='190.0' y='126' font-size='7.5' fill='var(--text)' text-anchor='middle'>staging, then production</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Schema changes flow through the same build/test/deploy pipeline as application</text><text x='16' y='178' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>code.</text></svg>"},
    { "id": "p5-51-3", "core": "core1", "domain": "p5", "objective": "5.1", "term": "PowerShell/CLI automation", "definition": "Scripting routine or bulk database administration tasks, such as creating multiple databases or applying configuration changes, using Azure PowerShell or the Azure CLI.", "scenario": "apply the same configuration change consistently across two hundred Azure SQL databases without clicking through the portal two hundred times", "distractors": ["ARM templates", "SQL Agent jobs", "Long-term retention backups"], "tip": "SCRIPTS repeated ADMIN TASKS across many resources — ARM/Bicep instead is specifically for declaring the desired infrastructure state, a related but distinct automation category." , "diagram": "<svg viewBox='0 0 380 138' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-51-3'><title id='dt-p5-51-3'>One script applies the same operation consistently across many databases at once.</title><rect x='30' y='26' width='140' height='56' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='100' y='48' font-size='6.6' fill='var(--primary)' text-anchor='middle' font-weight='700'>PowerShell / az CLI</text><text x='100' y='62' font-size='6.2' fill='var(--primary)' text-anchor='middle'>one script, one run</text><line x1='172' y1='54' x2='204' y2='54' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 50 L209 54 L202 58' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='40' height='24' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='230' y='40' font-size='6' fill='var(--text)' text-anchor='middle'>DB</text><rect x='210' y='54' width='40' height='24' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='230' y='70' font-size='6' fill='var(--text)' text-anchor='middle'>DB</text><rect x='260' y='24' width='40' height='24' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='280' y='40' font-size='6' fill='var(--text)' text-anchor='middle'>DB</text><rect x='260' y='54' width='40' height='24' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='280' y='70' font-size='6' fill='var(--text)' text-anchor='middle'>DB</text><rect x='310' y='24' width='40' height='24' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='330' y='40' font-size='6' fill='var(--text)' text-anchor='middle'>DB</text><rect x='310' y='54' width='40' height='24' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='330' y='70' font-size='6' fill='var(--text)' text-anchor='middle'>DB</text><text x='16' y='116' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>One script applies the same operation consistently across many databases at</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>once.</text></svg>"},
    { "id": "p5-52-1", "core": "core1", "domain": "p5", "objective": "5.2", "term": "SQL Agent / Elastic Jobs", "definition": "Scheduling engines for running T-SQL scripts or maintenance tasks automatically — SQL Agent for SQL Managed Instance/VM, Elastic Jobs for running scripts across many Azure SQL databases at once.", "scenario": "schedule the same maintenance script to run automatically across every database in a large Azure SQL Database fleet", "distractors": ["CI/CD pipeline", "ARM template", "Query Store"], "tip": "Elastic Jobs specifically runs scripts ACROSS MANY Azure SQL databases at once — SQL Agent's classic single-instance scheduling doesn't natively span a whole fleet the same way." , "diagram": "<svg viewBox='0 0 380 188' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-52-1'><title id='dt-p5-52-1'>Runs recurring T-SQL/scripted work on a schedule, with logged, alertable outcomes.</title><rect x='16' y='14' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='25' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Job scheduled</text><text x='190.0' y='38' font-size='7.5' fill='var(--muted)' text-anchor='middle'>or elastic job across many DBs</text><line x1='190.0' y1='46' x2='190.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 50 L190.0 57 L194.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='69' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Runs on trigger</text><text x='190.0' y='82' font-size='7.5' fill='var(--muted)' text-anchor='middle'>time schedule or event</text><line x1='190.0' y1='90' x2='190.0' y2='96' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 94 L190.0 101 L194.0 94' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='102' width='348' height='32' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='113' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Result logged</text><text x='190.0' y='126' font-size='7.5' fill='var(--text)' text-anchor='middle'>success/failure visible, alertable</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Runs recurring T-SQL/scripted work on a schedule, with logged, alertable</text><text x='16' y='178' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>outcomes.</text></svg>"},
    { "id": "p5-52-2", "core": "core1", "domain": "p5", "objective": "5.2", "term": "Automated index maintenance", "definition": "Scheduled jobs that automatically rebuild or reorganize indexes based on measured fragmentation levels, keeping performance consistent without manual intervention.", "scenario": "keep index fragmentation under control across a busy database automatically, without a DBA manually checking and rebuilding indexes each week", "distractors": ["Missing index recommendations alone", "Query Store", "Statistics staleness detection alone"], "tip": "AUTOMATES the REBUILD/REORGANIZE response to fragmentation — turns a manual, easy-to-forget maintenance task into a scheduled, hands-off process." , "diagram": "<svg viewBox='0 0 380 194' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-52-2'><title id='dt-p5-52-2'>A scheduled job measures fragmentation and applies the right fix without manual intervention.</title><rect x='16' y='14' width='348' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='26' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Job checks fragmentation</text><text x='190.0' y='39' font-size='7.5' fill='var(--muted)' text-anchor='middle'>per index, on schedule</text><line x1='190.0' y1='48' x2='190.0' y2='54' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 52 L190.0 59 L194.0 52' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='60' width='348' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='72' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Reorganize (low) or rebuild (high)</text><text x='190.0' y='85' font-size='7.5' fill='var(--text)' text-anchor='middle'>threshold-based choice</text><line x1='190.0' y1='94' x2='190.0' y2='100' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 98 L190.0 105 L194.0 98' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='106' width='348' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='118' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Runs unattended</text><text x='190.0' y='131' font-size='7.5' fill='var(--muted)' text-anchor='middle'>off-hours maintenance window</text><text x='16' y='172' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A scheduled job measures fragmentation and applies the right fix without manual</text><text x='16' y='184' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>intervention.</text></svg>"},
    { "id": "p5-52-3", "core": "core1", "domain": "p5", "objective": "5.2", "term": "Long-term retention (LTR) backups", "definition": "A configuration that retains Azure SQL Database automated backups for up to 10 years, beyond the standard short-term retention window, for compliance or legal hold requirements.", "scenario": "satisfy a regulatory requirement to retain database backups for seven years, well beyond the standard automatic backup retention window", "distractors": ["Auto-failover groups", "Zone redundancy", "Active geo-replication"], "tip": "Extends retention out to YEARS for COMPLIANCE — standard automated backups cover only weeks by default, nowhere near long enough for this kind of regulatory hold." , "diagram": "<svg viewBox='0 0 380 120' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-52-3'><title id='dt-p5-52-3'>Retains selected backups far beyond the normal short-term window, for compliance needs.</title><line x1='30' y1='60' x2='350' y2='60' stroke='var(--border)' stroke-width='2'/><rect x='30' y='50' width='90' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.4'/><text x='75' y='64' font-size='6' fill='var(--blue)' text-anchor='middle'>normal 7\u201335d</text><rect x='140' y='50' width='210' height='20' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.4'/><text x='245' y='64' font-size='6.4' fill='var(--primary)' text-anchor='middle'>LTR: up to 10 years</text><text x='16' y='98' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Retains selected backups far beyond the normal short-term window, for</text><text x='16' y='110' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>compliance needs.</text></svg>"},
    { "id": "p1-11-4", "core": "core1", "domain": "p1", "objective": "1.1", "term": "DTU vs. vCore purchasing model", "definition": "DTU bundles compute, memory, and I/O into a single blended unit for simpler sizing; vCore lets you choose compute and storage independently and maps more directly to physical hardware resources, easing on-premises cost comparisons.", "scenario": "size an Azure SQL Database in a way that maps clearly to on-premises hardware specs for an easier cost comparison with the current SQL Server deployment", "distractors": ["Deployment offering choice", "Elastic pool", "Serverless tier"], "tip": "vCore maps DIRECTLY to physical CPU/memory specs — DTU instead bundles everything into one blended number, simpler to pick but harder to directly compare against known on-premises hardware." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-11-4'><title id='dt-p1-11-4'>vCore maps directly to CPU/memory specs; DTU bundles everything into one simpler blended number.</title><rect x='16.0' y='30' width='179.0' height='64' rx='5' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='105.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>DTU</text><text x='105.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>blended compute+I/O unit</text><rect x='205.0' y='30' width='179.0' height='64' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='294.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>vCore</text><text x='294.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>compute/storage set apart</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>vCore maps directly to CPU/memory specs; DTU bundles everything into one simpler</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>blended number.</text></svg>"},
    { "id": "p1-11-5", "core": "core1", "domain": "p1", "objective": "1.1", "term": "Hyperscale service tier", "definition": "An Azure SQL Database compute tier designed for very large databases (up to 100TB), offering fast storage autogrowth and rapid backups independent of database size.", "scenario": "support a rapidly growing database that's expected to exceed the size limits of standard Azure SQL Database tiers", "distractors": ["DTU vs. vCore", "Elastic pool", "Serverless tier"], "tip": "Built specifically for VERY LARGE databases with FAST autogrowth and backups — standard tiers have much lower size ceilings and backup times that scale with database size." , "diagram": "<svg viewBox='0 0 380 138' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-11-5'><title id='dt-p1-11-5'>Built for very large databases \u2014 storage autogrowth and backup time stay fast regardless of size.</title><rect x='30' y='24' width='320' height='60' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='190' y='46' font-size='7.6' fill='var(--primary)' text-anchor='middle' font-weight='700'>Hyperscale tier</text><text x='190' y='62' font-size='6.4' fill='var(--primary)' text-anchor='middle'>up to 100 TB \u2022 fast autogrowth \u2022 rapid backups</text><text x='16' y='116' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Built for very large databases \u2014 storage autogrowth and backup time stay fast</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>regardless of size.</text></svg>"},
    { "id": "p1-11-6", "core": "core1", "domain": "p1", "objective": "1.1", "term": "Serverless vs. provisioned compute", "definition": "Provisioned compute reserves a fixed amount of compute continuously for predictable, steady workloads; serverless auto-scales and can pause, better suited to intermittent or unpredictable workloads.", "scenario": "choose between provisioned and serverless compute for a database with steady, predictable, round-the-clock usage", "distractors": ["DTU vs. vCore", "Hyperscale tier", "Elastic pool"], "tip": "PROVISIONED suits STEADY, predictable load — serverless instead is optimized for INTERMITTENT, spiky usage where pausing during idle time actually saves money." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-11-6'><title id='dt-p1-11-6'>Provisioned suits steady round-the-clock load; serverless fits intermittent, spiky usage.</title><rect x='16.0' y='30' width='179.0' height='64' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='105.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Provisioned</text><text x='105.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>fixed, steady workloads</text><rect x='205.0' y='30' width='179.0' height='64' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='294.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Serverless</text><text x='294.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>auto-scales, can pause</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Provisioned suits steady round-the-clock load; serverless fits intermittent, spiky</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>usage.</text></svg>"},
    { "id": "p1-12-4", "core": "core1", "domain": "p1", "objective": "1.2", "term": "Database sharding", "definition": "Horizontally partitioning a large dataset across multiple independent databases, distributing load and storage beyond what a single database instance could handle alone.", "scenario": "distribute a massive dataset across several independent databases because no single database instance can handle the full data volume alone", "distractors": ["Elastic pool", "Read scale-out", "Serverless tier"], "tip": "SPLITS DATA horizontally across MULTIPLE databases — an elastic pool instead shares COMPUTE resources across databases that each still hold their own complete, separate dataset." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-12-4'><title id='dt-p1-12-4'>Splits one dataset horizontally across multiple independent databases, each holding its own slice.</title><rect x='16.0' y='30' width='116.0' height='64' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='74.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Shard 1</text><text x='74.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>customers A\u2013H</text><rect x='142.0' y='30' width='116.0' height='64' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='200.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Shard 2</text><text x='200.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>customers I\u2013Q</text><rect x='268.0' y='30' width='116.0' height='64' rx='5' fill='var(--violet-soft)' stroke='var(--violet)' stroke-width='1.5'/><text x='326.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Shard 3</text><text x='326.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>customers R\u2013Z</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Splits one dataset horizontally across multiple independent databases, each holding</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>its own slice.</text></svg>"},
    { "id": "p1-12-5", "core": "core1", "domain": "p1", "objective": "1.2", "term": "Resource governor", "definition": "A SQL Server feature that limits the CPU, memory, and I/O resources a specific workload or application can consume, preventing one runaway query from starving others on the same instance.", "scenario": "prevent one poorly-written reporting query from consuming all available server resources and starving other applications sharing the same instance", "distractors": ["Elastic pool", "Read scale-out", "Database sharding"], "tip": "Limits resources WITHIN A SINGLE INSTANCE for different workloads — an elastic pool instead shares resources ACROSS multiple separate databases, a different scope of resource management." , "diagram": "<svg viewBox='0 0 380 163' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-12-5'><title id='dt-p1-12-5'>Limits resources for one workload inside a single instance so it can&#39;t starve others sharing it.</title><rect x='20' y='20' width='340' height='92' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='34' font-size='6.8' fill='var(--text)' text-anchor='middle' font-weight='700'>One SQL Server instance</text><rect x='36' y='46' width='150' height='52' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.6'/><text x='111' y='66' font-size='6.8' fill='var(--red)' text-anchor='middle' font-weight='700'>Reporting pool</text><text x='111' y='80' font-size='6' fill='var(--red)' text-anchor='middle'>CPU/memory capped</text><rect x='196' y='46' width='150' height='52' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.6'/><text x='271' y='66' font-size='6.8' fill='var(--primary)' text-anchor='middle' font-weight='700'>OLTP pool</text><text x='271' y='80' font-size='6' fill='var(--primary)' text-anchor='middle'>protected, uncapped</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Limits resources for one workload inside a single instance so it can&#39;t starve</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>others sharing it.</text></svg>"},
    { "id": "p1-12-6", "core": "core1", "domain": "p1", "objective": "1.2", "term": "Compute tier switching downtime", "definition": "Changing an Azure SQL Database's service tier or compute size typically causes a brief connection interruption as the database moves to new underlying compute resources.", "scenario": "plan a scale-up of a production database's compute tier during a maintenance window, expecting a brief connection interruption during the switch", "distractors": ["Elastic pool", "Serverless auto-pause", "Read scale-out"], "tip": "A BRIEF INTERRUPTION during the SWITCH ITSELF — worth planning around with a maintenance window, distinct from serverless's DELIBERATE pausing during genuine idle periods." , "diagram": "<svg viewBox='0 0 380 197' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-12-6'><title id='dt-p1-12-6'>Plan scale operations around a short connection interruption \u2014 worth a maintenance window.</title><rect x='16' y='14' width='348' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='26' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Scale request submitted</text><text x='190.0' y='39' font-size='7.5' fill='var(--muted)' text-anchor='middle'>new tier/size chosen</text><line x1='190.0' y1='48' x2='190.0' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 53 L190.0 60 L194.0 53' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='61' width='348' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='73' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Brief connection break</text><text x='190.0' y='86' font-size='7.5' fill='var(--text)' text-anchor='middle'>moving to new compute</text><line x1='190.0' y1='95' x2='190.0' y2='102' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 100 L190.0 107 L194.0 100' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='108' width='348' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='120' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>New compute online</text><text x='190.0' y='133' font-size='7.5' fill='var(--muted)' text-anchor='middle'>connections resume</text><text x='16' y='175' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Plan scale operations around a short connection interruption \u2014 worth a</text><text x='16' y='187' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>maintenance window.</text></svg>"},
    { "id": "p1-13-4", "core": "core1", "domain": "p1", "objective": "1.3", "term": "Business continuity SLA tiers", "definition": "Different Azure SQL service tiers offer different guaranteed uptime SLA percentages, with higher tiers and zone-redundant configurations generally providing stronger guarantees.", "scenario": "choose a service tier that meets a contractual 99.99% uptime SLA requirement for a critical production database", "distractors": ["Auto-failover groups", "Active geo-replication", "Zone redundancy"], "tip": "The CONTRACTUAL GUARANTEE ITSELF varies by TIER — auto-failover groups and geo-replication are TECHNICAL MECHANISMS that help an organization actually achieve a given SLA target." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-13-4'><title id='dt-p1-13-4'>The contractual uptime guarantee itself varies by tier \u2014 higher, zone-redundant tiers guarantee more.</title><rect x='16.0' y='30' width='179.0' height='64' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='105.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>General Purpose</text><text x='105.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>\u2264 99.99%</text><rect x='205.0' y='30' width='179.0' height='64' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='294.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Business Critical</text><text x='294.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>\u2264 99.995% zone-redundant</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The contractual uptime guarantee itself varies by tier \u2014 higher, zone-redundant</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>tiers guarantee more.</text></svg>"},
    { "id": "p1-13-5", "core": "core1", "domain": "p1", "objective": "1.3", "term": "Backup storage redundancy options", "definition": "Azure SQL automated backups can be stored with locally redundant (LRS), zone-redundant (ZRS), or geo-redundant (GRS) storage, trading cost against protection against different failure scopes.", "scenario": "choose backup storage redundancy that protects against an entire Azure region becoming unavailable, not just a single datacenter", "distractors": ["Zone redundancy (compute)", "Auto-failover groups", "Point-in-time restore"], "tip": "GRS protects against a whole REGION failing — ZRS only protects against a single DATACENTER (zone) failing within one region, a narrower scope of protection." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-13-5'><title id='dt-p1-13-5'>Each step widens the failure scope backups survive \u2014 from one datacenter up to a whole region.</title><rect x='16.0' y='30' width='116.0' height='64' rx='5' fill='var(--surface-3)' stroke='var(--muted)' stroke-width='1.5'/><text x='74.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>LRS</text><text x='74.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>one datacenter</text><rect x='142.0' y='30' width='116.0' height='64' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='200.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>ZRS</text><text x='200.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>across zones, one region</text><rect x='268.0' y='30' width='116.0' height='64' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='326.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>GRS</text><text x='326.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>paired region too</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Each step widens the failure scope backups survive \u2014 from one datacenter up to a</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>whole region.</text></svg>"},
    { "id": "p1-13-6", "core": "core1", "domain": "p1", "objective": "1.3", "term": "Point-in-time restore", "definition": "A feature that restores an Azure SQL Database to any specific point within its retention window, commonly used to recover from an accidental data deletion or corruption.", "scenario": "recover a database to its exact state five minutes before someone accidentally ran a destructive DELETE statement without a WHERE clause", "distractors": ["Auto-failover groups", "Active geo-replication", "Backup redundancy"], "tip": "Recovers to an EXACT MOMENT IN TIME — auto-failover groups and geo-replication instead protect against INFRASTRUCTURE failures, not against an accidental bad query against otherwise-healthy infrastructure." , "diagram": "<svg viewBox='0 0 380 126' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-13-6'><title id='dt-p1-13-6'>Restores to any point inside the retention window \u2014 pick the moment right before the mistake.</title><line x1='30' y1='60' x2='350' y2='60' stroke='var(--border)' stroke-width='2'/><circle cx='150' cy='60' r='6' fill='var(--green)'/><text x='150' y='42' font-size='6.6' fill='var(--green)' text-anchor='middle' font-weight='700'>Restore target</text><text x='150' y='82' font-size='6' fill='var(--green)' text-anchor='middle'>5 min before</text><circle cx='260' cy='60' r='6' fill='var(--red)'/><text x='260' y='42' font-size='6.6' fill='var(--red)' text-anchor='middle' font-weight='700'>Bad DELETE</text><text x='260' y='82' font-size='6' fill='var(--red)' text-anchor='middle'>ran here</text><text x='16' y='104' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Restores to any point inside the retention window \u2014 pick the moment right</text><text x='16' y='116' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>before the mistake.</text></svg>"},
    { "id": "p1-14-1", "core": "core1", "domain": "p1", "objective": "1.4", "term": "Azure Arc-enabled SQL services", "definition": "Azure Arc extends Azure management to SQL Server instances that stay outside Azure through an agent, adding inventory, Microsoft Defender for SQL, Microsoft Entra authentication, and best-practices assessment; Arc-enabled SQL Managed Instance runs the managed-instance engine on Kubernetes you operate.", "scenario": "manage and secure on-premises SQL Server instances from the Azure portal without migrating them", "distractors": ["Azure SQL Managed Instance", "SQL Server on Azure Virtual Machines", "Azure Database Migration Service"], "tip": "It gives Azure management to servers that STAY where they are — migrating them into Azure is a different path.", "diagram": "<svg viewBox='0 0 380 158' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-14-1'><title id='dt-p1-14-1'>Azure Arc brings Azure inventory, security, and sign-in to SQL Server that stays on-premises.</title><rect x='115' y='14' width='150' height='34' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.3'/><text x='190' y='27.86' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Azure Arc</text><text x='190' y='39.26' font-size='6.4' fill='var(--muted)' text-anchor='middle'>manages SQL outside Azure</text><line x1='190' y1='48' x2='70' y2='69.5' stroke='var(--border)' stroke-width='1.2'/><rect x='16' y='70' width='108' height='40' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='70' y='86.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Inventory</text><text x='70' y='97.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>instances and versions</text><line x1='190' y1='48' x2='190' y2='69.5' stroke='var(--border)' stroke-width='1.2'/><rect x='136' y='70' width='108' height='40' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='86.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Defender for SQL</text><text x='190' y='97.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>threat protection</text><line x1='190' y1='48' x2='310' y2='69.5' stroke='var(--border)' stroke-width='1.2'/><rect x='256' y='70' width='108' height='40' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='310' y='86.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Entra authentication</text><text x='310' y='97.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>central sign-in</text><text x='16' y='134' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Azure Arc brings Azure inventory, security, and sign-in to SQL Server</text><text x='16' y='146' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>that stays on-premises.</text></svg>" },
    { "id": "p1-14-2", "core": "core1", "domain": "p1", "objective": "1.4", "term": "Azure SQL Database in Microsoft Fabric", "definition": "A transactional database built on the Azure SQL Database engine that is created and managed inside Microsoft Fabric, with its data replicated automatically to OneLake for analytics, aimed at application workloads that sit beside analytics.", "scenario": "give an application team a transactional SQL database that is available to Fabric analytics automatically, with no pipeline to build", "distractors": ["Azure SQL Managed Instance", "SQL Server on Azure Virtual Machines", "An elastic pool"], "tip": "It runs INSIDE Fabric and mirrors to OneLake — a standalone Azure SQL Database lives in your own Azure subscription.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-14-2'><title id='dt-p1-14-2'>SQL database in Fabric is a transactional Azure SQL database inside Fabric that feeds OneLake automatically.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>SQL database in Fabric</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Fabric workspace</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>creates the database</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>SQL engine</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>Azure SQL Database</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>OneLake</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>data copied automatically</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>SQL database in Fabric is a transactional Azure SQL database inside</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Fabric that feeds OneLake automatically.</text></svg>" },
    { "id": "p1-14-3", "core": "core1", "domain": "p1", "objective": "1.4", "term": "Rolling patching of replicas", "definition": "On SQL Server running on Azure VMs or hybrid servers you own operating system and SQL Server patching: schedule it in a maintenance window, patch secondary replicas first, perform a planned failover, then patch the former primary.", "scenario": "apply a cumulative update to an availability group on Azure VMs with minimal downtime", "distractors": ["Patch the primary first", "Patch every replica at once", "Wait for Microsoft to patch it"], "tip": "Secondaries FIRST, then fail over — on IaaS the patching is your job, unlike PaaS.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-14-3'><title id='dt-p1-14-3'>Patch secondaries first, fail over in a planned way, then patch the former primary.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Rolling patch</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Patch secondary</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>primary keeps serving</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Planned failover</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>no data loss</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Patch old primary</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>then rejoin the group</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Patch secondaries first, fail over in a planned way, then patch the</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>former primary.</text></svg>" },
    { "id": "p1-14-4", "core": "core1", "domain": "p1", "objective": "1.4", "term": "Hybrid SQL Server solution", "definition": "An architecture where SQL Server stays on-premises while Azure supplies part of the solution, such as a disaster recovery replica, a Managed Instance link target, backups to Blob storage, or Arc-based management.", "scenario": "keep the primary SQL Server on-premises while using Azure as the disaster recovery site", "distractors": ["A single Azure SQL Database", "An elastic pool", "The serverless compute tier"], "tip": "The primary stays ON-PREMISES with Azure as a partner — it is not a migration.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-14-4'><title id='dt-p1-14-4'>A hybrid solution keeps SQL Server on-premises and uses Azure for DR, backups, or management.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Hybrid layout</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>On-premises</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Primary SQL Server</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Local applications</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Full control</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Azure</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>DR replica or MI link</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Backups to Blob storage</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Arc management</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A hybrid solution keeps SQL Server on-premises and uses Azure for DR,</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>backups, or management.</text></svg>" },
    { "id": "p1-14-5", "core": "core1", "domain": "p1", "objective": "1.4", "term": "Declarative deployment (Bicep or ARM)", "definition": "Describing the desired end state of Azure resources in a Bicep or ARM template that Azure reconciles, which is repeatable and can be previewed with what-if, unlike an imperative script that lists the steps.", "scenario": "choose a repeatable deployment method that describes the desired state of SQL resources and can be previewed before it runs", "distractors": ["Clicking through the Azure portal", "A one-off script with no template", "Cloud Shell command history"], "tip": "Declare the END STATE and preview with what-if — imperative scripts describe steps and drift easily.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-14-5'><title id='dt-p1-14-5'>Declarative templates state the end result and can be previewed; scripts state the steps.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Choosing a deployment method</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Declarative</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Bicep or ARM template</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Describes the end state</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>what-if preview</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Imperative</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>PowerShell or CLI script</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Lists the steps</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Easy to drift</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Declarative templates state the end result and can be previewed; scripts</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>state the steps.</text></svg>" },
    { "id": "p1-15-1", "core": "core1", "domain": "p1", "objective": "1.5", "term": "Table partitioning", "definition": "Dividing a large table into partitions by a column such as date using a partition function and scheme, so maintenance, loading, and archiving can work on one partition at a time within a single database.", "scenario": "archive the oldest month of a very large table without a long, logged DELETE", "distractors": ["Database sharding", "Data compression", "A columnstore index"], "tip": "ONE database with many partitions — sharding spreads data across separate databases.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-15-1'><title id='dt-p1-15-1'>Table partitioning splits a big table by a key so each partition can be managed on its own.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Building a partitioned table</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Partition function</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>boundary values</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Partition scheme</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>maps to filegroups</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Partitioned table</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>switch or merge</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Table partitioning splits a big table by a key so each partition can be</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>managed on its own.</text></svg>" },
    { "id": "p1-15-2", "core": "core1", "domain": "p1", "objective": "1.5", "term": "Partition switching", "definition": "ALTER TABLE ... SWITCH PARTITION is a metadata-only operation that moves an entire partition in or out of a table almost instantly, used for fast loads and archiving.", "scenario": "load a month of staged data into a fact table in seconds with a metadata-only operation", "distractors": ["INSERT ... SELECT", "BULK INSERT", "bcp import"], "tip": "It moves a whole partition by changing METADATA — the other options physically copy every row.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-15-2'><title id='dt-p1-15-2'>Switching moves a whole partition between tables as a near-instant metadata change.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Partition switching</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Staging table</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>matches the structure</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>SWITCH PARTITION</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>metadata only</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Fact table</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>new partition appears</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Switching moves a whole partition between tables as a near-instant</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>metadata change.</text></svg>" },
    { "id": "p1-15-3", "core": "core1", "domain": "p1", "objective": "1.5", "term": "Partition elimination", "definition": "The optimizer reads only the partitions that can contain the requested rows when a query filters on the partition key, reducing I/O on large partitioned tables.", "scenario": "make a date-range query read only the relevant month's partition of a partitioned table", "distractors": ["Partition switching", "Row compression", "An index rebuild"], "tip": "It depends on filtering by the PARTITION KEY — without that predicate every partition is scanned.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-15-3'><title id='dt-p1-15-3'>Filtering on the partition key lets the optimizer skip partitions that cannot match.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Partition elimination</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Filter on the key</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>WHERE OrderDate in a range</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Only matching partitions read</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Less I/O</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>No key filter</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>WHERE on another column</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Every partition scanned</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>No benefit</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Filtering on the partition key lets the optimizer skip partitions that</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>cannot match.</text></svg>" },
    { "id": "p1-15-4", "core": "core1", "domain": "p1", "objective": "1.5", "term": "Row and page data compression", "definition": "ROW compression stores fixed-length data compactly and PAGE compression adds prefix and dictionary compression on top, saving storage and I/O at a CPU cost; sp_estimate_data_compression_savings predicts the benefit before ALTER ... REBUILD WITH (DATA_COMPRESSION = PAGE).", "scenario": "reduce storage and I/O for a large read-heavy table by trading some CPU, after estimating the savings first", "distractors": ["Transparent data encryption", "Partition switching", "Database sharding"], "tip": "PAGE saves more than ROW but costs more CPU — estimate the savings before rebuilding.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-15-4'><title id='dt-p1-15-4'>Row and page compression trade CPU for smaller storage and less I/O; estimate savings first.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Data compression levels</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>ROW</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Compact fixed-length types</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Lower CPU cost</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Smaller saving</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>PAGE</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Row plus prefix and dictionary</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Higher CPU cost</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Bigger saving</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Row and page compression trade CPU for smaller storage and less I/O;</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>estimate savings first.</text></svg>" },
    { "id": "p1-16-1", "core": "core1", "domain": "p1", "objective": "1.6", "term": "Offline migration", "definition": "A migration in which the source is unavailable or read-only while data is copied, using methods such as BACPAC export and import, native backup and restore, or Database Migration Service offline mode; it is simpler but requires an outage window.", "scenario": "migrate a small departmental database where a weekend outage is acceptable", "distractors": ["Online migration", "Continuous transactional replication", "Active geo-replication"], "tip": "The source is down or read-only during the copy — online migration keeps syncing until cutover.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-16-1'><title id='dt-p1-16-1'>Offline migration copies data while the source is unavailable, so it needs an outage window.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Offline migration</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Stop writes</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>outage begins</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Copy data</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>backup, BACPAC, DMS</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Cut over</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>point apps at Azure</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Offline migration copies data while the source is unavailable, so it</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>needs an outage window.</text></svg>" },
    { "id": "p1-16-2", "core": "core1", "domain": "p1", "objective": "1.6", "term": "Online migration", "definition": "A migration in which the source stays operational while changes are continuously synchronized to the target, leaving only a short cutover window; examples are Database Migration Service online mode, Log Replay Service, and the Managed Instance link.", "scenario": "migrate a 24/7 order system with only minutes of downtime allowed", "distractors": ["Offline migration", "A BACPAC import", "A one-time native restore"], "tip": "The source keeps WORKING while changes sync — only the final cutover causes downtime.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-16-2'><title id='dt-p1-16-2'>Online migration keeps the source running and syncs changes until a brief cutover.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Online migration</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Initial copy</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>source stays online</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Sync changes</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>continuously</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Cutover</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>minutes of downtime</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Online migration keeps the source running and syncs changes until a</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>brief cutover.</text></svg>" },
    { "id": "p1-16-3", "core": "core1", "domain": "p1", "objective": "1.6", "term": "Azure Database Migration Service (DMS)", "definition": "A managed service that moves databases from SQL Server to Azure SQL targets, with assessment and both offline and online modes, so you do not have to build and monitor the transfer yourself.", "scenario": "run a managed, assessed migration from on-premises SQL Server to Azure SQL Managed Instance", "distractors": ["A BACPAC export and import", "Transactional replication", "SSMS Generate Scripts"], "tip": "A managed service with online AND offline modes — a BACPAC is a manual file transfer.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-16-3'><title id='dt-p1-16-3'>DMS assesses and migrates SQL Server databases to Azure SQL, offline or online.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Using DMS</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Assess</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>find blockers</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Migrate</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>offline or online</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Cut over</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>validate, switch apps</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>DMS assesses and migrates SQL Server databases to Azure SQL, offline or</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>online.</text></svg>" },
    { "id": "p1-16-4", "core": "core1", "domain": "p1", "objective": "1.6", "term": "Log Replay Service (LRS)", "definition": "A service that migrates databases to SQL Managed Instance by continuously restoring native full and log backups from Blob storage, allowing a controlled cutover at a time you choose.", "scenario": "migrate a large database to Managed Instance by restoring backups from Blob storage and cutting over at a chosen moment", "distractors": ["A BACPAC import", "Managed Instance link", "An Azure Data Factory copy"], "tip": "It keeps RESTORING backups from storage until you cut over — the MI link uses a distributed availability group instead.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-16-4'><title id='dt-p1-16-4'>Log Replay Service restores backups from Blob storage continuously until you complete the cutover.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Log Replay Service</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Backups</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>to Blob storage</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>LRS restores</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>full, then log backups</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Cutover</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>complete and switch</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Log Replay Service restores backups from Blob storage continuously until</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>you complete the cutover.</text></svg>" },
    { "id": "p1-16-5", "core": "core1", "domain": "p1", "objective": "1.6", "term": "Managed Instance link", "definition": "A feature that uses a distributed availability group to replicate near real time from SQL Server to Managed Instance (and in supported cases back), for disaster recovery, read offloading, or an online migration.", "scenario": "replicate an on-premises SQL Server to Managed Instance in near real time for read scale-out and a later low-downtime cutover", "distractors": ["Log shipping", "A BACPAC import", "DMS offline mode"], "tip": "A near REAL-TIME distributed availability group — Log Replay Service restores backups in batches.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-16-5'><title id='dt-p1-16-5'>The MI link replicates SQL Server to Managed Instance in near real time using a distributed availability group.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Managed Instance link</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>SQL Server</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>primary replica</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Distributed AG</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>near real time</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Managed Instance</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>readable secondary</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The MI link replicates SQL Server to Managed Instance in near real time</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>using a distributed availability group.</text></svg>" },
    { "id": "p1-16-6", "core": "core1", "domain": "p1", "objective": "1.6", "term": "BACPAC export and import", "definition": "A BACPAC is a portable file holding a database's schema and data, created and loaded with SqlPackage or the portal; it works for Azure SQL Database where native backups do not, but is slow for very large databases and not transactionally consistent unless the source is quiesced.", "scenario": "move a small Azure SQL Database to another server when native backup and restore is not available", "distractors": ["A native RESTORE FROM URL", "A DACPAC deployment", "Log shipping"], "tip": "Schema plus DATA in one portable file — a DACPAC carries the schema only.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-16-6'><title id='dt-p1-16-6'>A BACPAC carries schema and data for portable moves; a DACPAC carries the schema only.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>BACPAC vs DACPAC</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>BACPAC</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Schema and data</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Export then import</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Slow for huge databases</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>DACPAC</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Schema only</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Deploy or upgrade</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>No table data</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A BACPAC carries schema and data for portable moves; a DACPAC carries</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>the schema only.</text></svg>" },
    { "id": "p1-16-7", "core": "core1", "domain": "p1", "objective": "1.6", "term": "Native restore from URL to Managed Instance", "definition": "Managed Instance can restore native COPY_ONLY backups placed in Azure Blob storage with RESTORE DATABASE ... FROM URL, an offline method that preserves the source database; Azure SQL Database does not support native restore.", "scenario": "migrate a SQL Server database to Managed Instance by taking a copy-only backup to Blob storage and restoring it", "distractors": ["A BACPAC import", "Azure SQL Database native restore", "Log shipping to Azure SQL Database"], "tip": "MI supports native RESTORE FROM URL — Azure SQL Database does not, which is why BACPAC exists for it.", "diagram": "<svg viewBox='0 0 380 156' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-16-7'><title id='dt-p1-16-7'>Managed Instance restores native copy-only backups from Blob storage; Azure SQL Database cannot.</title><rect x='16' y='16' width='348' height='20' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><circle cx='28' cy='26' r='3' fill='var(--red)'/><circle cx='38' cy='26' r='3' fill='var(--amber)'/><circle cx='48' cy='26' r='3' fill='var(--green)'/><text x='190' y='30' font-size='7' fill='var(--muted)' text-anchor='middle'>T-SQL</text><rect x='16' y='36' width='348' height='72' rx='0' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='28' y='54' font-size='8' fill='var(--primary)' text-anchor='start' font-family='monospace' style='white-space:pre'>BACKUP DATABASE Sales TO URL =</text><text x='28' y='68' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>  &#39;https://acct.blob.core.windows.net/bk/Sales.bak&#39;</text><text x='28' y='82' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>  WITH COPY_ONLY, COMPRESSION;</text><text x='28' y='96' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>RESTORE DATABASE Sales FROM URL = ...</text><text x='16' y='132' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Managed Instance restores native copy-only backups from Blob storage;</text><text x='16' y='144' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Azure SQL Database cannot.</text></svg>" },
    { "id": "p1-16-8", "core": "core1", "domain": "p1", "objective": "1.6", "term": "Managed Instance database copy and move", "definition": "A managed capability for copying a database to, or moving it between, SQL managed instances, for example to rebalance workloads or split a busy instance, without manually taking and restoring native backups.", "scenario": "move a database from one busy Managed Instance to another without taking and restoring backups by hand", "distractors": ["A BACPAC export and import", "Active geo-replication", "An elastic pool move"], "tip": "It is a built-in COPY or MOVE between managed instances — geo-replication targets Azure SQL Database, not instance rebalancing.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-16-8'><title id='dt-p1-16-8'>Managed Instance can copy or move a database between instances without hand-made backups.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Copy and move</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Source instance</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>busy managed instance</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Copy or move</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>service handles the data</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Target instance</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>database available</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Managed Instance can copy or move a database between instances without</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>hand-made backups.</text></svg>" },
    { "id": "p1-16-9", "core": "core1", "domain": "p1", "objective": "1.6", "term": "Orphaned users after a migration", "definition": "A restored or migrated database carries its users but not the server-level logins, so users appear orphaned and cannot sign in until the login is recreated with the same SID or the user is remapped to an existing login.", "scenario": "fix database users that cannot sign in after a database was restored to a new server where their logins do not exist", "distractors": ["Re-running the migration offline", "Resetting the compatibility level", "Updating statistics"], "tip": "Logins live in master and users in the database — recreate the login with the same SID or remap the user.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-16-9'><title id='dt-p1-16-9'>After a restore, recreate the missing logins or remap the users so they can sign in again.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Orphaned users</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Restore database</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>users come along</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>No matching login</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>users are orphaned</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Recreate or remap</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>same SID or ALTER USER</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>After a restore, recreate the missing logins or remap the users so they</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>can sign in again.</text></svg>" },
    { "id": "p1-16-10", "core": "core1", "domain": "p1", "objective": "1.6", "term": "Compatibility level after migration", "definition": "A migrated database keeps its compatibility level until you change it; keeping the original level first, testing with Query Store, and then raising it step by step avoids surprise plan regressions.", "scenario": "avoid sudden query regressions after migrating a database to a newer SQL engine version", "distractors": ["Raising the level on day one without testing", "Dropping the database and recreating it", "Disabling Query Store"], "tip": "Migrate first, then raise the compatibility level in a controlled step with Query Store as the safety net.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p1-16-10'><title id='dt-p1-16-10'>Raise the compatibility level only after migrating and capturing a Query Store baseline.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Raising compatibility level</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Migrate</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>keep the old level</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Capture baseline</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>Query Store on</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Raise the level</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>compare, force plans</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Raise the compatibility level only after migrating and capturing a Query</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Store baseline.</text></svg>" },
    { "id": "p2-21-4", "core": "core1", "domain": "p2", "objective": "2.1", "term": "Microsoft Entra ID admin assignment", "definition": "Designating a specific Microsoft Entra ID user or group as the administrator for a logical SQL server, which can then manage Microsoft Entra ID authentication for all databases on that server.", "scenario": "designate a specific Microsoft Entra ID security group as the administrator for a logical SQL server, enabling centralized Microsoft Entra ID-based access management", "distractors": ["SQL authentication login", "Contained database user", "Server-level role"], "tip": "A SERVER-LEVEL designation enabling AZURE AD auth management broadly — distinct from a contained database user, which is a specific USER granted access to just ONE database." , "diagram": "<svg viewBox='0 0 380 148' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-21-4'><title id='dt-p2-21-4'>One centralized assignment manages Entra ID authentication for every database on the server.</title><rect x='110' y='18' width='160' height='40' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190' y='36' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>Logical SQL server</text><text x='190' y='49' font-size='6' fill='var(--primary)' text-anchor='middle'>AAD admin: Security Group</text><line x1='190' y1='58' x2='190' y2='68' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 66 L190 73 L194 66' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='5' y='76' width='90' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='50' y='97' font-size='6.6' fill='var(--text)' text-anchor='middle'>DB 1</text><rect x='145' y='76' width='90' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='97' font-size='6.6' fill='var(--text)' text-anchor='middle'>DB 2</text><rect x='285' y='76' width='90' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='330' y='97' font-size='6.6' fill='var(--text)' text-anchor='middle'>DB 3</text><text x='16' y='125' font-size='8.5' fill='var(--muted)' text-anchor='start'>One centralized assignment manages Entra ID authentication for every database</text><text x='16' y='137' font-size='8.5' fill='var(--muted)' text-anchor='start'>on the server.</text></svg>"},
    { "id": "p2-21-5", "core": "core1", "domain": "p2", "objective": "2.1", "term": "Login vs. user distinction", "definition": "A login authenticates at the server level and grants access to the server itself; a user is mapped within a specific database and grants permissions inside that database.", "scenario": "understand why a login that can connect to the server still can't query a specific database until a corresponding user is created inside it", "distractors": ["Contained database users", "Server-level roles", "Database-level roles"], "tip": "LOGIN gets you IN THE DOOR at the server; USER is what lets you actually DO something inside a SPECIFIC database — both steps are needed for normal (non-contained) access." , "diagram": "<svg viewBox='0 0 380 146' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-21-5'><title id='dt-p2-21-5'>Both steps are required for normal (non-contained) access \u2014 a login alone can&#39;t query a database.</title><rect x='16' y='16' width='348' height='38' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='30' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Login</text><text x='190.0' y='43' font-size='7.5' fill='var(--muted)' text-anchor='middle'>authenticates at the server, gets you in the door</text><line x1='190.0' y1='54' x2='190.0' y2='64' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 62 L190.0 69 L194.0 62' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='70' width='348' height='38' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='84' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>User</text><text x='190.0' y='97' font-size='7.5' fill='var(--text)' text-anchor='middle'>mapped inside a specific database, grants permissions there</text><text x='16' y='124' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Both steps are required for normal (non-contained) access \u2014 a login alone can&#39;t</text><text x='16' y='136' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>query a database.</text></svg>"},
    { "id": "p2-21-6", "core": "core1", "domain": "p2", "objective": "2.1", "term": "Custom database roles", "definition": "User-defined roles created within a database that group a specific, tailored set of permissions, used when the built-in fixed database roles don't precisely match a needed permission set.", "scenario": "grant a group of users exactly the ability to execute stored procedures and read two specific tables, a combination the built-in fixed roles don't precisely offer", "distractors": ["Server-level roles", "Contained database users", "Microsoft Entra ID admin"], "tip": "TAILORS a PRECISE permission set when built-in FIXED roles don't fit — the flexible option for permission combinations that don't map neatly onto the standard predefined roles." , "diagram": "<svg viewBox='0 0 380 142' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-21-6'><title id='dt-p2-21-6'>User-defined roles group an exact, tailored permission set when built-in fixed roles don&#39;t fit.</title><rect x='20' y='20' width='160' height='84' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5' stroke-dasharray='2 2'/><text x='100' y='36' font-size='6.8' fill='var(--muted)' text-anchor='middle' font-weight='700'>Fixed roles</text><text x='100' y='52' font-size='6' fill='var(--muted)' text-anchor='middle'>don&#39;t quite match</text><text x='100' y='64' font-size='6' fill='var(--muted)' text-anchor='middle'>the needed</text><text x='100' y='76' font-size='6' fill='var(--muted)' text-anchor='middle'>permission set</text><rect x='200' y='20' width='160' height='84' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='280' y='36' font-size='6.8' fill='var(--primary)' text-anchor='middle' font-weight='700'>Custom role</text><text x='280' y='52' font-size='6' fill='var(--primary)' text-anchor='middle'>EXEC on 2 procs +</text><text x='280' y='64' font-size='6' fill='var(--primary)' text-anchor='middle'>SELECT on 2 tables</text><text x='280' y='76' font-size='6' fill='var(--primary)' text-anchor='middle'>\u2014 exact tailored fit</text><text x='16' y='120' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>User-defined roles group an exact, tailored permission set when built-in fixed</text><text x='16' y='132' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>roles don&#39;t fit.</text></svg>"},
    { "id": "p2-21-7", "core": "core1", "domain": "p2", "objective": "2.1", "term": "Creating users from Microsoft Entra identities", "definition": "With a Microsoft Entra admin set on the server, CREATE USER [name] FROM EXTERNAL PROVIDER creates a contained database user for an Entra user, group, or application, which then receives permissions through roles.", "scenario": "give an Entra group access to one database by creating a user for it with T-SQL", "distractors": ["CREATE LOGIN ... WITH PASSWORD", "CREATE USER ... WITHOUT LOGIN", "sp_addlogin"], "tip": "FROM EXTERNAL PROVIDER means a Microsoft Entra identity — run it while connected as an Entra account.", "diagram": "<svg viewBox='0 0 380 142' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-21-7'><title id='dt-p2-21-7'>FROM EXTERNAL PROVIDER creates a database user for a Microsoft Entra user, group, or application.</title><rect x='16' y='16' width='348' height='20' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><circle cx='28' cy='26' r='3' fill='var(--red)'/><circle cx='38' cy='26' r='3' fill='var(--amber)'/><circle cx='48' cy='26' r='3' fill='var(--green)'/><text x='190' y='30' font-size='7' fill='var(--muted)' text-anchor='middle'>T-SQL</text><rect x='16' y='36' width='348' height='58' rx='0' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='28' y='54' font-size='8' fill='var(--primary)' text-anchor='start' font-family='monospace' style='white-space:pre'>-- connected as the Entra admin</text><text x='28' y='68' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>CREATE USER [dba-team] FROM EXTERNAL PROVIDER;</text><text x='28' y='82' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>ALTER ROLE db_datareader ADD MEMBER [dba-team];</text><text x='16' y='118' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>FROM EXTERNAL PROVIDER creates a database user for a Microsoft Entra</text><text x='16' y='130' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>user, group, or application.</text></svg>" },
    { "id": "p2-21-8", "core": "core1", "domain": "p2", "objective": "2.1", "term": "Microsoft Entra-only authentication", "definition": "A server setting that disables SQL authentication entirely, so only Microsoft Entra identities (including managed identities) can sign in, enabling MFA, Conditional Access, and central lifecycle control.", "scenario": "force every connection to use Entra identities with MFA and Conditional Access and disable SQL logins", "distractors": ["Contained database users", "Assigning an Entra admin", "Always Encrypted"], "tip": "It turns SQL authentication OFF completely — an Entra admin alone still allows SQL logins.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-21-8'><title id='dt-p2-21-8'>Entra-only authentication disables SQL logins so every sign-in goes through Microsoft Entra ID.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Authentication modes</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Both methods on</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>SQL logins still work</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Passwords can be shared</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Weaker audit trail</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Entra-only</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>SQL authentication disabled</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>MFA and Conditional Access</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Central lifecycle control</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Entra-only authentication disables SQL logins so every sign-in goes</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>through Microsoft Entra ID.</text></svg>" },
    { "id": "p2-21-9", "core": "core1", "domain": "p2", "objective": "2.1", "term": "Managed identity authentication", "definition": "An Azure-managed identity lets an application, such as an App Service or Function, connect to the database with no password stored anywhere, after a database user is created for that identity FROM EXTERNAL PROVIDER.", "scenario": "let an App Service connect to the database with no password in its configuration", "distractors": ["SQL authentication with a stored password", "A shared access signature", "A service endpoint"], "tip": "The identity belongs to the AZURE RESOURCE — there is no secret to store, leak, or rotate.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-21-9'><title id='dt-p2-21-9'>A managed identity signs an Azure app in to the database without any stored password.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Passwordless access</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>App Service</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>has a managed identity</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Database user</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>created for that identity</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Token sign-in</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>no password stored</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A managed identity signs an Azure app in to the database without any</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>stored password.</text></svg>" },
    { "id": "p2-21-10", "core": "core1", "domain": "p2", "objective": "2.1", "term": "DENY (overrides GRANT)", "definition": "GRANT gives a permission, DENY explicitly blocks it and overrides any GRANT, including one inherited through a role, and REVOKE removes a previous GRANT or DENY; granting on schemas and roles supports least privilege.", "scenario": "stop one user from reading a sensitive table even though a role they belong to can read it", "distractors": ["REVOKE", "GRANT", "Removing the user from the database"], "tip": "DENY beats GRANT — REVOKE only removes an entry and would leave the role's access in place.", "diagram": "<svg viewBox='0 0 380 146' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-21-10'><title id='dt-p2-21-10'>DENY overrides GRANT, and REVOKE simply removes either one.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Permission statements</text><rect x='16' y='30' width='104.4' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='68.2' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Statement</text><rect x='120.4' y='30' width='243.6' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='242.2' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Effect</text><rect x='16' y='50' width='104.4' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='68.2' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>GRANT</text><rect x='120.4' y='50' width='243.6' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='242.2' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>allows the permission</text><rect x='16' y='70' width='104.4' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='68.2' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>DENY</text><rect x='120.4' y='70' width='243.6' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='242.2' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>blocks it, overrides GRANT</text><rect x='16' y='90' width='104.4' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='68.2' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>REVOKE</text><rect x='120.4' y='90' width='243.6' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='242.2' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>removes a GRANT or DENY</text><text x='16' y='134' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>DENY overrides GRANT, and REVOKE simply removes either one.</text></svg>" },
    { "id": "p2-21-11", "core": "core1", "domain": "p2", "objective": "2.1", "term": "Effective permissions check", "definition": "sys.fn_my_permissions and HAS_PERMS_BY_NAME report what the current user can actually do after role membership, GRANTs, and DENYs combine, which is the starting point for a permission denied (error 229) problem.", "scenario": "work out why a user in a reader role still gets \"SELECT permission was denied\" on one table", "distractors": ["Resetting the user's password", "Raising the service tier", "Rebuilding the table's indexes"], "tip": "A DENY somewhere beats the role's GRANT — check EFFECTIVE permissions, not just membership.", "diagram": "<svg viewBox='0 0 380 142' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-21-11'><title id='dt-p2-21-11'>Checking effective permissions shows the combined result of roles, GRANTs, and DENYs.</title><rect x='16' y='16' width='348' height='20' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><circle cx='28' cy='26' r='3' fill='var(--red)'/><circle cx='38' cy='26' r='3' fill='var(--amber)'/><circle cx='48' cy='26' r='3' fill='var(--green)'/><text x='190' y='30' font-size='7' fill='var(--muted)' text-anchor='middle'>T-SQL</text><rect x='16' y='36' width='348' height='58' rx='0' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='28' y='54' font-size='8' fill='var(--primary)' text-anchor='start' font-family='monospace' style='white-space:pre'>SELECT * FROM sys.fn_my_permissions(&#39;dbo.Salary&#39;,&#39;OBJECT&#39;);</text><text x='28' y='68' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>SELECT HAS_PERMS_BY_NAME(&#39;dbo.Salary&#39;,&#39;OBJECT&#39;,&#39;SELECT&#39;);</text><text x='28' y='82' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>-- 0 means the user cannot SELECT</text><text x='16' y='118' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Checking effective permissions shows the combined result of roles,</text><text x='16' y='130' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>GRANTs, and DENYs.</text></svg>" },
    { "id": "p2-21-12", "core": "core1", "domain": "p2", "objective": "2.1", "term": "Login failed (error 18456) and firewall errors", "definition": "Error 18456 means authentication failed and its state number says why (state 8 a wrong password, state 5 an unknown login), whereas error 40615 means the server firewall blocked the client IP and 40613 means the database is unavailable.", "scenario": "tell whether a failed connection is a wrong password or an unknown login using the number in the error", "distractors": ["Error 40615", "Error 1205 (deadlock victim)", "Error 1222 (lock timeout)"], "tip": "18456 plus its STATE gives the reason — 40615 is the firewall, which is a different problem.", "diagram": "<svg viewBox='0 0 380 178' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-21-12'><title id='dt-p2-21-12'>Error 18456 states identify authentication failures; 40615 points to the firewall instead.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Common connection errors</text><rect x='16' y='30' width='139.2' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='85.6' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Error</text><rect x='155.2' y='30' width='208.8' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='259.6' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Meaning</text><rect x='16' y='50' width='139.2' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='85.6' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>18456, state 8</text><rect x='155.2' y='50' width='208.8' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='259.6' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>wrong password</text><rect x='16' y='70' width='139.2' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='85.6' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>18456, state 5</text><rect x='155.2' y='70' width='208.8' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='259.6' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>unknown login</text><rect x='16' y='90' width='139.2' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='85.6' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>40615</text><rect x='155.2' y='90' width='208.8' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='259.6' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>firewall blocked the IP</text><rect x='16' y='110' width='139.2' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='85.6' y='123.2' font-size='7' fill='var(--text)' text-anchor='middle'>40613</text><rect x='155.2' y='110' width='208.8' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='259.6' y='123.2' font-size='7' fill='var(--text)' text-anchor='middle'>database unavailable</text><text x='16' y='154' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Error 18456 states identify authentication failures; 40615 points to the</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>firewall instead.</text></svg>" },
    { "id": "p2-22-4", "core": "core1", "domain": "p2", "objective": "2.2", "term": "TDE with customer-managed keys (BYOK)", "definition": "Configuring Transparent Data Encryption to use an encryption key stored and controlled in Azure Key Vault, rather than a Microsoft-managed key, giving the customer direct control over key rotation and revocation.", "scenario": "satisfy a compliance requirement that the organization, not the cloud provider, must directly control the encryption key used to protect data at rest", "distractors": ["Service-managed TDE key", "Always Encrypted", "TLS enforcement"], "tip": "CUSTOMER controls the KEY directly via Key Vault — the default service-managed key instead is fully managed BY Microsoft, which some compliance requirements specifically disallow." , "diagram": "<svg viewBox='0 0 400 136' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-22-4'><title id='dt-p2-22-4'>Customer controls key rotation/revocation directly \u2014 some compliance rules require this.</title><rect x='20' y='26' width='150' height='60' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='95' y='48' font-size='7.3' fill='var(--primary)' text-anchor='middle' font-weight='700'>Key Vault</text><text x='95' y='62' font-size='6.2' fill='var(--primary)' text-anchor='middle'>customer-controlled</text><text x='95' y='74' font-size='6.2' fill='var(--primary)' text-anchor='middle'>key</text><line x1='172' y1='56' x2='204' y2='56' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 52 L209 56 L202 60' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='26' width='150' height='60' rx='6' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.8'/><text x='285' y='48' font-size='7.3' fill='var(--blue)' text-anchor='middle' font-weight='700'>TDE</text><text x='285' y='62' font-size='6.2' fill='var(--blue)' text-anchor='middle'>(vs. Microsoft-</text><text x='285' y='74' font-size='6.2' fill='var(--blue)' text-anchor='middle'>managed default key)</text><text x='16' y='114' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Customer controls key rotation/revocation directly \u2014 some compliance rules require</text><text x='16' y='126' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>this.</text></svg>"},
    { "id": "p2-22-5", "core": "core1", "domain": "p2", "objective": "2.2", "term": "Always Encrypted with secure enclaves", "definition": "An enhancement to Always Encrypted that allows certain operations, like pattern matching, to be performed on encrypted data inside a secure hardware enclave without ever decrypting it outside that protected boundary.", "scenario": "run a pattern-matching search against an encrypted column without the data ever being decrypted outside a protected hardware boundary", "distractors": ["Standard Always Encrypted", "TDE", "Dynamic Data Masking"], "tip": "Allows LIMITED OPERATIONS on data that stays encrypted OUTSIDE a hardware enclave — standard Always Encrypted alone is far more restrictive about what you can even query against encrypted columns." , "diagram": "<svg viewBox='0 0 380 159' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-22-5'><title id='dt-p2-22-5'>Limited operations run on decrypted data only inside a protected hardware boundary.</title><rect x='20' y='20' width='340' height='92' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='34' font-size='6.8' fill='var(--muted)' text-anchor='middle' font-weight='700'>DB engine</text><rect x='110' y='44' width='160' height='56' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='190' y='64' font-size='7.3' fill='var(--primary)' text-anchor='middle' font-weight='700'>Secure enclave</text><text x='190' y='78' font-size='6' fill='var(--primary)' text-anchor='middle'>pattern-match ops run here</text><text x='16' y='137' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Limited operations run on decrypted data only inside a protected hardware</text><text x='16' y='149' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>boundary.</text></svg>"},
    { "id": "p2-22-6", "core": "core1", "domain": "p2", "objective": "2.2", "term": "Azure Key Vault integration", "definition": "Centralizing encryption keys, certificates, and secrets used by Azure SQL (such as TDE keys or Always Encrypted column keys) in Azure Key Vault for unified management and access control.", "scenario": "manage encryption keys used across several Azure SQL databases from one centralized, access-controlled location instead of scattered per-database configuration", "distractors": ["TDE with BYOK (specific use)", "TLS enforcement", "Dynamic Data Masking"], "tip": "The GENERAL CENTRALIZED KEY MANAGEMENT service — BYOK for TDE is one SPECIFIC use case of this broader Key Vault integration, not the whole story." , "diagram": "<svg viewBox='0 0 380 186' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-22-6'><title id='dt-p2-22-6'>A single hardened secret store backs multiple database security features at once.</title><circle cx='190' cy='55' r='34' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='190' y='51' font-size='6.8' fill='var(--primary)' text-anchor='middle' font-weight='700'>Key</text><text x='190' y='62' font-size='6.8' fill='var(--primary)' text-anchor='middle' font-weight='700'>Vault</text><line x1='190' y1='89' x2='60' y2='118' stroke='var(--border)' stroke-width='1.3'/><rect x='8' y='118' width='104' height='30' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='60' y='137' font-size='6' fill='var(--text)' text-anchor='middle' font-weight='700'>TDE keys</text><line x1='190' y1='89' x2='190' y2='118' stroke='var(--border)' stroke-width='1.3'/><rect x='138' y='118' width='104' height='30' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='137' font-size='6' fill='var(--text)' text-anchor='middle' font-weight='700'>Always Encrypted</text><line x1='190' y1='89' x2='320' y2='118' stroke='var(--border)' stroke-width='1.3'/><rect x='268' y='118' width='104' height='30' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='320' y='137' font-size='6' fill='var(--text)' text-anchor='middle' font-weight='700'>Connection secrets</text><text x='16' y='163' font-size='8.5' fill='var(--muted)' text-anchor='start'>A single hardened secret store backs multiple database security features at</text><text x='16' y='175' font-size='8.5' fill='var(--muted)' text-anchor='start'>once.</text></svg>"},
    { "id": "p2-22-7", "core": "core1", "domain": "p2", "objective": "2.2", "term": "Cell-level (object-level) encryption", "definition": "Encrypting individual columns inside the database with T-SQL (ENCRYPTBYKEY and DECRYPTBYKEY) using symmetric keys protected by a certificate or password, where the database engine holds the keys and can decrypt for authorized users.", "scenario": "encrypt a single column inside the database with T-SQL where the server can decrypt it for authorized users", "distractors": ["Always Encrypted", "Transparent data encryption", "TLS enforcement"], "tip": "The SERVER holds the keys here — in Always Encrypted the client driver does, so the server never sees plaintext.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-22-7'><title id='dt-p2-22-7'>Cell-level encryption uses server-side keys; Always Encrypted keeps the keys with the client.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Who holds the keys</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Cell-level encryption</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>T-SQL ENCRYPTBYKEY</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Server holds the keys</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Admins may decrypt</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Always Encrypted</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Client driver encrypts</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Server never sees plaintext</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Protects from DBAs</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Cell-level encryption uses server-side keys; Always Encrypted keeps the</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>keys with the client.</text></svg>" },
    { "id": "p2-22-8", "core": "core1", "domain": "p2", "objective": "2.2", "term": "Deterministic encryption", "definition": "Always Encrypted can use deterministic encryption, where the same plaintext always yields the same ciphertext so equality lookups, joins, and grouping work, or randomized encryption, which is stronger but cannot be searched.", "scenario": "choose an Always Encrypted type for a column that must still support equality lookups such as WHERE SSN = @ssn", "distractors": ["Randomized encryption", "Transparent data encryption", "Dynamic data masking"], "tip": "Same plaintext gives the same ciphertext, so equality works — randomized is stronger but unsearchable.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-22-8'><title id='dt-p2-22-8'>Deterministic encryption allows equality searches; randomized encryption is stronger but cannot be searched.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Always Encrypted types</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Deterministic</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Same input, same output</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Equality, join, group by</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Patterns may leak</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Randomized</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Different output each time</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>No equality lookups</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Strongest protection</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Deterministic encryption allows equality searches; randomized encryption</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>is stronger but cannot be searched.</text></svg>" },
    { "id": "p2-23-4", "core": "core1", "domain": "p2", "objective": "2.3", "term": "Microsoft Defender for SQL", "definition": "A service providing advanced threat protection for Azure SQL, detecting anomalous activities like potential SQL injection attempts or unusual access patterns.", "scenario": "get automated alerts about a potential SQL injection attempt detected against a production database", "distractors": ["SQL Audit", "Vulnerability assessment", "Dynamic Data Masking"], "tip": "Detects ANOMALOUS/MALICIOUS ACTIVITY in real time — SQL Audit instead just LOGS activity for later review, without actively analyzing it for threat patterns." , "diagram": "<svg viewBox='0 0 380 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-23-4'><title id='dt-p2-23-4'>One umbrella capability covering both vulnerability scanning and live threat alerts.</title><rect x='120' y='18' width='140' height='38' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190' y='41' font-size='6.8' fill='var(--primary)' text-anchor='middle' font-weight='700'>Defender for SQL</text><line x1='140' y1='58' x2='140' y2='70' stroke='var(--muted)' stroke-width='1.5'/><path d='M136 68 L140 75 L144 68' fill='none' stroke='var(--muted)' stroke-width='1.5'/><line x1='240' y1='58' x2='240' y2='70' stroke='var(--muted)' stroke-width='1.5'/><path d='M236 68 L240 75 L244 68' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='60' y='78' width='140' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='130' y='99' font-size='6' fill='var(--text)' text-anchor='middle' font-weight='700'>Vulnerability assess.</text><rect x='220' y='78' width='140' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='290' y='99' font-size='6' fill='var(--text)' text-anchor='middle' font-weight='700'>Threat detection</text><text x='16' y='127' font-size='8.5' fill='var(--muted)' text-anchor='start'>One umbrella capability covering both vulnerability scanning and live threat</text><text x='16' y='139' font-size='8.5' fill='var(--muted)' text-anchor='start'>alerts.</text></svg>"},
    { "id": "p2-23-5", "core": "core1", "domain": "p2", "objective": "2.3", "term": "Vulnerability assessment", "definition": "A scanning service that checks a database's configuration against security best practices, flagging issues like excessive permissions or missing encryption.", "scenario": "get a scored report identifying specific security misconfigurations in a database, such as overly broad permissions granted to a role", "distractors": ["Defender for SQL (threat detection)", "SQL Audit", "Data classification"], "tip": "Scans CONFIGURATION against BEST PRACTICES proactively — Defender for SQL instead detects ACTIVE THREATS in real time, a different (though complementary) security function." , "diagram": "<svg viewBox='0 0 380 188' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-23-5'><title id='dt-p2-23-5'>A recurring scan compares configuration against a baseline and tracks what still needs fixing.</title><rect x='16' y='14' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='25' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Scan runs</text><text x='190.0' y='38' font-size='7.5' fill='var(--muted)' text-anchor='middle'>against a security best-practice baseline</text><line x1='190.0' y1='46' x2='190.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 50 L190.0 57 L194.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='348' height='32' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='69' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Findings surfaced</text><text x='190.0' y='82' font-size='7.5' fill='var(--text)' text-anchor='middle'>ranked by risk</text><line x1='190.0' y1='90' x2='190.0' y2='96' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 94 L190.0 101 L194.0 94' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='102' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='113' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Remediate or accept</text><text x='190.0' y='126' font-size='7.5' fill='var(--muted)' text-anchor='middle'>track decision per finding</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A recurring scan compares configuration against a baseline and tracks what</text><text x='16' y='178' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>still needs fixing.</text></svg>"},
    { "id": "p2-23-6", "core": "core1", "domain": "p2", "objective": "2.3", "term": "Data classification and labeling", "definition": "Tagging columns with sensitivity labels, such as 'Confidential' or 'PII', to track where sensitive data lives and support compliance reporting.", "scenario": "identify and label every column across a database containing personally identifiable information, for a compliance audit", "distractors": ["Dynamic Data Masking", "Row-level security", "Vulnerability assessment"], "tip": "IDENTIFIES and TAGS where sensitive data LIVES — Dynamic Data Masking instead ACTS on already-identified sensitive columns by obscuring their values in results." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-23-6'><title id='dt-p2-23-6'>Columns are tagged by sensitivity so exposure of the most sensitive data is easy to track and audit.</title><rect x='16.0' y='36' width='84.5' height='48' rx='5' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.5'/><text x='58.25' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Public</text><rect x='110.5' y='36' width='84.5' height='48' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='152.75' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>General</text><rect x='205.0' y='36' width='84.5' height='48' rx='5' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='247.25' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Confidential</text><rect x='299.5' y='36' width='84.5' height='48' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='341.75' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Highly confid.</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Columns are tagged by sensitivity so exposure of the most sensitive data is easy to</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>track and audit.</text></svg>"},
    { "id": "p2-23-7", "core": "core1", "domain": "p2", "objective": "2.3", "term": "Ledger tables", "definition": "Ledger makes data tamper-evident: updatable ledger tables keep a history table and hash-chained blocks, append-only tables forbid updates and deletes, and digests stored outside the database let you verify that nothing was altered.", "scenario": "prove to auditors that financial records have not been altered, even by a privileged administrator", "distractors": ["Dynamic data masking", "Row-level security", "Transparent data encryption"], "tip": "Tamper EVIDENCE through hash-chained blocks and external digests — encryption and masking cannot prove data is unchanged.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-23-7'><title id='dt-p2-23-7'>Ledger chains transaction blocks with hashes and external digests so tampering can be detected.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>How ledger works</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Transactions</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>recorded in blocks</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Hash chain</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>each block links the last</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Digest</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>stored outside the database</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Ledger chains transaction blocks with hashes and external digests so</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>tampering can be detected.</text></svg>" },
    { "id": "p2-23-8", "core": "core1", "domain": "p2", "objective": "2.3", "term": "Change tracking", "definition": "A lightweight feature that records which rows changed (their primary key and a version number) so applications can synchronize incrementally; it does not store the old or new values.", "scenario": "let a mobile app sync only the rows that changed since its last sync, without storing history", "distractors": ["Change data capture", "Temporal tables", "SQL Audit"], "tip": "It only says WHICH rows changed — change data capture records what they changed from and to.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-23-8'><title id='dt-p2-23-8'>Change tracking flags changed rows for sync; it does not keep their values.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Tracking changes</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Change tracking</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Row key plus version</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Which rows changed</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>No old or new values</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Change data capture</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Reads the transaction log</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Before and after values</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Retention and cleanup job</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Change tracking flags changed rows for sync; it does not keep their</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>values.</text></svg>" },
    { "id": "p2-23-9", "core": "core1", "domain": "p2", "objective": "2.3", "term": "Change data capture (CDC)", "definition": "Reads the transaction log asynchronously and writes the before and after values of inserts, updates, and deletes into change tables, for ETL or history; it has a retention and cleanup job and in Azure SQL Database needs a service objective of S3 or higher or a vCore tier.", "scenario": "feed a data warehouse with the full history of row changes, including old and new values, without altering the application", "distractors": ["Change tracking", "Temporal tables", "A database audit"], "tip": "CDC captures old and new VALUES from the log — change tracking only flags that a row changed.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-23-9'><title id='dt-p2-23-9'>CDC reads the log and stores before and after values of every change in change tables.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Change data capture</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Transaction log</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>inserts, updates, deletes</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Capture job</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>reads the log</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Change tables</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>before and after values</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>CDC reads the log and stores before and after values of every change in</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>change tables.</text></svg>" },
    { "id": "p2-23-10", "core": "core1", "domain": "p2", "objective": "2.3", "term": "Audit destinations and scope", "definition": "Azure SQL auditing writes events to Azure Storage, Log Analytics, or Event Hubs and can be set on the server (covering all databases) or on a single database; SQL Server uses a server audit with server and database audit specifications.", "scenario": "send database audit events to Log Analytics so they can be queried alongside other logs", "distractors": ["Query Store", "An Extended Events ring buffer", "A metrics-only diagnostic setting"], "tip": "Choose the DESTINATION (Storage, Log Analytics, Event Hubs) and the scope (server or database) of the audit.", "diagram": "<svg viewBox='0 0 380 158' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-23-10'><title id='dt-p2-23-10'>Auditing can be scoped to a server or database and written to Storage, Log Analytics, or Event Hubs.</title><rect x='115' y='14' width='150' height='34' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.3'/><text x='190' y='27.86' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>SQL auditing</text><text x='190' y='39.26' font-size='6.4' fill='var(--muted)' text-anchor='middle'>server or database scope</text><line x1='190' y1='48' x2='70' y2='69.5' stroke='var(--border)' stroke-width='1.2'/><rect x='16' y='70' width='108' height='40' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='70' y='86.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Storage account</text><text x='70' y='97.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>blob files</text><line x1='190' y1='48' x2='190' y2='69.5' stroke='var(--border)' stroke-width='1.2'/><rect x='136' y='70' width='108' height='40' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='86.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Log Analytics</text><text x='190' y='97.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>query with Kusto</text><line x1='190' y1='48' x2='310' y2='69.5' stroke='var(--border)' stroke-width='1.2'/><rect x='256' y='70' width='108' height='40' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='310' y='86.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Event Hubs</text><text x='310' y='97.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>stream to a SIEM</text><text x='16' y='134' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Auditing can be scoped to a server or database and written to Storage,</text><text x='16' y='146' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Log Analytics, or Event Hubs.</text></svg>" },
    { "id": "p2-24-1", "core": "core1", "domain": "p2", "objective": "2.4", "term": "Server-level firewall rule", "definition": "An IP address rule stored in the master database and applied to every database on the logical server, managed in the portal or with sp_set_firewall_rule; a client outside the rules receives error 40615.", "scenario": "allow an office's public IP range to reach all databases on a logical server", "distractors": ["A database-level firewall rule", "A private endpoint", "A service endpoint"], "tip": "It covers ALL databases on the server — a database-level rule covers one and travels with the database.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-24-1'><title id='dt-p2-24-1'>A server-level firewall rule allows an IP range to reach every database on the logical server.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Server-level rule</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Client IP</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>checked at the gateway</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Server rules</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>stored in master</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Allowed or 40615</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>applies to every database</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A server-level firewall rule allows an IP range to reach every database</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>on the logical server.</text></svg>" },
    { "id": "p2-24-2", "core": "core1", "domain": "p2", "objective": "2.4", "term": "Database-level firewall rule", "definition": "An IP rule stored in a user database (sp_set_database_firewall_rule) that applies only to that database and moves with it during a restore or geo-replication, useful for portable, contained access.", "scenario": "allow one application's IP to reach a single database and have the rule follow the database to a geo-replica", "distractors": ["A server-level firewall rule", "A network security group", "A private endpoint"], "tip": "Scoped to ONE database and portable — server rules cover everything on the server.", "diagram": "<svg viewBox='0 0 380 153' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-24-2'><title id='dt-p2-24-2'>A database-level rule is stored in one database and travels with it.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Firewall rule scope</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Server-level rule</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Stored in master</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>All databases</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Portal, PowerShell, T-SQL</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Database-level rule</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Stored in the database</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>That database only</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Moves with replicas and restores</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A database-level rule is stored in one database and travels with it.</text></svg>" },
    { "id": "p2-24-3", "core": "core1", "domain": "p2", "objective": "2.4", "term": "Allow Azure services and resources setting", "definition": "A setting that creates a 0.0.0.0 rule so any Azure resource, from any subscription, can attempt to connect to the server; authentication still applies, but it is much broader than it sounds.", "scenario": "explain why enabling \"Allow Azure services and resources to access this server\" also lets other tenants' Azure resources reach the server", "distractors": ["A private endpoint", "A server-level rule for one office IP", "Transparent data encryption"], "tip": "It means ANY Azure resource in any subscription — restrict with private endpoints or virtual network rules instead.", "diagram": "<svg viewBox='0 0 380 170' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-24-3'><title id='dt-p2-24-3'>Allow Azure services opens the server to every Azure resource, so tighter options are safer.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Allow Azure services</text><rect x='16' y='30' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='43.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Rule created</text><text x='122' y='43.5' font-size='7.3' fill='var(--text)' text-anchor='start'>0.0.0.0 start and end</text><rect x='16' y='54' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='67.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Who can connect</text><text x='122' y='67.5' font-size='7.3' fill='var(--text)' text-anchor='start'>any Azure resource</text><rect x='16' y='78' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='91.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Still required</text><text x='122' y='91.5' font-size='7.3' fill='var(--text)' text-anchor='start'>valid authentication</text><rect x='16' y='102' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='115.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Safer option</text><text x='122' y='115.5' font-size='7.3' fill='var(--text)' text-anchor='start'>private endpoint</text><text x='16' y='146' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Allow Azure services opens the server to every Azure resource, so</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>tighter options are safer.</text></svg>" },
    { "id": "p2-24-4", "core": "core1", "domain": "p2", "objective": "2.4", "term": "Private endpoint (Private Link)", "definition": "A private IP address in your virtual network that maps to the logical server, keeping traffic on the Microsoft backbone and allowing public network access to be disabled; DNS must resolve the server name to that private IP.", "scenario": "make a database reachable only from a virtual network, with public network access turned off", "distractors": ["A service endpoint", "A server-level firewall rule", "Allow Azure services"], "tip": "A private IP for the SERVER inside your VNet — a service endpoint still connects to the public IP.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-24-4'><title id='dt-p2-24-4'>A private endpoint gives the server a private IP so public access can be disabled.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Private endpoint</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Virtual network</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>private IP assigned</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Private Link</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>maps to the server</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Public access off</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>DNS points to private IP</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A private endpoint gives the server a private IP so public access can be</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>disabled.</text></svg>" },
    { "id": "p2-24-5", "core": "core1", "domain": "p2", "objective": "2.4", "term": "Virtual network service endpoint", "definition": "A service endpoint extends a subnet's identity to the SQL service over the Azure backbone so a virtual network rule can allow that subnet, while the server still keeps its public endpoint.", "scenario": "allow only a specific subnet to reach the database through a virtual network rule while the server keeps its public IP", "distractors": ["A private endpoint", "A database-level firewall rule", "Allow Azure services"], "tip": "A subnet allow-list over the PUBLIC endpoint — a private endpoint gives the server a private IP instead.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-24-5'><title id='dt-p2-24-5'>Service endpoints allow a subnet over the public endpoint; private endpoints give a private IP.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Service vs private endpoint</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Service endpoint</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>VNet rule allows a subnet</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Server keeps its public IP</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>No extra IP address</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Private endpoint</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Private IP in your VNet</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Public access can be off</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Needs private DNS</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Service endpoints allow a subnet over the public endpoint; private</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>endpoints give a private IP.</text></svg>" },
    { "id": "p2-24-6", "core": "core1", "domain": "p2", "objective": "2.4", "term": "Proxy connection policy", "definition": "With Redirect, clients connect straight to the node hosting the database after the gateway handshake (ports 11000 to 11999 must be open), while Proxy sends every packet through the gateway on port 1433; Default uses Redirect from inside Azure and Proxy from outside.", "scenario": "choose the policy that works for clients behind a firewall that only allows outbound port 1433", "distractors": ["Redirect connection policy", "Private endpoint", "Service endpoint"], "tip": "Proxy keeps everything on port 1433 through the gateway — Redirect is faster but needs 11000 to 11999 open.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p2-24-6'><title id='dt-p2-24-6'>Proxy routes through the gateway on 1433; Redirect connects directly but needs extra ports open.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Connection policy</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Proxy</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>All traffic via the gateway</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Only port 1433 needed</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Higher latency</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Redirect</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Direct to the database node</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Ports 11000 to 11999 too</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Lower latency</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Proxy routes through the gateway on 1433; Redirect connects directly but</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>needs extra ports open.</text></svg>" },
    { "id": "p3-31-4", "core": "core1", "domain": "p3", "objective": "3.1", "term": "Query Performance Insight", "definition": "A visual dashboard for Azure SQL Database that surfaces top resource-consuming queries over a selected time range, without needing to write custom DMV or Query Store queries.", "scenario": "quickly identify the top five most resource-intensive queries against a database over the past week, without writing a custom query", "distractors": ["Query Store (raw data)", "Extended Events", "Diagnostic settings"], "tip": "A READY-MADE VISUAL DASHBOARD on top of Query Store's underlying data — saves writing custom queries against Query Store's raw tables for this very common need." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-31-4'><title id='dt-p3-31-4'>Ranks queries by resource consumption, pointing straight at the biggest tuning opportunities.</title><rect x='16.0' y='30' width='116.0' height='64' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='74.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Query A</text><text x='74.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>42% of DTU</text><rect x='142.0' y='30' width='116.0' height='64' rx='5' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='200.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Query B</text><text x='200.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>21% of DTU</text><rect x='268.0' y='30' width='116.0' height='64' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='326.0' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Query C</text><text x='326.0' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>9% of DTU</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Ranks queries by resource consumption, pointing straight at the biggest tuning</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>opportunities.</text></svg>"},
    { "id": "p3-31-5", "core": "core1", "domain": "p3", "objective": "3.1", "term": "Diagnostic settings", "definition": "Configuration that routes Azure SQL resource logs and metrics to a destination such as Log Analytics, Storage, or Event Hubs for long-term retention or further analysis.", "scenario": "retain a database's diagnostic logs for a full year for compliance purposes, beyond Azure's default short-term retention", "distractors": ["Query Performance Insight", "Metric alerts", "Extended Events"], "tip": "ROUTES logs/metrics to a chosen LONG-TERM DESTINATION — without configuring this, Azure's default log retention windows are typically far short of a year." , "diagram": "<svg viewBox='0 0 380 168' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-31-5'><title id='dt-p3-31-5'>Routes metrics/logs to a chosen destination automatically once configured.</title><rect x='16' y='14' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='25' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Enable diagnostic setting</text><text x='190.0' y='38' font-size='7.5' fill='var(--muted)' text-anchor='middle'>per database or server</text><line x1='190.0' y1='46' x2='190.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 50 L190.0 57 L194.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='69' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Choose destination</text><text x='190.0' y='82' font-size='7.5' fill='var(--muted)' text-anchor='middle'>Log Analytics, storage, or Event Hub</text><line x1='190.0' y1='90' x2='190.0' y2='96' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 94 L190.0 101 L194.0 94' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='102' width='348' height='32' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='113' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Data flows continuously</text><text x='190.0' y='126' font-size='7.5' fill='var(--text)' text-anchor='middle'>no manual export needed</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Routes metrics/logs to a chosen destination automatically once configured.</text></svg>"},
    { "id": "p3-31-6", "core": "core1", "domain": "p3", "objective": "3.1", "term": "Metric alerts", "definition": "Rules that notify administrators when a specific database metric, such as DTU percentage or storage usage, crosses a defined threshold.", "scenario": "get notified automatically the moment a database's DTU consumption sustains above 90% for several minutes", "distractors": ["Query Performance Insight", "Diagnostic settings", "Extended Events"], "tip": "Triggers a NOTIFICATION on a THRESHOLD crossing — diagnostic settings instead just ROUTE the raw data somewhere; alerts are the layer that actively watches and reacts to it." , "diagram": "<svg viewBox='0 0 380 188' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-31-6'><title id='dt-p3-31-6'>Turns a monitored metric crossing a defined threshold into an automatic notification or action.</title><rect x='16' y='14' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='25' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Threshold defined</text><text x='190.0' y='38' font-size='7.5' fill='var(--muted)' text-anchor='middle'>e.g. DTU &gt; 90% for 5 min</text><line x1='190.0' y1='46' x2='190.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 50 L190.0 57 L194.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='69' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Metric crosses threshold</text><text x='190.0' y='82' font-size='7.5' fill='var(--muted)' text-anchor='middle'>condition is met</text><line x1='190.0' y1='90' x2='190.0' y2='96' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 94 L190.0 101 L194.0 94' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='102' width='348' height='32' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='113' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Action group notified</text><text x='190.0' y='126' font-size='7.5' fill='var(--text)' text-anchor='middle'>email, SMS, webhook, or runbook</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Turns a monitored metric crossing a defined threshold into an automatic</text><text x='16' y='178' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>notification or action.</text></svg>"},
    { "id": "p3-31-7", "core": "core1", "domain": "p3", "objective": "3.1", "term": "Operational performance baseline", "definition": "A record of normal CPU, I/O, memory, wait, and query metrics captured over representative periods, including peaks, used as the reference for judging whether current behavior is abnormal and for capacity planning.", "scenario": "decide whether today's 70% CPU is a problem by comparing it with what is normal for this database at this time of the week", "distractors": ["A single snapshot taken today", "The default alert threshold", "A forced query plan"], "tip": "Without a BASELINE you cannot tell normal from abnormal — capture it before problems start.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-31-7'><title id='dt-p3-31-7'>A baseline records what normal looks like so abnormal behavior and growth are easy to see.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Building a baseline</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Collect</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>CPU, IO, waits, queries</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Cover peaks</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>weekdays, month end</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Compare</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>today versus normal</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A baseline records what normal looks like so abnormal behavior and</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>growth are easy to see.</text></svg>" },
    { "id": "p3-31-8", "core": "core1", "domain": "p3", "objective": "3.1", "term": "Azure Monitor platform metrics", "definition": "Built-in numeric metrics such as CPU percentage, DTU or data IO percentage, storage used, and deadlocks, collected automatically and chartable or alertable with no configuration inside the database.", "scenario": "chart CPU percentage and set an alert on it without running any T-SQL", "distractors": ["Query Store", "Extended Events", "sys.dm_exec_requests"], "tip": "Automatic outside-in numbers — Query Store and DMVs explain WHAT inside the database used the resources.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-31-8'><title id='dt-p3-31-8'>Platform metrics come from Azure Monitor automatically; DMVs and Query Store show what inside the database caused them.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Where the numbers come from</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Platform metrics</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>CPU, DTU, storage percent</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>No setup needed</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Chart and alert</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Inside the database</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>DMVs and Query Store</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Shows which query</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Needs T-SQL</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Platform metrics come from Azure Monitor automatically; DMVs and Query</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Store show what inside the database caused them.</text></svg>" },
    { "id": "p3-31-9", "core": "core1", "domain": "p3", "objective": "3.1", "term": "Database watcher", "definition": "A managed monitoring solution that collects detailed workload data from DMVs for Azure SQL Database, Managed Instance, and elastic pools into a central data store with ready-made dashboards, without agents or custom collection scripts.", "scenario": "monitor a large fleet of Azure SQL databases in one set of dashboards without deploying agents", "distractors": ["Query Performance Insight", "SQL Server Profiler", "Intelligent Insights"], "tip": "Fleet-wide DMV collection into a central store with dashboards — Query Performance Insight looks at one database.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-31-9'><title id='dt-p3-31-9'>Database watcher collects DMV data from many Azure SQL resources into central dashboards without agents.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Database watcher</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Watcher</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>collects DMV data</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Data store</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>Data Explorer or Fabric</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Dashboards</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>fleet and single database</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Database watcher collects DMV data from many Azure SQL resources into</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>central dashboards without agents.</text></svg>" },
    { "id": "p3-31-10", "core": "core1", "domain": "p3", "objective": "3.1", "term": "Intelligent Insights", "definition": "Built-in intelligence that detects disruptive events in Azure SQL Database, such as reaching resource limits, locking, and plan regressions, and writes a diagnostics log with root-cause analysis once the SQLInsights log is enabled.", "scenario": "get automatic root-cause analysis of a performance degradation without digging through DMVs by hand", "distractors": ["Automatic tuning", "Query Store forced plans", "A metric alert"], "tip": "It EXPLAINS a degradation (root cause) — automatic tuning is the feature that FIXES some of them.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-31-10'><title id='dt-p3-31-10'>Intelligent Insights detects performance events and writes a root-cause diagnostics log.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Intelligent Insights</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Detect</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>a disruptive event</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Analyze</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>root cause</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Diagnostics log</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>SQLInsights output</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Intelligent Insights detects performance events and writes a root-cause</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>diagnostics log.</text></svg>" },
    { "id": "p3-32-4", "core": "core1", "domain": "p3", "objective": "3.2", "term": "sys.dm_exec_requests", "definition": "A dynamic management view showing all currently executing requests on a SQL instance, including their status, wait type, and resource consumption in real time.", "scenario": "see every query currently executing against a database right now, along with what each one is waiting on", "distractors": ["Query Store (historical)", "Wait statistics (aggregate)", "Resource utilization metrics"], "tip": "Shows CURRENTLY EXECUTING requests LIVE — Query Store instead shows HISTORICAL execution data over time, a different (complementary) temporal scope." , "diagram": "<svg viewBox='0 0 380 122' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-32-4'><title id='dt-p3-32-4'>Every currently-executing request, live \u2014 the go-to first stop when something feels slow right now.</title><rect x='20' y='18' width='340' height='90' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='32' font-size='6.6' fill='var(--text)' text-anchor='middle' font-weight='700'>sys.dm_exec_requests (live snapshot)</text><text x='55' y='48' font-size='5.8' fill='var(--muted)' text-anchor='start' font-weight='700'>session_id</text><text x='135' y='48' font-size='5.8' fill='var(--muted)' text-anchor='start' font-weight='700'>status</text><text x='215' y='48' font-size='5.8' fill='var(--muted)' text-anchor='start' font-weight='700'>wait_type</text><text x='295' y='48' font-size='5.8' fill='var(--muted)' text-anchor='start' font-weight='700'>command</text><text x='55' y='64' font-size='5.8' fill='var(--text)' text-anchor='start'>62</text><text x='135' y='64' font-size='5.8' fill='var(--text)' text-anchor='start'>running</text><text x='215' y='64' font-size='5.8' fill='var(--text)' text-anchor='start'>PAGEIOLATCH_SH</text><text x='295' y='64' font-size='5.8' fill='var(--text)' text-anchor='start'>SELECT</text><text x='55' y='82' font-size='5.8' fill='var(--text)' text-anchor='start'>71</text><text x='135' y='82' font-size='5.8' fill='var(--text)' text-anchor='start'>suspended</text><text x='215' y='82' font-size='5.8' fill='var(--text)' text-anchor='start'>LCK_M_X</text><text x='295' y='82' font-size='5.8' fill='var(--text)' text-anchor='start'>UPDATE</text><text x='16' y='100' font-size='8.5' fill='var(--muted)' text-anchor='start'>Every currently-executing request, live \u2014 the go-to first stop when something</text><text x='16' y='112' font-size='8.5' fill='var(--muted)' text-anchor='start'>feels slow right now.</text></svg>"},
    { "id": "p3-32-5", "core": "core1", "domain": "p3", "objective": "3.2", "term": "Blocking chain analysis", "definition": "Identifying which session is holding a lock that other sessions are waiting on, tracing back through a chain of blocked sessions to find the root blocking query.", "scenario": "trace a chain of five blocked queries back to the one original session actually holding the lock everyone else is waiting on", "distractors": ["DMVs (general)", "Wait statistics", "Resource utilization metrics"], "tip": "Traces a CHAIN back to the ROOT BLOCKER — a specific, structured application of DMV data for exactly this common 'why is everything stuck waiting' scenario." , "diagram": "<svg viewBox='0 0 410 130' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-32-5'><title id='dt-p3-32-5'>Each blocked session is itself blocking the next \u2014 find the head-blocker (A) to fix the chain.</title><rect x='15' y='30' width='110' height='50' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.6'/><text x='70' y='50' font-size='6.4' fill='var(--red)' text-anchor='middle' font-weight='700'>Session A</text><text x='70' y='62' font-size='6' fill='var(--red)' text-anchor='middle'>(holds lock)</text><line x1='131' y1='55' x2='138' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M136 51 L143 55 L136 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='150' y='30' width='110' height='50' rx='6' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.6'/><text x='205' y='50' font-size='6.4' fill='var(--amber)' text-anchor='middle' font-weight='700'>Session B</text><text x='205' y='62' font-size='6' fill='var(--amber)' text-anchor='middle'>(blocked by A)</text><line x1='266' y1='55' x2='273' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M271 51 L278 55 L271 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='285' y='30' width='110' height='50' rx='6' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.6'/><text x='340' y='50' font-size='6.4' fill='var(--blue)' text-anchor='middle' font-weight='700'>Session C</text><text x='340' y='62' font-size='6' fill='var(--blue)' text-anchor='middle'>(blocked by B)</text><text x='16' y='108' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Each blocked session is itself blocking the next \u2014 find the head-blocker (A) to fix</text><text x='16' y='120' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>the chain.</text></svg>"},
    { "id": "p3-32-6", "core": "core1", "domain": "p3", "objective": "3.2", "term": "tempdb contention", "definition": "Performance problems caused by heavy concurrent use of tempdb, such as for large sorts, temp tables, or row versioning, often diagnosed through specific tempdb-related wait types.", "scenario": "diagnose why an unrelated-looking set of queries are all slowing down at the same time, traced back to heavy shared tempdb usage", "distractors": ["General wait statistics", "Resource utilization metrics", "Blocking chain"], "tip": "A SPECIFIC, SHARED RESOURCE bottleneck (tempdb) that can slow down seemingly UNRELATED queries — worth recognizing as its own diagnostic category with dedicated wait types." , "diagram": "<svg viewBox='0 0 380 163' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-32-6'><title id='dt-p3-32-6'>Many sessions competing for shared tempdb pages/allocation is a common hidden bottleneck.</title><rect x='30' y='18' width='60' height='26' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='60' y='35' font-size='6' fill='var(--text)' text-anchor='middle'>Session</text><line x1='60' y1='44' x2='190' y2='76' stroke='var(--amber)' stroke-width='1.3'/><rect x='120' y='18' width='60' height='26' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='150' y='35' font-size='6' fill='var(--text)' text-anchor='middle'>Session</text><line x1='150' y1='44' x2='190' y2='76' stroke='var(--amber)' stroke-width='1.3'/><rect x='210' y='18' width='60' height='26' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='240' y='35' font-size='6' fill='var(--text)' text-anchor='middle'>Session</text><line x1='240' y1='44' x2='190' y2='76' stroke='var(--amber)' stroke-width='1.3'/><rect x='300' y='18' width='60' height='26' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='330' y='35' font-size='6' fill='var(--text)' text-anchor='middle'>Session</text><line x1='330' y1='44' x2='190' y2='76' stroke='var(--amber)' stroke-width='1.3'/><rect x='140' y='78' width='100' height='34' rx='6' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.8'/><text x='190' y='99' font-size='7.3' fill='var(--amber)' text-anchor='middle' font-weight='700'>tempdb</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Many sessions competing for shared tempdb pages/allocation is a common hidden</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>bottleneck.</text></svg>"},
    { "id": "p3-32-7", "core": "core1", "domain": "p3", "objective": "3.2", "term": "sys.dm_db_resource_stats and sys.resource_stats", "definition": "sys.dm_db_resource_stats, in the user database, reports CPU, data IO, log IO, and memory in 15-second samples for about the last hour, while sys.resource_stats, in master, keeps 5-minute samples for about two weeks.", "scenario": "find where to see resource usage for the last hour at fine detail and for the last two weeks at coarse detail", "distractors": ["sys.dm_exec_sessions and sys.dm_exec_connections", "sys.dm_os_wait_stats", "sys.dm_tran_locks"], "tip": "Two views, two time scales — fine and recent in the database, coarse and longer in master.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-32-7'><title id='dt-p3-32-7'>dm_db_resource_stats gives recent fine detail; sys.resource_stats gives about two weeks at coarser detail.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Resource history</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>sys.dm_db_resource_stats</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>In the user database</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>15-second samples</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>About the last hour</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>sys.resource_stats</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>In master</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>5-minute samples</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>About 14 days</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>dm_db_resource_stats gives recent fine detail; sys.resource_stats gives</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>about two weeks at coarser detail.</text></svg>" },
    { "id": "p3-32-8", "core": "core1", "domain": "p3", "objective": "3.2", "term": "Reading CPU, data IO, and log IO percentages", "definition": "High CPU percent with low data IO suggests compute-bound queries (tune the queries or add compute), high data IO percent suggests scans or missing indexes, and high log IO percent suggests heavy write activity; values sustained near 100% mean a tier limit is being hit.", "scenario": "decide whether to tune queries or scale up when CPU stays near 100% while data IO stays low", "distractors": ["Adding a read replica", "Switching to a smaller tier", "Disabling Query Store"], "tip": "Which percentage is high says WHAT is constrained — look at the queries before simply scaling.", "diagram": "<svg viewBox='0 0 380 178' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-32-8'><title id='dt-p3-32-8'>The metric that is high points to the constrained resource and the likely kind of workload problem.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Reading the percentages</text><rect x='16' y='30' width='121.8' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='76.9' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Metric high</text><rect x='137.8' y='30' width='226.2' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='250.9' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Likely cause</text><rect x='16' y='50' width='121.8' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='76.9' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>CPU %</text><rect x='137.8' y='50' width='226.2' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='250.9' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>compute-heavy queries</text><rect x='16' y='70' width='121.8' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='76.9' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>Data IO %</text><rect x='137.8' y='70' width='226.2' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='250.9' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>scans, missing indexes</text><rect x='16' y='90' width='121.8' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='76.9' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>Log IO %</text><rect x='137.8' y='90' width='226.2' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='250.9' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>heavy write activity</text><rect x='16' y='110' width='121.8' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='76.9' y='123.2' font-size='7' fill='var(--text)' text-anchor='middle'>Workers %</text><rect x='137.8' y='110' width='226.2' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='250.9' y='123.2' font-size='7' fill='var(--text)' text-anchor='middle'>too many concurrent requests</text><text x='16' y='154' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The metric that is high points to the constrained resource and the</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>likely kind of workload problem.</text></svg>" },
    { "id": "p3-32-9", "core": "core1", "domain": "p3", "objective": "3.2", "term": "Row versioning (RCSI) to reduce blocking", "definition": "READ_COMMITTED_SNAPSHOT lets readers use row versions instead of shared locks so readers stop blocking writers; it is on by default in Azure SQL Database and costs version store space in tempdb or the database.", "scenario": "reduce readers blocking writers without rewriting the application", "distractors": ["Raising the isolation level to SERIALIZABLE", "Adding NOLOCK hints everywhere", "Increasing the service tier"], "tip": "Readers use VERSIONS instead of locks — NOLOCK risks dirty reads and does not fix the design.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-32-9'><title id='dt-p3-32-9'>Row versioning removes reader-writer blocking at the cost of version store space.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Read committed behavior</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Without row versioning</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Readers take shared locks</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Writers wait for readers</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>More blocking</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>With RCSI</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Readers use row versions</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Readers do not block writers</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Version store grows</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Row versioning removes reader-writer blocking at the cost of version</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>store space.</text></svg>" },
    { "id": "p3-32-10", "core": "core1", "domain": "p3", "objective": "3.2", "term": "Deadlock (error 1205)", "definition": "Two or more sessions each hold a lock the other needs, so the engine ends one as the victim with error 1205; capture the deadlock graph with the system_health Extended Events session and fix it with a consistent access order, shorter transactions, or better indexes.", "scenario": "diagnose intermittent error 1205 in which the engine chose one transaction as a victim", "distractors": ["Plain blocking", "A lock timeout (error 1222)", "A full transaction log"], "tip": "A CYCLE of waits ends with a victim — plain blocking clears once the head blocker finishes.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p3-32-10'><title id='dt-p3-32-10'>A deadlock is a cycle of lock waits that the engine resolves by killing one session.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Anatomy of a deadlock</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Session A</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>holds lock 1, wants 2</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Session B</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>holds lock 2, wants 1</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Victim killed</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>error 1205</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A deadlock is a cycle of lock waits that the engine resolves by killing</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>one session.</text></svg>" },
    { "id": "p4-41-4", "core": "core1", "domain": "p4", "objective": "4.1", "term": "Columnstore indexes", "definition": "An index storage format optimized for analytical, aggregate-heavy queries over large tables, storing data column-by-column rather than row-by-row for much better compression and scan performance.", "scenario": "dramatically speed up aggregate queries scanning millions of rows in a large analytical fact table", "distractors": ["Clustered/nonclustered indexes (row-based)", "Missing index recommendations", "Filtered indexes"], "tip": "Stores data COLUMN-BY-COLUMN for ANALYTICAL workloads — standard row-based clustered/nonclustered indexes instead suit typical transactional, row-lookup-heavy OLTP queries better." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-41-4'><title id='dt-p4-41-4'>Column-oriented storage compresses and scans large analytical aggregations far faster.</title><rect x='16.0' y='30' width='179.0' height='64' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='105.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Row-store</text><text x='105.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>best for OLTP lookups</text><rect x='205.0' y='30' width='179.0' height='64' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='294.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Columnstore</text><text x='294.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>best for analytical scans</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Column-oriented storage compresses and scans large analytical aggregations far</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>faster.</text></svg>"},
    { "id": "p4-41-5", "core": "core1", "domain": "p4", "objective": "4.1", "term": "Filtered indexes", "definition": "A nonclustered index built on only a subset of a table's rows matching a filter predicate, resulting in a smaller, more efficient index for queries that only ever target that subset.", "scenario": "create a smaller, more efficient index covering only active (non-archived) orders, since 95% of queries only ever touch active orders anyway", "distractors": ["Columnstore index", "Included columns", "Fragmentation"], "tip": "Indexes only a SUBSET of rows matching a FILTER — much smaller and more efficient than indexing the whole table when queries consistently only care about that subset." , "diagram": "<svg viewBox='0 0 380 163' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-41-5'><title id='dt-p4-41-5'>Indexes only a WHERE-filtered subset of rows \u2014 smaller, faster for queries matching that filter.</title><rect x='20' y='18' width='340' height='96' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='32' font-size='6.6' fill='var(--muted)' text-anchor='middle' font-weight='700'>Full table</text><rect x='36' y='42' width='308' height='14' rx='3' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.2'/><text x='190' y='52.5' font-size='5.8' fill='var(--muted)' text-anchor='middle'>excluded from this index</text><rect x='36' y='60' width='308' height='14' rx='3' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='190' y='70.5' font-size='5.8' fill='var(--primary)' text-anchor='middle'>WHERE Status = &#39;Active&#39;</text><rect x='36' y='78' width='308' height='14' rx='3' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.2'/><text x='190' y='88.5' font-size='5.8' fill='var(--muted)' text-anchor='middle'>excluded from this index</text><rect x='36' y='96' width='308' height='14' rx='3' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='190' y='106.5' font-size='5.8' fill='var(--primary)' text-anchor='middle'>WHERE Status = &#39;Active&#39;</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Indexes only a WHERE-filtered subset of rows \u2014 smaller, faster for queries</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>matching that filter.</text></svg>"},
    { "id": "p4-41-6", "core": "core1", "domain": "p4", "objective": "4.1", "term": "Included columns", "definition": "Extra, non-key columns added to a nonclustered index's leaf level, allowing a query to be fully satisfied by the index alone without an extra lookup back to the full table row.", "scenario": "avoid an extra table lookup for a frequently-run query by adding the specific columns it needs directly to an existing index", "distractors": ["Filtered index", "Columnstore index", "Missing index recommendation"], "tip": "Turns a query into a fully COVERING index lookup with NO EXTRA TABLE ACCESS — a targeted tuning technique for a specific frequently-run query's exact column needs." , "diagram": "<svg viewBox='0 0 380 122' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-41-6'><title id='dt-p4-41-6'>Non-key columns stored at the leaf level let a query be answered from the index alone.</title><rect x='20' y='24' width='160' height='60' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='100' y='46' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>Key column(s)</text><text x='100' y='60' font-size='6.2' fill='var(--primary)' text-anchor='middle'>defines index order</text><rect x='200' y='24' width='160' height='60' rx='6' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.6' stroke-dasharray='2 2'/><text x='280' y='46' font-size='6.6' fill='var(--blue)' text-anchor='middle' font-weight='700'>Included columns</text><text x='280' y='60' font-size='6' fill='var(--blue)' text-anchor='middle'>ride along at leaf level</text><text x='280' y='72' font-size='6' fill='var(--blue)' text-anchor='middle'>no lookup needed</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Non-key columns stored at the leaf level let a query be answered from the index</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>alone.</text></svg>"},
    { "id": "p4-41-7", "core": "core1", "domain": "p4", "objective": "4.1", "term": "Unused and duplicate indexes", "definition": "Indexes that are never read (see sys.dm_db_index_usage_stats) or that duplicate another index's keys only add write cost and storage, so review them over a full business cycle before dropping.", "scenario": "find indexes that slow down inserts and updates yet are never used by any query", "distractors": ["Missing index recommendations", "Filtered indexes", "Columnstore indexes"], "tip": "Every index taxes WRITES — check usage across a full cycle (month end!) before dropping one.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-41-7'><title id='dt-p4-41-7'>Unused or duplicate indexes cost write performance and space; confirm over a full cycle, then drop.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Pruning indexes</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Usage stats</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>reads versus writes</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Review a full cycle</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>month end, reports</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Drop safely</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>script it first</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Unused or duplicate indexes cost write performance and space; confirm</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>over a full cycle, then drop.</text></svg>" },
    { "id": "p4-42-4", "core": "core1", "domain": "p4", "objective": "4.2", "term": "Query Store forced plans", "definition": "A feature that pins a specific, known-good execution plan for a query, preventing the optimizer from switching to a worse plan due to parameter sniffing or statistics changes.", "scenario": "lock in a known-good execution plan for a critical query, after the optimizer kept switching to a much worse plan following a statistics update", "distractors": ["Parameter sniffing (the problem)", "Statistics staleness", "Plan cache bloat"], "tip": "PINS a SPECIFIC plan to PREVENT the optimizer from switching — a direct, targeted fix for exactly the kind of plan-regression parameter sniffing can cause." , "diagram": "<svg viewBox='0 0 380 188' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-42-4'><title id='dt-p4-42-4'>Pins a specific, proven-good plan so the optimizer stops flip-flopping between choices.</title><rect x='16' y='14' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='25' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Multiple plans observed</text><text x='190.0' y='38' font-size='7.5' fill='var(--muted)' text-anchor='middle'>performance varies run to run</text><line x1='190.0' y1='46' x2='190.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 50 L190.0 57 L194.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='69' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>DBA forces known-good plan</text><text x='190.0' y='82' font-size='7.5' fill='var(--muted)' text-anchor='middle'>via Query Store</text><line x1='190.0' y1='90' x2='190.0' y2='96' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 94 L190.0 101 L194.0 94' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='102' width='348' height='32' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='113' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Optimizer uses forced plan</text><text x='190.0' y='126' font-size='7.5' fill='var(--text)' text-anchor='middle'>consistent performance going forward</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Pins a specific, proven-good plan so the optimizer stops flip-flopping between</text><text x='16' y='178' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>choices.</text></svg>"},
    { "id": "p4-42-5", "core": "core1", "domain": "p4", "objective": "4.2", "term": "Automatic tuning", "definition": "An Azure SQL feature that can automatically apply and monitor recommendations, such as forcing a better plan or creating a missing index, reverting automatically if the change doesn't actually help.", "scenario": "let Azure SQL automatically apply and monitor a recommended fix for a query regression, reverting on its own if the fix doesn't actually improve things", "distractors": ["Query Store forced plans (manual)", "Missing index recommendations (manual)", "Plan cache bloat"], "tip": "AUTOMATES applying AND MONITORING a fix, with AUTOMATIC ROLLBACK if it doesn't help — the hands-off version of manually forcing a plan or creating a recommended index yourself." , "diagram": "<svg viewBox='0 0 380 194' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-42-5'><title id='dt-p4-42-5'>Azure SQL can detect, test, and apply plan-performance fixes with no DBA action required.</title><rect x='16' y='14' width='348' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='26' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Regression detected</text><text x='190.0' y='39' font-size='7.5' fill='var(--muted)' text-anchor='middle'>a query got slower after a plan change</text><line x1='190.0' y1='48' x2='190.0' y2='54' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 52 L190.0 59 L194.0 52' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='60' width='348' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='72' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Azure tests a better plan</text><text x='190.0' y='85' font-size='7.5' fill='var(--text)' text-anchor='middle'>compares against history automatically</text><line x1='190.0' y1='94' x2='190.0' y2='100' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 98 L190.0 105 L194.0 98' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='106' width='348' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='118' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Applies or reverts</text><text x='190.0' y='131' font-size='7.5' fill='var(--muted)' text-anchor='middle'>reverts on its own if it doesn\u2019t help</text><text x='16' y='172' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Azure SQL can detect, test, and apply plan-performance fixes with no DBA action</text><text x='16' y='184' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>required.</text></svg>"},
    { "id": "p4-42-6", "core": "core1", "domain": "p4", "objective": "4.2", "term": "Plan cache bloat", "definition": "A performance problem where the plan cache fills with many single-use, non-reusable execution plans, often caused by non-parameterized queries, wasting memory that could otherwise cache reusable plans.", "scenario": "diagnose why SQL Server's plan cache is full of thousands of nearly-identical, single-use query plans that are never reused", "distractors": ["Parameter sniffing", "Statistics staleness", "Fragmentation"], "tip": "Caused by NON-PARAMETERIZED queries generating many NEVER-REUSED plans — the opposite failure mode from parameter sniffing, which is about ONE cached plan being reused badly." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-42-6'><title id='dt-p4-42-6'>Non-parameterized ad-hoc queries fill the plan cache with one-off entries that are never reused.</title><rect x='16.0' y='30' width='179.0' height='64' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='105.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Many ad-hoc plans</text><text x='105.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>single-use, clog the cache</text><rect x='205.0' y='30' width='179.0' height='64' rx='5' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.5'/><text x='294.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Parameterized plans</text><text x='294.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>few, reused often</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Non-parameterized ad-hoc queries fill the plan cache with one-off entries that are</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>never reused.</text></svg>"},
    { "id": "p4-42-7", "core": "core1", "domain": "p4", "objective": "4.2", "term": "Key lookup", "definition": "An execution-plan operator that fetches extra columns from the clustered index for each row found through a nonclustered index; many lookups over large row counts suggest adding INCLUDE columns so the index covers the query.", "scenario": "remove the row-by-row fetches of extra columns that follow a nonclustered index seek in an execution plan", "distractors": ["A table scan", "A hash match", "A sort spill"], "tip": "A seek plus a lookup PER ROW — INCLUDE the missing columns to make the index covering.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-42-7'><title id='dt-p4-42-7'>A key lookup fetches missing columns row by row; a covering index with INCLUDE columns removes it.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Key lookup</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Index seek</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>finds matching keys</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Key lookup</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>row-by-row fetch</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Fix</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>INCLUDE the columns</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A key lookup fetches missing columns row by row; a covering index with</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>INCLUDE columns removes it.</text></svg>" },
    { "id": "p4-42-8", "core": "core1", "domain": "p4", "objective": "4.2", "term": "Sargable predicate", "definition": "A predicate the optimizer can answer with an index seek because the column is not wrapped in a function or expression, for example OrderDate >= @start AND OrderDate < @end instead of YEAR(OrderDate) = 2025.", "scenario": "rewrite WHERE YEAR(OrderDate) = 2025 so that an index on OrderDate can be used", "distractors": ["Adding NOLOCK", "Increasing MAXDOP", "Forcing a hash join"], "tip": "Never wrap the COLUMN in a function — compare the bare column with a range.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-42-8'><title id='dt-p4-42-8'>Predicates that leave the column bare can use an index seek; functions on the column force a scan.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Writing seekable filters</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Not sargable</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>WHERE YEAR(OrderDate) = 2025</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Function on the column</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Scans the index</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Sargable</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>WHERE OrderDate &gt;= &#39;2025-01-01&#39;</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>AND OrderDate &lt; &#39;2026-01-01&#39;</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Seeks the index</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Predicates that leave the column bare can use an index seek; functions</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>on the column force a scan.</text></svg>" },
    { "id": "p4-42-9", "core": "core1", "domain": "p4", "objective": "4.2", "term": "Implicit conversion warning", "definition": "When a query compares values of different data types, SQL Server converts one side; converting the column side prevents index seeks and shows as a plan warning, for example an nvarchar parameter compared with a varchar column.", "scenario": "fix a plan warning showing an implicit conversion that turned an index seek into a scan", "distractors": ["A missing index warning", "Parameter sniffing", "A spilled sort"], "tip": "Match the parameter's data type to the COLUMN — converting the column side kills the seek.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-42-9'><title id='dt-p4-42-9'>Mismatched data types force a conversion on the column and can turn a seek into a scan.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Data type mismatch</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Types differ</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>nvarchar parameter</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>varchar column converted</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Index scan plus warning</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Types match</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>varchar parameter</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>No conversion</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Index seek</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Mismatched data types force a conversion on the column and can turn a</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>seek into a scan.</text></svg>" },
    { "id": "p4-43-1", "core": "core1", "domain": "p4", "objective": "4.3", "term": "ALTER INDEX REORGANIZE", "definition": "An online, lightweight defragmentation of an index's leaf pages suited to moderate fragmentation (roughly 5 to 30 percent); it can be stopped and resumed without losing work and does not update statistics.", "scenario": "choose the lighter maintenance operation for an index with about 15% fragmentation on a busy system", "distractors": ["ALTER INDEX REBUILD OFFLINE", "DROP INDEX and CREATE INDEX", "UPDATE STATISTICS WITH FULLSCAN"], "tip": "Moderate fragmentation, lightweight and interruptible — rebuild is for heavy fragmentation.", "diagram": "<svg viewBox='0 0 380 146' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-43-1'><title id='dt-p4-43-1'>REORGANIZE is the light, online option for moderate fragmentation.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Fragmentation guidance</text><rect x='16' y='30' width='156.6' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='94.3' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Fragmentation</text><rect x='172.6' y='30' width='191.4' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='268.3' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Typical action</text><rect x='16' y='50' width='156.6' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='94.3' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>Under about 5%</text><rect x='172.6' y='50' width='191.4' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='268.3' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>leave it alone</text><rect x='16' y='70' width='156.6' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='94.3' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>About 5% to 30%</text><rect x='172.6' y='70' width='191.4' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='268.3' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>REORGANIZE</text><rect x='16' y='90' width='156.6' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='94.3' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>Over about 30%</text><rect x='172.6' y='90' width='191.4' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='268.3' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>REBUILD</text><text x='16' y='134' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>REORGANIZE is the light, online option for moderate fragmentation.</text></svg>" },
    { "id": "p4-43-2", "core": "core1", "domain": "p4", "objective": "4.3", "term": "ALTER INDEX REBUILD", "definition": "Recreates an index to remove heavy fragmentation, refreshes its statistics with a full scan, and can run online or as a resumable operation so it can be paused; it uses more resources than REORGANIZE.", "scenario": "recreate a heavily fragmented index and refresh its statistics, with the option to pause the operation", "distractors": ["ALTER INDEX REORGANIZE", "DBCC CHECKDB", "Clearing the plan cache"], "tip": "REBUILD recreates the index and its statistics — REORGANIZE only shuffles leaf pages.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-43-2'><title id='dt-p4-43-2'>REBUILD recreates the index and its statistics, and can be online or resumable.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>REORGANIZE vs REBUILD</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>REORGANIZE</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Leaf-level defragmentation</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Always online</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Statistics not updated</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>REBUILD</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Recreates the index</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>ONLINE or RESUMABLE option</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Statistics updated (full scan)</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>REBUILD recreates the index and its statistics, and can be online or</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>resumable.</text></svg>" },
    { "id": "p4-43-3", "core": "core1", "domain": "p4", "objective": "4.3", "term": "Scheduled statistics updates (FULLSCAN)", "definition": "Auto-update statistics can lag after very large loads, so a scheduled UPDATE STATISTICS, with FULLSCAN where accuracy matters, keeps cardinality estimates correct and prevents poor plans.", "scenario": "refresh statistics with a full scan after loading millions of rows so the optimizer estimates row counts correctly", "distractors": ["ALTER INDEX REORGANIZE", "DBCC CHECKDB", "Clearing the plan cache"], "tip": "Big loads outrun the auto-update threshold — update manually, and use FULLSCAN for accuracy.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-43-3'><title id='dt-p4-43-3'>After big loads, update statistics (FULLSCAN if needed) so the optimizer sees the real data.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Refreshing statistics</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Large load</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>millions of rows</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Stale statistics</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>wrong row estimates</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>UPDATE STATISTICS</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>FULLSCAN, then retest</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>After big loads, update statistics (FULLSCAN if needed) so the optimizer</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>sees the real data.</text></svg>" },
    { "id": "p4-43-4", "core": "core1", "domain": "p4", "objective": "4.3", "term": "DBCC CHECKDB", "definition": "Checks the physical and logical integrity of a database's pages and structures, scheduled regularly on SQL Server VMs and Managed Instance (often against a restored copy for large databases); REPAIR_ALLOW_DATA_LOSS is a last resort.", "scenario": "verify that a database on a SQL Server VM has no page corruption, on a schedule", "distractors": ["UPDATE STATISTICS", "ALTER INDEX REBUILD", "RESTORE VERIFYONLY"], "tip": "It checks PAGES and structures for corruption — RESTORE VERIFYONLY only confirms a backup file is readable.", "diagram": "<svg viewBox='0 0 380 130' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-43-4'><title id='dt-p4-43-4'>DBCC CHECKDB verifies database integrity and should run on a schedule.</title><rect x='16' y='16' width='348' height='20' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><circle cx='28' cy='26' r='3' fill='var(--red)'/><circle cx='38' cy='26' r='3' fill='var(--amber)'/><circle cx='48' cy='26' r='3' fill='var(--green)'/><text x='190' y='30' font-size='7' fill='var(--muted)' text-anchor='middle'>T-SQL</text><rect x='16' y='36' width='348' height='58' rx='0' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='28' y='54' font-size='8' fill='var(--primary)' text-anchor='start' font-family='monospace' style='white-space:pre'>DBCC CHECKDB (Sales) WITH NO_INFOMSGS;</text><text x='28' y='68' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>Command(s) completed successfully.</text><text x='28' y='82' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>-- repair options are a last resort</text><text x='16' y='118' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>DBCC CHECKDB verifies database integrity and should run on a schedule.</text></svg>" },
    { "id": "p4-43-5", "core": "core1", "domain": "p4", "objective": "4.3", "term": "Database-scoped configuration", "definition": "ALTER DATABASE SCOPED CONFIGURATION sets per-database options such as MAXDOP, LEGACY_CARDINALITY_ESTIMATION, and PARAMETER_SNIFFING, so one database can behave differently without changing the server; it is the main tuning surface in Azure SQL Database.", "scenario": "set MAXDOP to 4 for one database without changing the server or any other database", "distractors": ["sp_configure", "A startup trace flag", "A Resource Governor pool"], "tip": "PER-database — sp_configure is instance-level and is not available in Azure SQL Database.", "diagram": "<svg viewBox='0 0 380 156' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-43-5'><title id='dt-p4-43-5'>Database-scoped configuration changes optimizer and execution options for one database only.</title><rect x='16' y='16' width='348' height='20' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><circle cx='28' cy='26' r='3' fill='var(--red)'/><circle cx='38' cy='26' r='3' fill='var(--amber)'/><circle cx='48' cy='26' r='3' fill='var(--green)'/><text x='190' y='30' font-size='7' fill='var(--muted)' text-anchor='middle'>T-SQL</text><rect x='16' y='36' width='348' height='72' rx='0' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='28' y='54' font-size='8' fill='var(--primary)' text-anchor='start' font-family='monospace' style='white-space:pre'>ALTER DATABASE SCOPED CONFIGURATION</text><text x='28' y='68' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>  SET MAXDOP = 4;</text><text x='28' y='82' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>ALTER DATABASE SCOPED CONFIGURATION</text><text x='28' y='96' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>  SET PARAMETER_SNIFFING = OFF;</text><text x='16' y='132' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Database-scoped configuration changes optimizer and execution options</text><text x='16' y='144' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>for one database only.</text></svg>" },
    { "id": "p4-43-6", "core": "core1", "domain": "p4", "objective": "4.3", "term": "Cost threshold for parallelism", "definition": "On SQL Server VMs and Managed Instance, this server setting decides how expensive a plan must be before it can go parallel; the default of 5 is usually raised (often to 50) so cheap queries stay serial, alongside a sensible MAXDOP and a max server memory that leaves room for the OS.", "scenario": "stop cheap queries from going parallel and generating excess parallelism waits by raising a server setting", "distractors": ["Setting MAXDOP to 0", "Lowering max server memory", "Optimize for ad hoc workloads"], "tip": "The default of 5 lets cheap queries go parallel — raising it keeps parallel plans for expensive queries.", "diagram": "<svg viewBox='0 0 380 170' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-43-6'><title id='dt-p4-43-6'>Raising the cost threshold for parallelism keeps cheap queries from going parallel.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Server settings that matter</text><rect x='16' y='30' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='43.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Cost threshold</text><text x='122' y='43.5' font-size='7.3' fill='var(--text)' text-anchor='start'>default 5, often raised to 50</text><rect x='16' y='54' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='67.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>MAXDOP</text><text x='122' y='67.5' font-size='7.3' fill='var(--text)' text-anchor='start'>limits threads per query</text><rect x='16' y='78' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='91.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Max server memory</text><text x='122' y='91.5' font-size='7.3' fill='var(--text)' text-anchor='start'>leave room for the OS</text><rect x='16' y='102' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='115.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Scope</text><text x='122' y='115.5' font-size='7.3' fill='var(--text)' text-anchor='start'>SQL Server VM and MI</text><text x='16' y='146' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Raising the cost threshold for parallelism keeps cheap queries from</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>going parallel.</text></svg>" },
    { "id": "p4-43-7", "core": "core1", "domain": "p4", "objective": "4.3", "term": "Intelligent query processing (IQP)", "definition": "A family of optimizer features that improve performance after raising the compatibility level, with little or no code change, including adaptive joins, memory grant feedback, table variable deferred compilation, batch mode on rowstore, scalar UDF inlining, and parameter sensitive plan optimization.", "scenario": "speed up queries after an upgrade by raising the compatibility level instead of rewriting them", "distractors": ["Automatic index creation", "Query Store forced plans", "Resource Governor"], "tip": "It is gated by COMPATIBILITY LEVEL — raise it and the features apply with no application change.", "diagram": "<svg viewBox='0 0 380 158' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-43-7'><title id='dt-p4-43-7'>IQP features improve existing queries automatically once the compatibility level is raised.</title><rect x='115' y='14' width='150' height='34' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.3'/><text x='190' y='27.86' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Intelligent query processing</text><text x='190' y='39.26' font-size='6.4' fill='var(--muted)' text-anchor='middle'>raise the compatibility level</text><line x1='190' y1='48' x2='70' y2='69.5' stroke='var(--border)' stroke-width='1.2'/><rect x='16' y='70' width='108' height='40' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='70' y='86.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Adaptive joins</text><text x='70' y='97.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>runtime join choice</text><line x1='190' y1='48' x2='190' y2='69.5' stroke='var(--border)' stroke-width='1.2'/><rect x='136' y='70' width='108' height='40' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='86.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Memory grant feedback</text><text x='190' y='97.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>right-sizes grants</text><line x1='190' y1='48' x2='310' y2='69.5' stroke='var(--border)' stroke-width='1.2'/><rect x='256' y='70' width='108' height='40' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='310' y='86.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>PSP optimization</text><text x='310' y='97.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>plans per parameter range</text><text x='16' y='134' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>IQP features improve existing queries automatically once the</text><text x='16' y='146' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>compatibility level is raised.</text></svg>" },
    { "id": "p4-43-8", "core": "core1", "domain": "p4", "objective": "4.3", "term": "Parameter sensitive plan (PSP) optimization", "definition": "At compatibility level 160 the optimizer can keep multiple cached plans for one parameterized query when parameter values have very different row counts, reducing parameter sniffing problems without hints.", "scenario": "reduce parameter sniffing without hints by letting a query keep different plans for small and large parameter values", "distractors": ["OPTION (RECOMPILE) on every query", "Forcing one plan in Query Store", "Clearing the plan cache hourly"], "tip": "Several plans for ONE query by parameter range — it needs compatibility level 160.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-43-8'><title id='dt-p4-43-8'>PSP optimization keeps different plans for different parameter ranges of the same query.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Parameter sensitive plans</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Before PSP</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>One cached plan</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Good for the first value</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Bad for skewed values</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>With PSP (level 160)</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Several plans per query</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Chosen by parameter range</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Fewer sniffing problems</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>PSP optimization keeps different plans for different parameter ranges of</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>the same query.</text></svg>" },
    { "id": "p4-43-9", "core": "core1", "domain": "p4", "objective": "4.3", "term": "Memory grant feedback", "definition": "The engine adjusts the memory grant for a repeated query based on earlier executions, shrinking over-grants and growing under-grants that spilled to tempdb (batch mode from compatibility level 140, row mode from 150).", "scenario": "stop a repeated query from spilling to tempdb because its memory grant is too small, without adding hints", "distractors": ["Adaptive joins", "Table variable deferred compilation", "Scalar UDF inlining"], "tip": "It learns from earlier EXECUTIONS to right-size the grant — both spills and over-grants shrink over time.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-43-9'><title id='dt-p4-43-9'>Memory grant feedback right-sizes a repeated query&#39;s memory grant based on earlier runs.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Memory grant feedback</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Run 1</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>grant too small, spill</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Feedback</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>engine adjusts the grant</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Run 2</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>right-sized, no spill</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Memory grant feedback right-sizes a repeated query&#39;s memory grant based</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>on earlier runs.</text></svg>" },
    { "id": "p4-43-10", "core": "core1", "domain": "p4", "objective": "4.3", "term": "Adaptive joins", "definition": "The optimizer defers the choice between a nested loops join and a hash join until runtime, using the actual row count of the build input, which helps queries whose input size varies; it applies to batch mode plans (compatibility level 140 and higher, including rowstore queries once batch mode on rowstore applies).", "scenario": "let one plan switch between nested loops and hash join depending on how many rows actually arrive", "distractors": ["Parameter sensitive plan optimization", "Memory grant feedback", "Forced parallelism"], "tip": "The JOIN type is chosen at RUNTIME from the real row count — PSP chooses between whole plans instead.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p4-43-10'><title id='dt-p4-43-10'>An adaptive join picks nested loops or hash join at runtime based on the actual row count.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Adaptive join</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Build input</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>rows counted at runtime</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Threshold check</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>few or many rows?</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Join chosen</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>nested loops or hash</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>An adaptive join picks nested loops or hash join at runtime based on the</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>actual row count.</text></svg>" },
    { "id": "p5-51-4", "core": "core1", "domain": "p5", "objective": "5.1", "term": "DACPAC/BACPAC deployment", "definition": "DACPAC packages a database's schema for deployment or comparison; BACPAC packages both schema and data, commonly used for exporting a database or deploying schema changes consistently.", "scenario": "deploy a consistent, version-controlled schema change to a database as part of an automated release process, without including the actual data", "distractors": ["ARM/Bicep templates (infrastructure)", "CI/CD pipeline (general)", "SQL Agent job"], "tip": "DACPAC packages SCHEMA ONLY, BACPAC includes DATA too — ARM/Bicep templates instead define the surrounding AZURE INFRASTRUCTURE the database runs on, a different layer entirely." , "diagram": "<svg viewBox='0 0 400 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-51-4'><title id='dt-p5-51-4'>DACPAC moves structure alone; BACPAC packages both structure and the data rows together.</title><rect x='16.0' y='30' width='179.0' height='64' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='105.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>DACPAC</text><text x='105.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>schema only</text><rect x='205.0' y='30' width='179.0' height='64' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='294.5' y='58.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>BACPAC</text><text x='294.5' y='72.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>schema + data</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>DACPAC moves structure alone; BACPAC packages both structure and the data rows</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>together.</text></svg>"},
    { "id": "p5-51-5", "core": "core1", "domain": "p5", "objective": "5.1", "term": "Database schema drift detection", "definition": "Comparing a database's actual live schema against its expected, source-controlled definition to catch unauthorized or undocumented manual changes.", "scenario": "detect that someone manually added a column directly to a production database outside of the normal, tracked deployment process", "distractors": ["DACPAC deployment", "CI/CD pipeline", "PowerShell automation"], "tip": "DETECTS undocumented DEVIATION from the expected schema — DACPAC deployment is the tool that PUSHES intended schema changes; drift detection instead catches changes that bypassed that process." , "diagram": "<svg viewBox='0 0 400 132' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-51-5'><title id='dt-p5-51-5'>Detects when a live database has diverged from its declared, version-controlled definition.</title><rect x='20' y='24' width='150' height='56' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='95' y='44' font-size='6.8' fill='var(--primary)' text-anchor='middle' font-weight='700'>Source of truth</text><text x='95' y='58' font-size='6.2' fill='var(--primary)' text-anchor='middle'>(template/repo)</text><rect x='210' y='24' width='150' height='56' rx='6' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.8' stroke-dasharray='2 2'/><text x='285' y='44' font-size='6.8' fill='var(--amber)' text-anchor='middle' font-weight='700'>Live database</text><text x='285' y='58' font-size='6.2' fill='var(--amber)' text-anchor='middle'>a column was added</text><text x='285' y='70' font-size='6.2' fill='var(--amber)' text-anchor='middle'>directly, out of band</text><text x='16' y='110' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Detects when a live database has diverged from its declared, version-controlled</text><text x='16' y='122' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>definition.</text></svg>"},
    { "id": "p5-51-6", "core": "core1", "domain": "p5", "objective": "5.1", "term": "Blue-green database deployment", "definition": "A deployment strategy using two parallel database environments, switching traffic from the old (blue) to the new (green) version after validation, minimizing downtime and easing rollback.", "scenario": "deploy a major schema change with minimal downtime and an easy rollback path if something goes wrong after the switch", "distractors": ["DACPAC deployment (single-environment)", "Schema drift detection", "CI/CD pipeline"], "tip": "Runs TWO PARALLEL environments and SWITCHES traffic after validation — a broader deployment STRATEGY, distinct from DACPAC which is the packaging FORMAT such a strategy might deploy with." , "diagram": "<svg viewBox='0 0 400 136' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-51-6'><title id='dt-p5-51-6'>Stages the new version fully before swapping traffic over, keeping rollback fast and simple.</title><rect x='20' y='24' width='150' height='56' rx='6' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.8'/><text x='95' y='44' font-size='7.3' fill='var(--blue)' text-anchor='middle' font-weight='700'>Blue</text><text x='95' y='58' font-size='6.2' fill='var(--blue)' text-anchor='middle'>current, live</text><line x1='172' y1='52' x2='204' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 48 L209 52 L202 56' fill='none' stroke='var(--muted)' stroke-width='1.5'/><text x='191' y='42' font-size='6' fill='var(--muted)' text-anchor='middle'>swap</text><rect x='210' y='24' width='150' height='56' rx='6' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.8'/><text x='285' y='44' font-size='7.3' fill='var(--green)' text-anchor='middle' font-weight='700'>Green</text><text x='285' y='58' font-size='6.2' fill='var(--green)' text-anchor='middle'>new version, staged</text><text x='16' y='114' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Stages the new version fully before swapping traffic over, keeping rollback fast and</text><text x='16' y='126' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>simple.</text></svg>"},
    { "id": "p5-51-7", "core": "core1", "domain": "p5", "objective": "5.1", "term": "What-if and incremental deployment mode", "definition": "The what-if operation previews which resources a Bicep or ARM deployment would create, change, or delete before it runs; Incremental mode (the default) adds or updates the resources in the template and leaves others alone, whereas Complete mode deletes resources that are not in the template.", "scenario": "preview a template deployment and make sure it cannot delete other resources in the resource group", "distractors": ["Complete deployment mode", "Running the template twice", "An Azure Resource Graph query"], "tip": "what-if SHOWS the changes first — Complete mode is the one that can delete things not in the template.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-51-7'><title id='dt-p5-51-7'>what-if previews changes; Incremental mode leaves other resources alone while Complete mode can delete them.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Deployment modes</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Incremental (default)</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Adds or updates resources</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Leaves other resources alone</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>The safe default</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Complete</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Makes the group match the template</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Deletes resources not listed</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Use with care</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>what-if previews changes; Incremental mode leaves other resources alone</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>while Complete mode can delete them.</text></svg>" },
    { "id": "p5-51-8", "core": "core1", "domain": "p5", "objective": "5.1", "term": "Azure PowerShell and Azure CLI commands", "definition": "New-AzSqlServer and New-AzSqlDatabase (Azure PowerShell) and az sql server create and az sql db create (Azure CLI) script the same operations imperatively, and both run in pipelines and Cloud Shell on any platform.", "scenario": "create a logical server and a database from a pipeline script using a cross-platform command-line tool", "distractors": ["SSMS Object Explorer", "The Azure portal blade", "A DACPAC deployment"], "tip": "Both are imperative command-line tools for Azure resources — templates are the declarative alternative.", "diagram": "<svg viewBox='0 0 380 142' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-51-8'><title id='dt-p5-51-8'>Azure PowerShell cmdlets and Azure CLI commands script resource creation from pipelines.</title><rect x='16' y='16' width='348' height='20' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><circle cx='28' cy='26' r='3' fill='var(--red)'/><circle cx='38' cy='26' r='3' fill='var(--amber)'/><circle cx='48' cy='26' r='3' fill='var(--green)'/><text x='190' y='30' font-size='7' fill='var(--muted)' text-anchor='middle'>Automation commands</text><rect x='16' y='36' width='348' height='58' rx='0' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='28' y='54' font-size='8' fill='var(--primary)' text-anchor='start' font-family='monospace' style='white-space:pre'>New-AzSqlDatabase -ServerName sql01 -DatabaseName Sales</text><text x='28' y='68' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>az sql db create -s sql01 -n Sales -g rg1</text><text x='28' y='82' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'># PowerShell cmdlets and CLI commands do the same job</text><text x='16' y='118' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Azure PowerShell cmdlets and Azure CLI commands script resource creation</text><text x='16' y='130' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>from pipelines.</text></svg>" },
    { "id": "p5-51-9", "core": "core1", "domain": "p5", "objective": "5.1", "term": "Troubleshooting a failed deployment", "definition": "Read the error code and message in the resource group's Deployments blade or the Activity log (for example a name already taken, a quota exceeded, or an invalid parameter), fix the template or parameter, and redeploy; what-if and validation catch many problems earlier.", "scenario": "find out why a Bicep deployment of a SQL logical server failed with a name conflict", "distractors": ["Query Store", "sys.dm_exec_requests", "SQL Agent job history"], "tip": "Deployment history and the ACTIVITY LOG show the failing operation and its error code.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-51-9'><title id='dt-p5-51-9'>The Deployments blade and Activity log reveal why a deployment failed; fix and redeploy.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Diagnosing a deployment</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Deployment fails</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>status shows Failed</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Read the error</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>Deployments, Activity log</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Fix and redeploy</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>template or parameter</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The Deployments blade and Activity log reveal why a deployment failed;</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>fix and redeploy.</text></svg>" },
    { "id": "p5-52-4", "core": "core1", "domain": "p5", "objective": "5.2", "term": "Ola Hallengren maintenance scripts", "definition": "A widely-used, free, open-source set of T-SQL scripts for automating index maintenance, integrity checks, and backups, commonly deployed via SQL Agent jobs as an alternative to built-in maintenance plans.", "scenario": "set up comprehensive, well-tested automated maintenance (index rebuilds, integrity checks, backups) using a trusted, widely-adopted community solution instead of building custom scripts from scratch", "distractors": ["Built-in automated index maintenance", "SQL Agent jobs (generic)", "LTR backups"], "tip": "A WIDELY-TRUSTED, PRE-BUILT community script set — saves writing and testing custom maintenance T-SQL from scratch, and is a very common real-world choice over built-in maintenance plans." , "diagram": "<svg viewBox='0 0 380 144' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-52-4'><title id='dt-p5-52-4'>Widely-used open-source scripts wrapping these three tasks into one scheduled job set.</title><rect x='8' y='20' width='104' height='30' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='60' y='39' font-size='6.2' fill='var(--text)' text-anchor='middle' font-weight='700'>Index maint.</text><line x1='60' y1='50' x2='60' y2='62' stroke='var(--muted)' stroke-width='1.5'/><path d='M56 60 L60 67 L64 60' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='138' y='20' width='104' height='30' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='39' font-size='6.2' fill='var(--text)' text-anchor='middle' font-weight='700'>Backups</text><line x1='190' y1='50' x2='190' y2='62' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 60 L190 67 L194 60' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='268' y='20' width='104' height='30' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='320' y='39' font-size='6.2' fill='var(--text)' text-anchor='middle' font-weight='700'>Integrity checks</text><line x1='320' y1='50' x2='320' y2='62' stroke='var(--muted)' stroke-width='1.5'/><path d='M316 60 L320 67 L324 60' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='90' y='70' width='200' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190' y='91' font-size='6.8' fill='var(--primary)' text-anchor='middle' font-weight='700'>Ola Hallengren scripts</text><text x='16' y='122' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Widely-used open-source scripts wrapping these three tasks into one scheduled</text><text x='16' y='134' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>job set.</text></svg>"},
    { "id": "p5-52-5", "core": "core1", "domain": "p5", "objective": "5.2", "term": "Database mail alerts", "definition": "Configuring SQL Server to send email notifications automatically when a scheduled job fails or a monitored condition, like low disk space, is detected.", "scenario": "get an email notification automatically the moment a critical nightly backup job fails", "distractors": ["SQL Agent jobs (the job itself)", "Automated index maintenance", "LTR backups"], "tip": "The NOTIFICATION layer ON TOP of jobs — a SQL Agent job runs the actual task; database mail is the separate piece that tells someone when that task succeeds or fails." , "diagram": "<svg viewBox='0 0 380 188' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-52-5'><title id='dt-p5-52-5'>Turns a job failure or alert condition into an email notification automatically.</title><rect x='16' y='14' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='25' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Job or alert condition met</text><text x='190.0' y='38' font-size='7.5' fill='var(--muted)' text-anchor='middle'>e.g. a backup job fails</text><line x1='190.0' y1='46' x2='190.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 50 L190.0 57 L194.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='69' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Database Mail sends notice</text><text x='190.0' y='82' font-size='7.5' fill='var(--muted)' text-anchor='middle'>via configured SMTP profile</text><line x1='190.0' y1='90' x2='190.0' y2='96' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 94 L190.0 101 L194.0 94' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='102' width='348' height='32' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='113' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Operator/DBA notified</text><text x='190.0' y='126' font-size='7.5' fill='var(--text)' text-anchor='middle'>can act before it becomes urgent</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Turns a job failure or alert condition into an email notification</text><text x='16' y='178' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>automatically.</text></svg>"},
    { "id": "p5-52-6", "core": "core1", "domain": "p5", "objective": "5.2", "term": "Auto-tuning: automatic index create/drop", "definition": "A specific automatic tuning capability that creates recommended indexes and drops unused, duplicate ones automatically, continuously adapting a database's indexing to its actual query workload.", "scenario": "let the database automatically create indexes it determines would help performance and drop ones that have gone unused, without manual DBA intervention", "distractors": ["Automated index maintenance (rebuild/reorganize)", "Missing index recommendations (manual)", "Ola Hallengren scripts"], "tip": "Automatically CREATES/DROPS indexes based on workload — distinct from maintenance that just REBUILDS/REORGANIZES indexes that ALREADY EXIST, a different kind of automation entirely." , "diagram": "<svg viewBox='0 0 380 194' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-52-6'><title id='dt-p5-52-6'>Azure can create and later drop indexes on its own, watching the real-world impact of each.</title><rect x='16' y='14' width='348' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='26' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Beneficial index detected</text><text x='190.0' y='39' font-size='7.5' fill='var(--muted)' text-anchor='middle'>would clearly help performance</text><line x1='190.0' y1='48' x2='190.0' y2='54' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 52 L190.0 59 L194.0 52' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='60' width='348' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='72' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Created automatically</text><text x='190.0' y='85' font-size='7.5' fill='var(--text)' text-anchor='middle'>no DBA action needed</text><line x1='190.0' y1='94' x2='190.0' y2='100' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 98 L190.0 105 L194.0 98' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='106' width='348' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='118' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Monitored, dropped if unused</text><text x='190.0' y='131' font-size='7.5' fill='var(--muted)' text-anchor='middle'>or if it doesn\u2019t help</text><text x='16' y='172' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Azure can create and later drop indexes on its own, watching the real-world</text><text x='16' y='184' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>impact of each.</text></svg>"},
    { "id": "p5-52-7", "core": "core1", "domain": "p5", "objective": "5.2", "term": "Elastic job target groups", "definition": "An elastic job agent runs T-SQL jobs against target groups, which can include or exclude servers, elastic pools, and individual databases, so one job fans out to many Azure SQL databases using database-scoped credentials or a managed identity.", "scenario": "run one T-SQL job against every database in two elastic pools and exclude a test database", "distractors": ["A SQL Server Agent job on the logical server", "A multi-statement table-valued function", "An Azure Data Factory copy activity"], "tip": "Target groups include or EXCLUDE servers, pools, and databases — Azure SQL Database has no SQL Server Agent.", "diagram": "<svg viewBox='0 0 380 158' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-52-7'><title id='dt-p5-52-7'>An elastic job fans one T-SQL job out to every server, pool, and database in its target group.</title><rect x='115' y='14' width='150' height='34' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.3'/><text x='190' y='27.86' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Elastic job</text><text x='190' y='39.26' font-size='6.4' fill='var(--muted)' text-anchor='middle'>T-SQL steps on a schedule</text><line x1='190' y1='48' x2='70' y2='69.5' stroke='var(--border)' stroke-width='1.2'/><rect x='16' y='70' width='108' height='40' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='70' y='86.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Server</text><text x='70' y='97.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>all its databases</text><line x1='190' y1='48' x2='190' y2='69.5' stroke='var(--border)' stroke-width='1.2'/><rect x='136' y='70' width='108' height='40' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='86.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Elastic pool</text><text x='190' y='97.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>every member</text><line x1='190' y1='48' x2='310' y2='69.5' stroke='var(--border)' stroke-width='1.2'/><rect x='256' y='70' width='108' height='40' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='310' y='86.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Database</text><text x='310' y='97.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>a single target</text><text x='16' y='134' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>An elastic job fans one T-SQL job out to every server, pool, and</text><text x='16' y='146' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>database in its target group.</text></svg>" },
    { "id": "p5-52-8", "core": "core1", "domain": "p5", "objective": "5.2", "term": "Azure Automation runbook", "definition": "A PowerShell or Python runbook in an Azure Automation account, started on a schedule or by a webhook and using a managed identity, can scale a database, start or stop resources, or run T-SQL for tasks that sit outside the database engine's own scheduler.", "scenario": "scale a database up every weekday morning and back down in the evening on a schedule", "distractors": ["A SQL Server Agent alert", "Query Store", "An elastic pool"], "tip": "It schedules Azure RESOURCE operations such as scaling — jobs inside the database run T-SQL.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-52-8'><title id='dt-p5-52-8'>An Automation runbook runs on a schedule to scale or manage Azure resources outside the database.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Scheduled scaling</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Schedule</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>morning and evening</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Runbook</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>Set-AzSqlDatabase</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Database scales</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>up, then down</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>An Automation runbook runs on a schedule to scale or manage Azure</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>resources outside the database.</text></svg>" },
    { "id": "p5-52-9", "core": "core1", "domain": "p5", "objective": "5.2", "term": "Action groups", "definition": "An Azure Monitor action group is a reusable list of notification and action targets, such as email, SMS, push, a webhook, a Logic App, or a Function, that alert rules call when they fire.", "scenario": "reuse one list of notification targets (email, SMS, and a webhook) across many alert rules", "distractors": ["A metric alert rule", "A diagnostic setting", "A SQL Server Agent operator"], "tip": "The WHO and HOW of notification — the alert rule decides WHEN to fire.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-52-9'><title id='dt-p5-52-9'>Action groups define who and how to notify when Azure Monitor alert rules fire.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Alert to action</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Alert rule</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>CPU above 90%</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Action group</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>email, SMS, webhook</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Responder</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>on-call DBA is paged</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Action groups define who and how to notify when Azure Monitor alert</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>rules fire.</text></svg>" },
    { "id": "p5-52-10", "core": "core1", "domain": "p5", "objective": "5.2", "term": "Troubleshooting automated tasks", "definition": "When a scheduled task fails, read the job or runbook history for the failing step and error, confirm credentials and permissions (job credential, managed identity), check firewall and network access, then rerun the step manually to isolate the cause.", "scenario": "find out why a scheduled maintenance task fails every night with a login error", "distractors": ["Raising the service tier", "Rebuilding tempdb", "Changing the connection policy to Redirect"], "tip": "History first, then identity and firewall — most scheduled-task failures are credentials or network, not the T-SQL.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-52-10'><title id='dt-p5-52-10'>Start with the failing step&#39;s history, then check identity and network access.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Troubleshooting a task</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Read history</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>failing step and error</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Check identity</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>credential, permissions</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Check access</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>firewall, network</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Start with the failing step&#39;s history, then check identity and network</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>access.</text></svg>" },
    { "id": "p5-53-1", "core": "core1", "domain": "p5", "objective": "5.3", "term": "SQL Server Agent jobs, steps, and schedules", "definition": "SQL Server Agent runs jobs made of steps (T-SQL, PowerShell, command line, and more) on schedules such as recurring, one-time, at Agent start, or when the CPU is idle; it exists on SQL Server and SQL Managed Instance but not in Azure SQL Database.", "scenario": "run a nightly backup and index maintenance as a multi-step scheduled job on a SQL Server VM or Managed Instance", "distractors": ["Elastic jobs", "An Azure Automation runbook", "A Windows scheduled task only"], "tip": "Jobs, steps, schedules — it exists on SQL Server and Managed Instance but NOT in Azure SQL Database.", "diagram": "<svg viewBox='0 0 380 158' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-53-1'><title id='dt-p5-53-1'>SQL Server Agent schedules multi-step jobs on SQL Server and Managed Instance, not Azure SQL Database.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Where Agent is available</text><rect x='16' y='30' width='174' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='103' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Offering</text><rect x='190' y='30' width='174' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='277' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>SQL Server Agent?</text><rect x='16' y='50' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='103' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>SQL Server on Azure VM</text><rect x='190' y='50' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='277' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>yes</text><rect x='16' y='70' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='103' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>Managed Instance</text><rect x='190' y='70' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='277' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>yes</text><rect x='16' y='90' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='103' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>Azure SQL Database</text><rect x='190' y='90' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='277' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>no, use elastic jobs</text><text x='16' y='134' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>SQL Server Agent schedules multi-step jobs on SQL Server and Managed</text><text x='16' y='146' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Instance, not Azure SQL Database.</text></svg>" },
    { "id": "p5-53-2", "core": "core1", "domain": "p5", "objective": "5.3", "term": "SQL Server Agent alerts and operators", "definition": "An alert fires on a SQL Server error number or severity, a performance condition, or a WMI event and then notifies an operator, usually by email through Database Mail, or runs a job; operators define who is notified and when.", "scenario": "email the DBA team whenever any error of severity 19 to 25 occurs", "distractors": ["A job schedule", "A proxy account", "A maintenance plan"], "tip": "The ALERT detects, the OPERATOR receives, and Database Mail delivers.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-53-2'><title id='dt-p5-53-2'>Agent alerts react to errors or conditions and notify operators through Database Mail.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Agent alerting</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Alert</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>severity 19 to 25</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Operator</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>DBA team on call</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Notification</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>Database Mail email</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Agent alerts react to errors or conditions and notify operators through</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Database Mail.</text></svg>" },
    { "id": "p5-53-3", "core": "core1", "domain": "p5", "objective": "5.3", "term": "Troubleshooting Agent job failures (history and proxies)", "definition": "Diagnose a failed job from its history (Job Activity Monitor or msdb.dbo.sysjobhistory), reading the step output and error; steps that need different credentials run under a proxy account, and the Agent service account's permissions are a common cause of failures.", "scenario": "diagnose a job step that fails with access denied when copying files from a network share", "distractors": ["Increasing MAXDOP", "Rebuilding statistics", "Running the job more often"], "tip": "Read the STEP output in job history, then check the account the step runs as — a proxy supplies another identity.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p5-53-3'><title id='dt-p5-53-3'>Job history shows the failing step; check which account it runs as and what that account may access.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Why a job step fails</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Job history</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>step output and error</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Run-as account</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>service account or proxy</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Permissions</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>share, folder, database</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Job history shows the failing step; check which account it runs as and</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>what that account may access.</text></svg>" },
    { "id": "p6-61-1", "core": "core1", "domain": "p6", "objective": "6.1", "term": "RPO and RTO to solution mapping", "definition": "The recovery point objective (acceptable data loss) and recovery time objective (acceptable downtime) pick the technology: zone redundancy for near-zero loss within a region, geo-replication or a failover group for seconds of loss across regions, point-in-time restore for same-region mistakes, and geo-restore when hours of loss and downtime are acceptable.", "scenario": "translate the stated tolerances for data loss and downtime into the matching Azure SQL resilience options", "distractors": ["Choosing the largest compute tier", "Adding read replicas", "Turning on Query Store"], "tip": "Tight RPO and RTO cost more — match the cheapest option that still meets BOTH numbers.", "diagram": "<svg viewBox='0 0 380 178' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-61-1'><title id='dt-p6-61-1'>RPO and RTO decide which Azure SQL resilience option fits, balancing protection against cost.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>From RPO and RTO to a design</text><rect x='16' y='30' width='174' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='103' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Requirement</text><rect x='190' y='30' width='174' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='277' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Typical option</text><rect x='16' y='50' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='103' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>Near-zero loss in region</text><rect x='190' y='50' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='277' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>zone-redundant tier</text><rect x='16' y='70' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='103' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>Seconds of loss, region failure</text><rect x='190' y='70' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='277' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>failover group</text><rect x='16' y='90' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='103' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>Undo a mistake, same region</text><rect x='190' y='90' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='277' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>point-in-time restore</text><rect x='16' y='110' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='103' y='123.2' font-size='7' fill='var(--text)' text-anchor='middle'>Hours of loss and downtime</text><rect x='190' y='110' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='277' y='123.2' font-size='7' fill='var(--text)' text-anchor='middle'>geo-restore</text><text x='16' y='154' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>RPO and RTO decide which Azure SQL resilience option fits, balancing</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>protection against cost.</text></svg>" },
    { "id": "p6-61-2", "core": "core1", "domain": "p6", "objective": "6.1", "term": "Planned failover", "definition": "A planned failover waits for the secondary to synchronize so no data is lost and is used for maintenance and DR drills, whereas a forced failover switches immediately when the primary is unavailable and can lose recent transactions.", "scenario": "fail over a failover group for a DR drill with no data loss while both regions are healthy", "distractors": ["Forced failover", "Geo-restore", "Point-in-time restore"], "tip": "PLANNED means no data loss and healthy regions — FORCED is for when the primary is gone and some loss is accepted.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-61-2'><title id='dt-p6-61-2'>A planned failover loses no data and needs healthy regions; a forced failover accepts data loss.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Failover types</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Planned failover</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Waits for synchronization</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>No data loss</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Drills and maintenance</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Forced failover</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Switches immediately</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Recent data may be lost</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Primary is unavailable</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A planned failover loses no data and needs healthy regions; a forced</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>failover accepts data loss.</text></svg>" },
    { "id": "p6-61-3", "core": "core1", "domain": "p6", "objective": "6.1", "term": "DR testing procedure", "definition": "A written, scheduled test: define success criteria from the RPO and RTO, perform a planned failover in a maintenance window, validate application connectivity through the listener or failover group endpoint, measure the real RTO and RPO, document the results, and fail back.", "scenario": "prove that the DR design really meets the agreed RTO before an outage happens", "distractors": ["Reading the SLA document", "Running DBCC CHECKDB", "Taking another full backup"], "tip": "An untested plan is a hope — measure the real RTO and RPO in a drill and document the result.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-61-3'><title id='dt-p6-61-3'>Regular DR drills measure the real RTO and RPO and give you a documented, rehearsed procedure.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>A DR drill</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Plan</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>criteria and window</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Fail over</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>validate the apps</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Measure, fail back</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>document RTO and RPO</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Regular DR drills measure the real RTO and RPO and give you a</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>documented, rehearsed procedure.</text></svg>" },
    { "id": "p6-61-4", "core": "core1", "domain": "p6", "objective": "6.1", "term": "Geo-restore", "definition": "Restoring an Azure SQL Database from geo-redundant backup copies into any region when the primary region is unavailable and no geo-replica exists; it is the lowest-cost recovery option but has the longest RTO (up to about 12 hours) and an RPO of up to about an hour.", "scenario": "recover in another region after a regional outage when no geo-replica or failover group was configured", "distractors": ["Point-in-time restore in the same region", "Active geo-replication", "Zone-redundant configuration"], "tip": "Cheapest but slowest — roughly an hour of RPO and up to about 12 hours of RTO; geo-replication is the fast option.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-61-4'><title id='dt-p6-61-4'>Geo-restore rebuilds a database in another region from geo-redundant backups, slowly and cheaply.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Geo-restore</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Regional outage</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>primary unavailable</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Geo-restore</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>from geo-redundant backup</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>New database</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>in another region</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Geo-restore rebuilds a database in another region from geo-redundant</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>backups, slowly and cheaply.</text></svg>" },
    { "id": "p6-62-1", "core": "core1", "domain": "p6", "objective": "6.2", "term": "FULL recovery model", "definition": "The FULL recovery model logs every operation and keeps the log until it is backed up, which allows transaction log backups and point-in-time restore; SIMPLE truncates the log automatically and permits neither, and BULK_LOGGED minimally logs bulk operations.", "scenario": "configure a database so the log can be backed up every five minutes and restored to any moment", "distractors": ["SIMPLE recovery model", "BULK_LOGGED recovery model", "Differential backups only"], "tip": "FULL is what makes LOG backups and point-in-time restore possible — SIMPLE gives up both.", "diagram": "<svg viewBox='0 0 380 158' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-62-1'><title id='dt-p6-62-1'>FULL recovery enables log backups and point-in-time restore; SIMPLE does not.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Recovery models</text><rect x='16' y='30' width='104.4' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='68.2' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Model</text><rect x='120.4' y='30' width='104.4' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='172.6' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Log backups</text><rect x='224.8' y='30' width='139.2' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='294.4' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Point-in-time restore</text><rect x='16' y='50' width='104.4' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='68.2' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>FULL</text><rect x='120.4' y='50' width='104.4' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='172.6' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>yes</text><rect x='224.8' y='50' width='139.2' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='294.4' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>yes</text><rect x='16' y='70' width='104.4' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='68.2' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>BULK_LOGGED</text><rect x='120.4' y='70' width='104.4' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='172.6' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>yes</text><rect x='224.8' y='70' width='139.2' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='294.4' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>limited</text><rect x='16' y='90' width='104.4' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='68.2' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>SIMPLE</text><rect x='120.4' y='90' width='104.4' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='172.6' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>no</text><rect x='224.8' y='90' width='139.2' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='294.4' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>no</text><text x='16' y='134' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>FULL recovery enables log backups and point-in-time restore; SIMPLE does</text><text x='16' y='146' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>not.</text></svg>" },
    { "id": "p6-62-2", "core": "core1", "domain": "p6", "objective": "6.2", "term": "Full, differential, and log backup chain", "definition": "A full backup captures everything, a differential captures changes since the last full, and log backups capture transactions since the last log backup; a restore needs the full, the latest differential, then each log in order, and the log backup interval sets the RPO.", "scenario": "design weekly full, daily differential, and 10-minute log backups so that at most about ten minutes of data can be lost", "distractors": ["Nightly full backups only", "A snapshot every hour", "A differential backup every minute"], "tip": "The LOG backup interval sets the RPO, and a restore needs the chain in order.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-62-2'><title id='dt-p6-62-2'>Full, differential, and log backups together allow restores to a point in time; the log interval sets the RPO.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>A backup strategy</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Full</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>weekly</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Differential</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>daily</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Log</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>every 10 minutes</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Full, differential, and log backups together allow restores to a point</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>in time; the log interval sets the RPO.</text></svg>" },
    { "id": "p6-62-3", "core": "core1", "domain": "p6", "objective": "6.2", "term": "Automated backups in Azure SQL", "definition": "Azure SQL Database and Managed Instance take backups automatically: a full backup weekly, differential backups every 12 or 24 hours, and log backups about every 10 minutes, supporting point-in-time restore within a retention of 1 to 35 days (7 by default).", "scenario": "explain which backups Azure SQL Database takes without any configuration, and how often", "distractors": ["Backups only when an administrator runs them", "A daily full backup and nothing else", "A snapshot every minute"], "tip": "Weekly full, 12 or 24-hour differential, and about 10-minute log — there is nothing to schedule.", "diagram": "<svg viewBox='0 0 380 170' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-62-3'><title id='dt-p6-62-3'>Azure SQL takes weekly full, 12- or 24-hour differential, and roughly 10-minute log backups automatically.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Automated backup schedule</text><rect x='16' y='30' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='43.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Full</text><text x='122' y='43.5' font-size='7.3' fill='var(--text)' text-anchor='start'>weekly</text><rect x='16' y='54' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='67.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Differential</text><text x='122' y='67.5' font-size='7.3' fill='var(--text)' text-anchor='start'>every 12 or 24 hours</text><rect x='16' y='78' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='91.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Log</text><text x='122' y='91.5' font-size='7.3' fill='var(--text)' text-anchor='start'>about every 10 minutes</text><rect x='16' y='102' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='115.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>PITR retention</text><text x='122' y='115.5' font-size='7.3' fill='var(--text)' text-anchor='start'>1 to 35 days, 7 by default</text><text x='16' y='146' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Azure SQL takes weekly full, 12- or 24-hour differential, and roughly</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>10-minute log backups automatically.</text></svg>" },
    { "id": "p6-62-4", "core": "core1", "domain": "p6", "objective": "6.2", "term": "Long-term retention policy (W, M, Y)", "definition": "A long-term retention policy keeps full backups for up to 10 years using weekly (W), monthly (M), and yearly (Y) retention settings plus the week of the year to keep; restoring from one creates a new database.", "scenario": "keep a yearly full backup for seven years to meet a compliance requirement", "distractors": ["Raising point-in-time retention to 35 days", "Geo-redundant backup storage", "Active geo-replication"], "tip": "PITR tops out at 35 days — compliance retention needs the LTR policy.", "diagram": "<svg viewBox='0 0 380 170' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-62-4'><title id='dt-p6-62-4'>An LTR policy sets weekly, monthly, and yearly retention, up to 10 years, for compliance.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>LTR policy settings</text><rect x='16' y='30' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='43.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>W</text><text x='122' y='43.5' font-size='7.3' fill='var(--text)' text-anchor='start'>weeks to keep weekly fulls</text><rect x='16' y='54' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='67.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>M</text><text x='122' y='67.5' font-size='7.3' fill='var(--text)' text-anchor='start'>months to keep monthly fulls</text><rect x='16' y='78' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='91.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Y</text><text x='122' y='91.5' font-size='7.3' fill='var(--text)' text-anchor='start'>years to keep a yearly full</text><rect x='16' y='102' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='115.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>WeekOfYear</text><text x='122' y='115.5' font-size='7.3' fill='var(--text)' text-anchor='start'>which week is the yearly</text><text x='16' y='146' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>An LTR policy sets weekly, monthly, and yearly retention, up to 10</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>years, for compliance.</text></svg>" },
    { "id": "p6-62-5", "core": "core1", "domain": "p6", "objective": "6.2", "term": "RESTORE ... STOPAT", "definition": "On SQL Server and Managed Instance, restore the full, any differential, and log backups WITH NORECOVERY, apply the final log with STOPAT to stop just before the mistake, then finish WITH RECOVERY to bring the database online.", "scenario": "restore a database to 14:32, one minute before an accidental DELETE, using native backups", "distractors": ["RESTORE ... WITH RECOVERY on the first file", "RESTORE VERIFYONLY", "DBCC CHECKDB"], "tip": "NORECOVERY until the last log, STOPAT before the error, then RECOVERY — recover too early and you cannot continue the chain.", "diagram": "<svg viewBox='0 0 380 142' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-62-5'><title id='dt-p6-62-5'>STOPAT replays logs up to a chosen moment; NORECOVERY keeps the chain open until the last step.</title><rect x='16' y='16' width='348' height='20' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><circle cx='28' cy='26' r='3' fill='var(--red)'/><circle cx='38' cy='26' r='3' fill='var(--amber)'/><circle cx='48' cy='26' r='3' fill='var(--green)'/><text x='190' y='30' font-size='7' fill='var(--muted)' text-anchor='middle'>T-SQL</text><rect x='16' y='36' width='348' height='58' rx='0' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='28' y='54' font-size='8' fill='var(--primary)' text-anchor='start' font-family='monospace' style='white-space:pre'>RESTORE DATABASE Sales FROM DISK = ... WITH NORECOVERY;</text><text x='28' y='68' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>RESTORE LOG Sales FROM DISK = ...</text><text x='28' y='82' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>  WITH STOPAT = &#39;2026-10-04 14:32&#39;, RECOVERY;</text><text x='16' y='118' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>STOPAT replays logs up to a chosen moment; NORECOVERY keeps the chain</text><text x='16' y='130' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>open until the last step.</text></svg>" },
    { "id": "p6-62-6", "core": "core1", "domain": "p6", "objective": "6.2", "term": "Tail-log backup", "definition": "A log backup taken before restoring (BACKUP LOG ... WITH NORECOVERY, or NO_TRUNCATE if the database is damaged) that captures transactions not yet backed up, so the restore can reach the latest possible point.", "scenario": "capture the last transactions from a damaged database before starting a restore so no committed data is lost", "distractors": ["A differential backup", "A COPY_ONLY full backup", "A snapshot"], "tip": "Back up the log FIRST — otherwise the most recent transactions are lost when you restore over the database.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-62-6'><title id='dt-p6-62-6'>A tail-log backup saves the final transactions before a restore so no committed data is lost.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Tail-log backup</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Database fails</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>log still readable</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Tail-log backup</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>NORECOVERY or NO_TRUNCATE</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Restore chain</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>full, diff, logs, tail</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A tail-log backup saves the final transactions before a restore so no</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>committed data is lost.</text></svg>" },
    { "id": "p6-62-7", "core": "core1", "domain": "p6", "objective": "6.2", "term": "Backup to URL (Blob storage)", "definition": "BACKUP ... TO URL writes backups directly to Azure Blob storage using a credential (a shared access signature or a managed identity), giving off-site storage without local disks, and RESTORE ... FROM URL reads them back.", "scenario": "send SQL Server backups straight to Azure Blob storage for off-site retention", "distractors": ["A backup to a local tape drive", "Log shipping", "A BACPAC export"], "tip": "The destination is a BLOB URL with a credential — the backup goes off-site without local disks.", "diagram": "<svg viewBox='0 0 380 142' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-62-7'><title id='dt-p6-62-7'>Backup to URL writes native backups straight to Blob storage using a credential.</title><rect x='16' y='16' width='348' height='20' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><circle cx='28' cy='26' r='3' fill='var(--red)'/><circle cx='38' cy='26' r='3' fill='var(--amber)'/><circle cx='48' cy='26' r='3' fill='var(--green)'/><text x='190' y='30' font-size='7' fill='var(--muted)' text-anchor='middle'>T-SQL</text><rect x='16' y='36' width='348' height='58' rx='0' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='28' y='54' font-size='8' fill='var(--primary)' text-anchor='start' font-family='monospace' style='white-space:pre'>CREATE CREDENTIAL [https://acct.blob.core.windows.net/bk]</text><text x='28' y='68' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>  WITH IDENTITY = &#39;SHARED ACCESS SIGNATURE&#39;, SECRET = &#39;...&#39;;</text><text x='28' y='82' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>BACKUP DATABASE Sales TO URL = &#39;.../Sales.bak&#39;;</text><text x='16' y='118' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Backup to URL writes native backups straight to Blob storage using a</text><text x='16' y='130' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>credential.</text></svg>" },
    { "id": "p6-62-8", "core": "core1", "domain": "p6", "objective": "6.2", "term": "Restoring a deleted database", "definition": "Azure SQL Database and Managed Instance can restore a dropped database from automated backups within the retention period, creating a new database as of the time it was deleted.", "scenario": "recover a database that was dropped by mistake yesterday", "distractors": ["A failover to the geo-replica", "Changing the compatibility level", "Moving it into an elastic pool"], "tip": "It works only within the retention period, from the automated backups — it creates a NEW database.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-62-8'><title id='dt-p6-62-8'>A dropped database can be restored from automated backups within the retention window.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Undeleting a database</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Database dropped</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>by mistake</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Restore deleted</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>from automated backups</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>New database</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>as of deletion time</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A dropped database can be restored from automated backups within the</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>retention window.</text></svg>" },
    { "id": "p6-62-9", "core": "core1", "domain": "p6", "objective": "6.2", "term": "Restore testing and RESTORE VERIFYONLY", "definition": "RESTORE VERIFYONLY (with CHECKSUM) confirms a backup file is readable and complete, but only an actual test restore to another server followed by DBCC CHECKDB proves the data can really be recovered.", "scenario": "prove that last night's backup can actually be restored and the data inside is intact", "distractors": ["Counting the backup files", "Checking the backup size", "Reading the SQL error log"], "tip": "VERIFYONLY checks readability — only a test RESTORE plus CHECKDB proves the backup works.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-62-9'><title id='dt-p6-62-9'>A test restore plus an integrity check is the only real proof a backup works.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Proving a backup</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Test restore</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>on another server</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>DBCC CHECKDB</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>verify integrity</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Record the time</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>compare with RTO</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A test restore plus an integrity check is the only real proof a backup</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>works.</text></svg>" },
    { "id": "p6-63-1", "core": "core1", "domain": "p6", "objective": "6.3", "term": "Always On availability group", "definition": "A set of databases that fail over together between replicas on separate servers, each holding its own copy of the data; one primary accepts writes, secondaries can be readable, a listener gives clients one name, and automatic failover needs synchronous commit.", "scenario": "protect a set of databases on SQL Server VMs with separate data copies and automatic failover", "distractors": ["A failover cluster instance", "Log shipping", "Active geo-replication"], "tip": "Separate COPIES of the data on separate servers — a failover cluster instance shares one copy of the storage.", "diagram": "<svg viewBox='0 0 380 158' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-63-1'><title id='dt-p6-63-1'>An availability group keeps separate database copies on replicas and fails them over together.</title><rect x='115' y='14' width='150' height='34' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.3'/><text x='190' y='27.86' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Availability group</text><text x='190' y='39.26' font-size='6.4' fill='var(--muted)' text-anchor='middle'>databases fail over together</text><line x1='190' y1='48' x2='70' y2='69.5' stroke='var(--border)' stroke-width='1.2'/><rect x='16' y='70' width='108' height='40' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='70' y='86.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Primary</text><text x='70' y='97.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>accepts writes</text><line x1='190' y1='48' x2='190' y2='69.5' stroke='var(--border)' stroke-width='1.2'/><rect x='136' y='70' width='108' height='40' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='86.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Synchronous secondary</text><text x='190' y='97.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>automatic failover</text><line x1='190' y1='48' x2='310' y2='69.5' stroke='var(--border)' stroke-width='1.2'/><rect x='256' y='70' width='108' height='40' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='310' y='86.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Asynchronous secondary</text><text x='310' y='97.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>remote DR copy</text><text x='16' y='134' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>An availability group keeps separate database copies on replicas and</text><text x='16' y='146' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>fails them over together.</text></svg>" },
    { "id": "p6-63-2", "core": "core1", "domain": "p6", "objective": "6.3", "term": "Asynchronous commit", "definition": "With asynchronous commit the primary does not wait for the secondary to harden the log before committing, giving lower latency across distance but possible data loss on failover; synchronous commit waits and is required for automatic failover.", "scenario": "choose the commit mode for a replica in a distant region where latency must stay low and some data loss is acceptable", "distractors": ["Synchronous commit", "Automatic failover mode", "Read-only routing"], "tip": "ASYNC trades possible data loss for low latency — synchronous is for nearby replicas that need automatic failover.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-63-2'><title id='dt-p6-63-2'>Asynchronous commit favors latency over zero data loss and suits distant replicas.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Commit modes</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Synchronous</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Waits for the secondary</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>No data loss</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Automatic failover possible</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Asynchronous</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Does not wait</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Possible data loss</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Suits remote regions</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Asynchronous commit favors latency over zero data loss and suits distant</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>replicas.</text></svg>" },
    { "id": "p6-63-3", "core": "core1", "domain": "p6", "objective": "6.3", "term": "Availability group listener", "definition": "A virtual network name and IP that clients connect to so they always reach the current primary; on Azure VMs it uses a load balancer or a distributed network name (DNN), and read-only routing can send read-intent connections to a readable secondary.", "scenario": "give applications one connection string that always points to the current primary after a failover", "distractors": ["The primary replica's computer name", "A DNS record that someone updates by hand", "A linked server"], "tip": "ONE name that follows the primary — on Azure VMs it needs a load balancer or a DNN.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-63-3'><title id='dt-p6-63-3'>The listener gives clients one name that always resolves to the current primary replica.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Listener</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Clients</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>connect to the listener</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Listener</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>load balancer or DNN</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Current primary</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>follows each failover</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The listener gives clients one name that always resolves to the current</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>primary replica.</text></svg>" },
    { "id": "p6-63-4", "core": "core1", "domain": "p6", "objective": "6.3", "term": "Failover cluster instance (FCI) on Azure VMs", "definition": "A Windows Server Failover Cluster hosts one SQL Server instance that moves between nodes using shared storage (Azure shared disks, premium file shares, or Storage Spaces Direct); it protects the whole instance against node failure, but there is only one copy of the data.", "scenario": "provide instance-level failover on Azure VMs using shared storage, protecting logins and jobs along with the databases", "distractors": ["An availability group", "Log shipping", "Active geo-replication"], "tip": "One INSTANCE moving between nodes on shared storage — an availability group keeps separate copies of the databases.", "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-63-4'><title id='dt-p6-63-4'>An FCI moves one instance between nodes on shared storage; an availability group keeps separate copies.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>FCI vs availability group</text><rect x='16' y='30' width='168' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='100' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Failover cluster instance</text><rect x='16' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>One instance, shared storage</text><rect x='16' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Protects the whole instance</text><rect x='16' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='100' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Single copy of the data</text><rect x='196' y='30' width='168' height='20' rx='4' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.3'/><text x='280' y='43.5' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Availability group</text><rect x='196' y='54' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='66.5' font-size='7' fill='var(--text)' text-anchor='middle'>Separate copies per replica</text><rect x='196' y='76' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='88.5' font-size='7' fill='var(--text)' text-anchor='middle'>Protects selected databases</text><rect x='196' y='98' width='168' height='19' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.1'/><text x='280' y='110.5' font-size='7' fill='var(--text)' text-anchor='middle'>Each node has its own storage</text><text x='16' y='141' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>An FCI moves one instance between nodes on shared storage; an</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>availability group keeps separate copies.</text></svg>" },
    { "id": "p6-63-5", "core": "core1", "domain": "p6", "objective": "6.3", "term": "Log shipping", "definition": "Automatically backs up the transaction log on a primary, copies it to one or more secondaries, and restores it there on a schedule; simple and usable across Azure and on-premises, but failover is manual and the RPO depends on the interval.", "scenario": "maintain a warm standby copy of a database that is refreshed every 15 minutes and failed over manually", "distractors": ["An availability group with automatic failover", "A failover cluster instance", "Zone redundancy"], "tip": "Backup, copy, and restore jobs on a schedule — failover is manual and the RPO equals the interval.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-63-5'><title id='dt-p6-63-5'>Log shipping backs up, copies, and restores logs on a schedule to keep a warm standby.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Log shipping</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Backup job</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>primary log backup</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Copy job</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>to the secondary</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Restore job</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>NORECOVERY or STANDBY</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Log shipping backs up, copies, and restores logs on a schedule to keep a</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>warm standby.</text></svg>" },
    { "id": "p6-63-6", "core": "core1", "domain": "p6", "objective": "6.3", "term": "Failover group grace period and policy", "definition": "A failover group can fail over manually or automatically; with the automatic policy, the grace period sets how long the service tries to recover the primary before forcing a failover that may lose recent data, one hour by default.", "scenario": "configure how long Azure waits before automatically forcing a failover that may lose data", "distractors": ["The read-only listener", "A planned failover", "Backup retention"], "tip": "The GRACE PERIOD is how long recovery is attempted before a forced failover — it ties the policy to your acceptable data loss.", "diagram": "<svg viewBox='0 0 380 170' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-63-6'><title id='dt-p6-63-6'>The grace period controls how long Azure waits before forcing an automatic failover.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Failover group settings</text><rect x='16' y='30' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='43.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Policy</text><text x='122' y='43.5' font-size='7.3' fill='var(--text)' text-anchor='start'>manual or automatic</text><rect x='16' y='54' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='67.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Grace period</text><text x='122' y='67.5' font-size='7.3' fill='var(--text)' text-anchor='start'>wait before a forced failover</text><rect x='16' y='78' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='91.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Default</text><text x='122' y='91.5' font-size='7.3' fill='var(--text)' text-anchor='start'>one hour</text><rect x='16' y='102' width='96' height='20' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.2'/><text x='64' y='115.5' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Trade-off</text><text x='122' y='115.5' font-size='7.3' fill='var(--text)' text-anchor='start'>shorter risks more data loss</text><text x='16' y='146' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The grace period controls how long Azure waits before forcing an</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>automatic failover.</text></svg>" },
    { "id": "p6-63-7", "core": "core1", "domain": "p6", "objective": "6.3", "term": "WSFC quorum and Cloud Witness", "definition": "Failover clusters (FCI and availability groups) depend on Windows Server Failover Clustering quorum, meaning a majority of votes must be online; on Azure a Cloud Witness, a small blob in a storage account, is an easy tie-breaker vote for clusters with an even number of nodes.", "scenario": "add a tie-breaking vote to a two-node cluster on Azure VMs without building a third server", "distractors": ["A file share on one of the nodes", "A third SQL Server replica", "An extra load balancer"], "tip": "Quorum is a MAJORITY of votes — a Cloud Witness blob is the simple extra vote on Azure.", "diagram": "<svg viewBox='0 0 380 124' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-63-7'><title id='dt-p6-63-7'>A Cloud Witness gives an Azure cluster a tie-breaking vote so quorum survives a node failure.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Cloud Witness</text><rect x='16' y='30' width='105.333' height='46' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='68.6667' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Two nodes</text><text x='68.6667' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>one vote each</text><line x1='123.333' y1='53' x2='135.333' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M131.333 50 L135.333 53 L131.333 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='137.333' y='30' width='105.333' height='46' rx='4' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='190' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Cloud Witness</text><text x='190' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>a blob adds a third vote</text><line x1='244.667' y1='53' x2='256.667' y2='53' stroke='var(--muted)' stroke-width='1.3'/><path d='M252.667 50 L256.667 53 L252.667 56' fill='none' stroke='var(--muted)' stroke-width='1.3'/><rect x='258.667' y='30' width='105.333' height='46' rx='4' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.3'/><text x='311.333' y='49.986' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Quorum kept</text><text x='311.333' y='60.686' font-size='6.4' fill='var(--muted)' text-anchor='middle'>one node can fail</text><text x='16' y='100' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A Cloud Witness gives an Azure cluster a tie-breaking vote so quorum</text><text x='16' y='112' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>survives a node failure.</text></svg>" },
    { "id": "p6-63-8", "core": "core1", "domain": "p6", "objective": "6.3", "term": "AG health DMVs and queues", "definition": "sys.dm_hadr_database_replica_states and the availability group dashboard show synchronization_state, log_send_queue_size, and redo_queue_size; a growing log send queue points to network or throughput trouble, and a growing redo queue to a secondary that applies logs slowly.", "scenario": "tell whether a secondary is behind because of network throughput or because of slow log redo", "distractors": ["sys.dm_exec_requests", "sys.dm_db_index_usage_stats", "Query Store runtime statistics"], "tip": "LOG SEND queue means the network or send side; REDO queue means the secondary is slow to apply.", "diagram": "<svg viewBox='0 0 380 158' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-63-8'><title id='dt-p6-63-8'>The send and redo queues show whether a lagging secondary has a network or a redo problem.</title><text x='190' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Reading AG health</text><rect x='16' y='30' width='174' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='103' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Indicator</text><rect x='190' y='30' width='174' height='20' rx='0' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.2'/><text x='277' y='43.5' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Points to</text><rect x='16' y='50' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='103' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>log_send_queue_size</text><rect x='190' y='50' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='277' y='63.2' font-size='7' fill='var(--text)' text-anchor='middle'>network or send rate</text><rect x='16' y='70' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='103' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>redo_queue_size</text><rect x='190' y='70' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='277' y='83.2' font-size='7' fill='var(--text)' text-anchor='middle'>slow redo on the secondary</text><rect x='16' y='90' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='103' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>synchronization_state</text><rect x='190' y='90' width='174' height='20' rx='0' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.0'/><text x='277' y='103.2' font-size='7' fill='var(--text)' text-anchor='middle'>SYNCHRONIZED or not</text><text x='16' y='134' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The send and redo queues show whether a lagging secondary has a network</text><text x='16' y='146' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>or a redo problem.</text></svg>" },
    { "id": "p6-63-9", "core": "core1", "domain": "p6", "objective": "6.3", "term": "Geo-replication lag monitoring", "definition": "sys.dm_geo_replication_link_status reports replication state and replication_lag_sec for active geo-replication, and the portal shows failover group status; alerting on lag shows whether the agreed RPO is still being met.", "scenario": "verify that geo-replication lag is still within the agreed RPO", "distractors": ["sys.dm_db_resource_stats", "sys.dm_exec_sessions", "sys.dm_os_wait_stats"], "tip": "Replication LAG is your live RPO — alert on it.", "diagram": "<svg viewBox='0 0 380 142' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-63-9'><title id='dt-p6-63-9'>Replication lag from the geo-replication DMV shows how much data a failover could lose right now.</title><rect x='16' y='16' width='348' height='20' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><circle cx='28' cy='26' r='3' fill='var(--red)'/><circle cx='38' cy='26' r='3' fill='var(--amber)'/><circle cx='48' cy='26' r='3' fill='var(--green)'/><text x='190' y='30' font-size='7' fill='var(--muted)' text-anchor='middle'>T-SQL</text><rect x='16' y='36' width='348' height='58' rx='0' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='28' y='54' font-size='8' fill='var(--primary)' text-anchor='start' font-family='monospace' style='white-space:pre'>SELECT partner_server, replication_lag_sec</text><text x='28' y='68' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>FROM sys.dm_geo_replication_link_status;</text><text x='28' y='82' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>-- compare the lag with the agreed RPO</text><text x='16' y='118' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Replication lag from the geo-replication DMV shows how much data a</text><text x='16' y='130' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>failover could lose right now.</text></svg>" },
    { "id": "p6-63-10", "core": "core1", "domain": "p6", "objective": "6.3", "term": "Log growth from a lagging replica", "definition": "A primary's transaction log can keep growing, even with log backups running, because it cannot truncate log records a lagging or disconnected secondary still needs; log_reuse_wait_desc shows AVAILABILITY_REPLICA, and the fix is to restore the replica's health.", "scenario": "explain why the log on an availability group primary keeps growing even though log backups run on schedule", "distractors": ["A missing index", "Stale statistics", "A deadlock"], "tip": "Check log_reuse_wait_desc — AVAILABILITY_REPLICA means a lagging replica is holding the log.", "diagram": "<svg viewBox='0 0 380 142' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-p6-63-10'><title id='dt-p6-63-10'>A lagging or disconnected replica prevents log truncation, so the primary log grows until it recovers.</title><rect x='16' y='16' width='348' height='20' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><circle cx='28' cy='26' r='3' fill='var(--red)'/><circle cx='38' cy='26' r='3' fill='var(--amber)'/><circle cx='48' cy='26' r='3' fill='var(--green)'/><text x='190' y='30' font-size='7' fill='var(--muted)' text-anchor='middle'>T-SQL</text><rect x='16' y='36' width='348' height='58' rx='0' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='28' y='54' font-size='8' fill='var(--primary)' text-anchor='start' font-family='monospace' style='white-space:pre'>SELECT name, log_reuse_wait_desc</text><text x='28' y='68' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>FROM sys.databases;</text><text x='28' y='82' font-size='7.5' fill='var(--text)' text-anchor='start' font-family='monospace' style='white-space:pre'>-- AVAILABILITY_REPLICA: a replica is behind</text><text x='16' y='118' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A lagging or disconnected replica prevents log truncation, so the</text><text x='16' y='130' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>primary log grows until it recovers.</text></svg>" }
